#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main(){int t;scanf("%d",&t);while(t--){int n;ll ax,ay,bx,by;scanf("%d %lld %lld %lld %lld",&n,&ax,&ay,&bx,&by);
 vector<ll> x(n),y(n);for(auto&v:x)scanf("%lld",&v);for(auto&v:y)scanf("%lld",&v);
 map<ll,pair<ll,ll>> col;
 for(int i=0;i<n;i++){auto it=col.find(x[i]);if(it==col.end())col[x[i]]={y[i],y[i]};
  else{it->second.first=min(it->second.first,y[i]);it->second.second=max(it->second.second,y[i]);}}
 ll p1=ay,c1=0,p2=ay,c2=0; // two states: position, cost
 for(auto&[cx,lh]:col){ll lo=lh.first,hi=lh.second,len=hi-lo;
  ll eLo=min(c1+llabs(p1-hi),c2+llabs(p2-hi))+len;
  ll eHi=min(c1+llabs(p1-lo),c2+llabs(p2-lo))+len;
  p1=lo;c1=eLo;p2=hi;c2=eHi;}
 printf("%lld\n",(bx-ax)+min(c1+llabs(p1-by),c2+llabs(p2-by)));}}

