#include <bits/stdc++.h>
using namespace std;
int main(){int n,w,h;scanf("%d %d %d",&n,&w,&h);vector<array<int,3>> e;
 for(int i=1;i<=n;i++){int a,b;scanf("%d %d",&a,&b);if(a>w&&b>h)e.push_back({a,b,i});}
 if(e.empty()){puts("0");return 0;}
 sort(e.begin(),e.end());int m=e.size();vector<int> dp(m,1),par(m,-1);int best=0;
 for(int i=0;i<m;i++){for(int j=0;j<i;j++)if(e[j][0]<e[i][0]&&e[j][1]<e[i][1]&&dp[j]+1>dp[i]){dp[i]=dp[j]+1;par[i]=j;}
  if(dp[i]>dp[best])best=i;}
 vector<int> ch;for(int i=best;i!=-1;i=par[i])ch.push_back(e[i][2]);reverse(ch.begin(),ch.end());
 printf("%d\n",(int)ch.size());for(int x:ch)printf("%d ",x);puts("");}

