int main(){int n,l,k;scanf("%d %d %d",&n,&l,&k);vector<ll> d(n+2),a(n+2,0);
 for(int i=1;i<=n;i++)scanf("%lld",&d[i]);for(int i=1;i<=n;i++)scanf("%lld",&a[i]);d[n+1]=l;
 const ll INF=LLONG_MAX/4;vector<vector<ll>> dp(n+2,vector<ll>(k+1,INF));dp[1][0]=0;
 for(int i=2;i<=n+1;i++)for(int p=i-1;p>=1;p--){int rm=i-p-1;if(rm>k)break;
  for(int r=0;r+rm<=k;r++)if(dp[p][r]<INF)dp[i][r+rm]=min(dp[i][r+rm],dp[p][r]+a[p]*(d[i]-d[p]));}
 printf("%lld\n",*min_element(dp[n+1].begin(),dp[n+1].end()));}

