#include <bits/stdc++.h>
using namespace std;
int main(){int n,k;cin>>n>>k;vector<int>t(n+1),d(n+1);for(int i=1;i<=n;i++)cin>>t[i]>>d[i];
 if(k>=n){puts("86400");return 0;}
 const int INF=1e9;vector<vector<int>>dp(n+1,vector<int>(k+1,INF));dp[0][0]=1; // dp = first free second
 for(int i=0;i<n;i++)for(int j=0;j<=k;j++){if(dp[i][j]==INF)continue;int f=dp[i][j];
  dp[i+1][j]=min(dp[i+1][j],max(f,t[i+1])+d[i+1]);
  if(j<k)dp[i+1][j+1]=min(dp[i+1][j+1],f);}
 int ans=0;
 for(int i=0;i<=n;i++)for(int j=0;j<=k;j++){if(dp[i][j]==INF)continue;int nx=i+1+(k-j); // ignore the next k-j calls
  int end=nx<=n?t[nx]:86401;ans=max(ans,min(end,86401)-dp[i][j]);}
 printf("%d\n",ans);}

