int main(){int n;scanf("%d",&n);vector<array<int,3>> q(n);
 for(int i=0;i<n;i++){scanf("%d %d",&q[i][1],&q[i][0]);q[i][2]=i+1;}
 sort(q.begin(),q.end(),[](auto&x,auto&y){return x[0]!=y[0]?x[0]>y[0]:x[1]<y[1];});
 int k;scanf("%d",&k);multiset<pair<int,int>> T;for(int j=1;j<=k;j++){int r;scanf("%d",&r);T.insert({r,j});}
 vector<pair<int,int>> res;int sum=0;
 for(auto&x:q){auto it=T.lower_bound({x[1],0});if(it==T.end())continue;
  res.push_back({x[2],it->second});sum+=x[0];T.erase(it);}
 printf("%d %d\n",(int)res.size(),sum);for(auto&r:res)printf("%d %d\n",r.first,r.second);}

