int main(){int R,G,B;cin>>R>>G>>B;vector<long long>r(R),g(G),b(B);for(auto&x:r)cin>>x;for(auto&x:g)cin>>x;for(auto&x:b)cin>>x;
 sort(r.rbegin(),r.rend());sort(g.rbegin(),g.rend());sort(b.rbegin(),b.rend());long long ans=0;
 for(int i=0;i<=R;i++)for(int j=0;j<=G;j++)for(int k=0;k<=B;k++){long long v=dp[i][j][k];ans=max(ans,v);
  if(i<R&&j<G)dp[i+1][j+1][k]=max(dp[i+1][j+1][k],v+r[i]*g[j]);
  if(i<R&&k<B)dp[i+1][j][k+1]=max(dp[i+1][j][k+1],v+r[i]*b[k]);
  if(j<G&&k<B)dp[i][j+1][k+1]=max(dp[i][j+1][k+1],v+g[j]*b[k]);}
 cout<<ans<<"\n";}

