#include <bits/stdc++.h>
using namespace std;
int main(){if(fopen("input.txt","r")){freopen("input.txt","r",stdin);freopen("output.txt","w",stdout);}
 int n,a,b;scanf("%d %d %d",&n,&a,&b);vector<int>h(n);int tot=0;for(auto&x:h){scanf("%d",&x);tot+=x;}
 const int INF=1e9;vector<array<int,2>>dp(a+1,{INF,INF});if(h[0]<=a)dp[h[0]][0]=0;dp[0][1]=0;
 for(int i=1;i<n;i++){vector<array<int,2>>nd(a+1,{INF,INF});int cst=min(h[i-1],h[i]);
  for(int r=0;r<=a;r++)for(int pc=0;pc<2;pc++){int v=dp[r][pc];if(v>=INF)continue;
   if(r+h[i]<=a)nd[r+h[i]][0]=min(nd[r+h[i]][0],v+(pc!=0?cst:0));
   nd[r][1]=min(nd[r][1],v+(pc!=1?cst:0));}
  dp=nd;}
 int ans=INF;for(int r=0;r<=a;r++)if(tot-r<=b)ans=min({ans,dp[r][0],dp[r][1]});
 printf("%d\n",ans>=INF?-1:ans);}

