int main(){int n;ll L;scanf("%d %lld",&n,&L);vector<ll> c(n);for(auto&x:c)scanf("%lld",&x);
 for(int i=1;i<n;i++)c[i]=min(c[i],2*c[i-1]);
 ll cost=0,ans=LLONG_MAX;
 for(int i=n-1;i>=0;i--){ll sz=1LL<<i;ll k=L/sz;cost+=k*c[i];L-=k*sz;
  ans=min(ans,cost+(L>0?c[i]:0));}
 ans=min(ans,cost);printf("%lld\n",ans);}

