 sort(it.begin(),it.end());const int T=2001;vector<vector<int>>dp(n+1,vector<int>(T,-1));dp[0][0]=0; // dp[i][time]
 for(int i=0;i<n;i++){auto[d,t,p,id]=it[i];for(int x=0;x<T;x++){if(dp[i][x]<0)continue;dp[i+1][x]=max(dp[i+1][x],dp[i][x]);
