#include <bits/stdc++.h>
using namespace std;
typedef long long ll;const ll INF=LLONG_MAX/4;
ll dp[101][101][101];
int main(){int n,m,k;scanf("%d %d %d",&n,&m,&k);vector<int> c(n+1);for(int i=1;i<=n;i++)scanf("%d",&c[i]);
 vector<vector<ll>> p(n+1,vector<ll>(m+1));for(int i=1;i<=n;i++)for(int j=1;j<=m;j++)scanf("%lld",&p[i][j]);
 for(int i=0;i<=n;i++)for(int j=0;j<=k;j++)for(int x=0;x<=m;x++)dp[i][j][x]=INF;
 for(int i=1;i<=n;i++)for(int j=1;j<=min(i,k);j++){
  ll b1=INF,b2=INF;int bc=-1; // best two of dp[i-1][j-1][*]
  if(i>1)for(int x=1;x<=m;x++){ll v=dp[i-1][j-1][x];if(v<b1){b2=b1;b1=v;bc=x;}else if(v<b2)b2=v;}
  for(int x=1;x<=m;x++){if(c[i]&&c[i]!=x)continue;ll cost=c[i]?0:p[i][x];ll best;
   if(i==1)best=(j==1)?0:INF;
   else best=min(dp[i-1][j][x],x==bc?b2:b1);
   if(best<INF)dp[i][j][x]=best+cost;}}
 ll ans=INF;for(int x=1;x<=m;x++)ans=min(ans,dp[n][k][x]);printf("%lld\n",ans>=INF?-1:ans);}

