 for(int T=0;T<=M;T++)dp[0][T]=0;
 for(int i=1;i<=n;i++)for(int T=1;T<=M;T++)dp[i][T]=min(dp[i][T-1],dp[i-1][T-1]+abs(T-t[i-1]));
