int main(){int t;scanf("%d",&t);while(t--){int n;long long l;scanf("%d %lld",&n,&l);vector<pair<long long,long long>>m(n);
 for(auto&p:m)scanf("%lld %lld",&p.second,&p.first);sort(m.begin(),m.end());int ans=0;
 for(int L=0;L<n;L++){priority_queue<long long>pq;long long s=0;
  for(int r=L;r<n;r++){pq.push(m[r].second);s+=m[r].second;
