#include <bits/stdc++.h>
using namespace std;
int main(){int n,k;scanf("%d %d",&n,&k);vector<int>t(n);for(auto&x:t)scanf("%d",&x);
 int cnt=0;for(int x:t)if(x<0)cnt++;if(cnt>k){puts("-1");return 0;}if(cnt==0){puts("0");return 0;}
 int first=-1,last=-1;for(int i=0;i<n;i++)if(t[i]<0){if(first<0)first=i;last=i;}
 vector<int>gaps;int groups=1,run=0;for(int i=first;i<=last;i++){if(t[i]>=0)run++;else{if(run>0){gaps.push_back(run);groups++;}run=0;}}
 sort(gaps.begin(),gaps.end());int tail=n-1-last,rem=k-cnt;
 auto calc=[&](int r,int base){for(int g:gaps){if(g<=r){r-=g;base-=2;}else break;}return base;};
 int ans=calc(rem,2*groups);if(tail<=rem)ans=min(ans,calc(rem-tail,2*groups-1));
 printf("%d\n",ans);}

