#include <bits/stdc++.h>
using namespace std;typedef long long ll;
int main(){int T;scanf("%d",&T);while(T--){int n,k;scanf("%d %d",&n,&k);vector<int>a(n);for(auto&x:a)scanf("%d",&x);
 vector<int> P;int mx=0;for(int i=0;i<n;i++)if(a[i]>mx){mx=a[i];P.push_back(i);}
 const ll NEG=LLONG_MIN/4;vector<vector<ll>>dp(k+1,vector<ll>(k+1,NEG));dp[0][0]=0;
 for(size_t t=0;t<P.size();t++){int p=P[t];ll gap=(t+1<P.size()?P[t+1]:n)-p;
  auto nd=dp;
  for(int s=0;s<=k;s++){ll best=NEG;for(int v=1;v<=min(a[p],k-s);v++){best=max(best,dp[s][v-1]);if(best>NEG)nd[s+v][v]=max(nd[s+v][v],best);}}
  for(int s=0;s<=k;s++)for(int m=0;m<=k;m++)if(nd[s][m]>NEG)nd[s][m]+=(ll)m*gap;
  dp.swap(nd);}
 ll ans=0;for(auto&r:dp)for(ll v:r)ans=max(ans,v);printf("%lld\n",ans);}}

#include <bits/stdc++.h>
using namespace std;
int main(){int n;cin>>n;vector<int>a(n),b(n);int A=0;for(auto&x:a){cin>>x;A+=x;}for(auto&x:b)cin>>x;
 vector<int>s=b;sort(s.rbegin(),s.rend());int k=0,acc=0;while(acc<A)acc+=s[k++];
 int S=100*n;vector<vector<int>>dp(k+1,vector<int>(S+1,-1));dp[0][0]=0;
 for(int i=0;i<n;i++)for(int j=min(k,i+1);j>=1;j--)for(int v=S;v>=b[i];v--)
  if(dp[j-1][v-b[i]]>=0)dp[j][v]=max(dp[j][v],dp[j-1][v-b[i]]+a[i]);
 int best=0;for(int v=A;v<=S;v++)best=max(best,dp[k][v]);cout<<k<<" "<<A-best<<endl;}

#include <bits/stdc++.h>
using namespace std;
int main(){int n,m;cin>>n>>m;vector<int>atk,def,c(m);
 for(int i=0;i<n;i++){string s;int x;cin>>s>>x;(s=="ATK"?atk:def).push_back(x);}
 for(auto&x:c)cin>>x;sort(atk.begin(),atk.end());sort(def.begin(),def.end());sort(c.begin(),c.end());
 long long best=0,cur=0; // strategy A: strongest cards vs weakest ATK
 for(int i=0;i<(int)atk.size()&&i<m;i++){int X=c[m-1-i];if(X<atk[i])break;cur+=X-atk[i];best=max(best,cur);}
 // strategy B: kill everything
 multiset<int>ms(c.begin(),c.end());bool ok=true;
 for(int y:def){auto it=ms.upper_bound(y);if(it==ms.end()){ok=false;break;}ms.erase(it);}
 if(ok&&ms.size()>=atk.size()){vector<int>r(ms.begin(),ms.end());int R=r.size(),A=atk.size();long long dmg=0;
  for(int i=0;i<A;i++){if(r[R-A+i]<atk[i]){ok=false;break;}}
  if(ok){for(int x:r)dmg+=x;for(int y:atk)dmg-=y;best=max(best,dmg);}}
 cout<<best<<endl;}

