int main(){int t;scanf("%d",&t);while(t--){int n;scanf("%d",&n);
 vector<long long> c(n),a(n),b(n);for(auto&x:c)scanf("%lld",&x);for(auto&x:a)scanf("%lld",&x);for(auto&x:b)scanf("%lld",&x);
 long long cur=0,ans=0;
 for(int i=1;i<n;i++){long long d=llabs(a[i]-b[i]);
