#include <bits/stdc++.h>
using namespace std;
int main(){int q;cin>>q;while(q--){string t;int n;cin>>t>>n;vector<string> s(n);for(auto&x:s)cin>>x;
 int L=t.size(),cov=0;vector<pair<int,int>> res;bool ok=true;
 while(cov<L){int bestEnd=-1,bw=-1,bp=-1;
  for(int p=0;p<=cov;p++)for(int w=0;w<n;w++){int len=s[w].size();
   if(p+len<=L&&t.compare(p,len,s[w])==0&&p+len-1>bestEnd){bestEnd=p+len-1;bw=w;bp=p;}}
  if(bestEnd<cov){ok=false;break;}
  res.push_back({bw+1,bp+1});cov=bestEnd+1;}
 if(!ok){puts("-1");continue;}
 printf("%d\n",(int)res.size());for(auto&r:res)printf("%d %d\n",r.first,r.second);}}

