#include <bits/stdc++.h>
using namespace std;
int main(){string s;int n;cin>>s>>n;const int NEG=-1e9,POS=1e9;
 vector<array<int,2>>mx(n+1,{NEG,NEG}),mn(n+1,{POS,POS});mx[0][0]=0;mn[0][0]=0;// d index 0:+1, 1:-1
 for(char c:s){vector<array<int,2>>nx(n+1,{NEG,NEG}),nn(n+1,{POS,POS});
  for(int j=0;j<=n;j++)for(int d=0;d<2;d++){if(mx[j][d]==NEG)continue;
   for(int k=0;j+k<=n;k++){char e=(k%2)?(c=='F'?'T':'F'):c;int nd=d,sh=0;if(e=='F')sh=(d==0?1:-1);else nd=1-d;
    nx[j+k][nd]=max(nx[j+k][nd],mx[j][d]+sh);nn[j+k][nd]=min(nn[j+k][nd],mn[j][d]+sh);}}
  mx=nx;mn=nn;}
 int ans=0;for(int d=0;d<2;d++){if(mx[n][d]!=NEG)ans=max(ans,abs(mx[n][d]));if(mn[n][d]!=POS)ans=max(ans,abs(mn[n][d]));}
 cout<<ans<<"\n";}

