int dp[101][102][26];
int main(){string s;int k,m;cin>>s>>k>>m;int b[26][26]={};while(m--){char x,y;int c;cin>>x>>y>>c;b[x-'a'][y-'a']=c;}
 int n=s.size();const int NEG=-1e9;for(auto&a:dp)for(auto&r:a)for(auto&v:r)v=NEG;
 for(int c=0;c<26;c++){int j=(c!=s[0]-'a');if(j<=k)dp[0][j][c]=0;}
 for(int i=1;i<n;i++)for(int j=0;j<=k;j++)for(int q=0;q<26;q++){if(dp[i-1][j][q]==NEG)continue;
  for(int c=0;c<26;c++){int nj=j+(c!=s[i]-'a');if(nj>k)continue;dp[i][nj][c]=max(dp[i][nj][c],dp[i-1][j][q]+b[q][c]);}}
 int ans=NEG;for(int j=0;j<=k;j++)for(int c=0;c<26;c++)ans=max(ans,dp[n-1][j][c]);cout<<ans<<"\n";}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main(){int t;scanf("%d",&t);while(t--){int n,k;scanf("%d %d",&n,&k);vector<int>a(n);
 for(auto&x:a)scanf("%d",&x);vector<ll>cold(k+1),hot(k+1);
 for(int i=1;i<=k;i++)scanf("%lld",&cold[i]);for(int i=1;i<=k;i++)scanf("%lld",&hot[i]);
 const ll INF=LLONG_MAX/4;vector<ll>dp(k+1,INF);dp[0]=0;int p=0;
 for(int i=0;i<n;i++){int c=a[i];ll c1=(c==p?hot[c]:cold[c]);vector<ll>nd(k+1,INF);ll best=INF;
  for(int x=0;x<=k;x++)if(dp[x]<INF){nd[x]=dp[x]+c1;best=min(best,dp[x]+(x==c?hot[c]:cold[c]));}
  nd[p]=min(nd[p],best);dp=nd;p=c;}
 printf("%lld\n",*min_element(dp.begin(),dp.end()));}}

