#include <bits/stdc++.h>
using namespace std;
int main(){int n;scanf("%d",&n);vector<long long>a(n+2,0);for(int i=1;i<=n;i++)scanf("%lld",&a[i]);a[0]=-1e18;
 int K=(n+1)/2;const long long INF=1e18;
 vector<array<long long,3>> f(K+2,{INF,INF,INF}),g;f[0][0]=0; // i=0
 for(int i=1;i<=n;i++){g.assign(K+2,{INF,INF,INF});
  for(int j=0;j<=K;j++){
   g[j][0]=min(f[j][0],f[j][2]);
   if(j>0){long long c0=(i>1)?max(0LL,a[i-1]-a[i]+1):0;
    long long c2=(i>2)?max(0LL,min(a[i-1],a[i-2]-1)-a[i]+1):c0;
    if(f[j-1][0]<INF)g[j][1]=min(g[j][1],f[j-1][0]+c0);
    if(f[j-1][2]<INF)g[j][1]=min(g[j][1],f[j-1][2]+c2);}
   if(f[j][1]<INF)g[j][2]=f[j][1]+max(0LL,a[i]-a[i-1]+1);}
  f=g;}
 for(int j=1;j<=K;j++)printf("%lld ",min({f[j][0],f[j][1],f[j][2]}));puts("");}

