#include <bits/stdc++.h>
using namespace std; typedef __int128 L128;
L128 val(const string&s){L128 v=0;for(char c:s)v=v*10+(c-'0');return v;}
int main(){int t;scanf("%d",&t);while(t--){long long a;int n;scanf("%lld %d",&a,&n);int D[2];scanf("%d %d",&D[0],&D[1]);
 string A=to_string(a);int L=A.size();char lo='0'+D[0],hi='0'+D[1];vector<string>c;
 if(D[0]==0)c.push_back("0");
 if(L>1)c.push_back(string(L-1,hi));
 c.push_back(string(1,D[0]>0?lo:hi)+string(L,lo));
 for(int i=0;i<=L;i++){if(i==L){c.push_back(A);break;}
  for(int d:D){if(i==0&&d==0&&L>1)continue;char ch='0'+d;
   if(ch<A[i])c.push_back(A.substr(0,i)+ch+string(L-i-1,hi));
   if(ch>A[i])c.push_back(A.substr(0,i)+ch+string(L-i-1,lo));}
  if(A[i]!=lo&&A[i]!=hi)break;}
 L128 best=-1;for(auto&s:c){L128 d=val(s)-(L128)a;if(d<0)d=-d;if(best<0||d<best)best=d;}
 printf("%lld\n",(long long)best);}}

