 for(int i=0;i<n;i++){scanf("%lld",&a[i]);P[i+1]=P[i]+a[i];}
 for(int i=0;i<n;i++)mx[i]=max(i?mx[i-1]:0,i+1<n?a[i]+a[i+1]:0);
 long long ans=0;
 for(int l=0;l<=z;l++){int p=k-2*l;if(p<0)break;ans=max(ans,P[p+1]+l*mx[p]);}
