#include <bits/stdc++.h>
using namespace std;
int main(){int n;scanf("%d",&n);vector<long long>a(n+1);for(int i=2;i<=n;i++)scanf("%lld",&a[i]);
 vector<array<long long,2>>val(n+1);vector<array<char,2>>st(n+1,{0,0});
 for(int s=2;s<=n;s++)for(int d0=0;d0<2;d0++){if(st[s][d0])continue;vector<pair<int,int>>stk={{s,d0}};
  while(!stk.empty()){auto [x,d]=stk.back();long long nx=d==0?x+a[x]:x-a[x];
   if(nx<=0||nx>n){val[x][d]=a[x];st[x][d]=2;stk.pop_back();continue;}
   if(nx==1){val[x][d]=-1;st[x][d]=2;stk.pop_back();continue;}
   char cs=st[nx][1-d];
   if(cs==2){long long v=val[nx][1-d];val[x][d]=v<0?-1:v+a[x];st[x][d]=2;stk.pop_back();}
   else if(cs==1&&st[x][d]==1){val[x][d]=-1;st[x][d]=2;stk.pop_back();}
   else if(st[x][d]==0){st[x][d]=1;if(cs==0)stk.push_back({(int)nx,1-d});}
   else {val[x][d]=-1;st[x][d]=2;stk.pop_back();}}}
 for(int i=1;i<n;i++){long long v=val[1+i][1];printf("%lld\n",v<0?-1:v+i);}}

