#include <bits/stdc++.h>
using namespace std;
const long long M=1e9+7;
int main(){int n,l;cin>>n>>l;vector<array<int,3>>v;// length,width,type
 for(int i=0;i<n;i++){int a,b;cin>>a>>b;v.push_back({a,b,i});if(a!=b)v.push_back({b,a,i});}
 int K=v.size();vector<vector<long long>>dp(l+1,vector<long long>(K,0));
 for(int x=0;x<K;x++)if(v[x][0]<=l)dp[v[x][0]][x]=1;
 for(int len=1;len<=l;len++)for(int x=0;x<K;x++){long long c=dp[len][x];if(!c)continue;
  for(int y=0;y<K;y++)if(v[y][2]!=v[x][2]&&v[y][0]==v[x][1]&&len+v[y][0]<=l)dp[len+v[y][0]][y]=(dp[len+v[y][0]][y]+c)%M;}
 long long ans=0;for(int x=0;x<K;x++)ans=(ans+dp[l][x])%M;cout<<ans<<"\n";}

