int main(){int n;cin>>n;vector<int>a(n),b(n);int B=0,S=0;for(int i=0;i<n;i++){cin>>a[i]>>b[i];B+=b[i];S+=a[i];}
 // dp[k][A] = max sum of b among k chosen glasses with total capacity A
 vector<vector<int>>dp(n+1,vector<int>(S+1,-1));dp[0][0]=0;
 for(int i=0;i<n;i++)for(int k=i;k>=0;k--)for(int A=S-a[i];A>=0;A--)
  if(dp[k][A]>=0)dp[k+1][A+a[i]]=max(dp[k+1][A+a[i]],dp[k][A]+b[i]);
 for(int k=1;k<=n;k++){double best=0;
  for(int A=0;A<=S;A++)if(dp[k][A]>=0)best=max(best,min((double)A,(B+dp[k][A])/2.0));
  printf("%.10f ",best);}puts("");}

#include <bits/stdc++.h>
