#include <bits/stdc++.h>
using namespace std;
int main(){int n;cin>>n;vector<long long>a(n),b(n),c(n);for(auto&x:a)cin>>x;for(auto&x:b)cin>>x;for(auto&x:c)cin>>x;
 const long long NEG=LLONG_MIN/4;
 // f[t]: t=1 means hare i+1 fed before hare i
 long long f[2];
 for(int t=0;t<2;t++){int fb=t;f[t]=fb==0?a[0]:b[0];}
 if(n==1){cout<<a[0]<<"\n";return 0;}
 for(int i=1;i<n;i++){long long g[2]={NEG,NEG};
  for(int p=0;p<2;p++)for(int t=0;t<2;t++){if(i==n-1&&t==1)continue;
   int fb=(p==1?0:1)+t; // p==1: hare i fed before hare i-1, so left neighbor not yet fed
   long long j=fb==0?a[i]:fb==1?b[i]:c[i];g[t]=max(g[t],f[p]+j);}
  f[0]=g[0];f[1]=g[1];}
 cout<<f[0]<<"\n";}

#include <bits/stdc++.h>
using namespace std;
int main(){int t;scanf("%d",&t);while(t--){int n;scanf("%d",&n);vector<long long>a(n+1);for(int i=1;i<=n;i++)scanf("%lld",&a[i]);
 vector<vector<int>>g(n+1);for(int i=0;i<n-1;i++){int u,v;scanf("%d %d",&u,&v);g[u].push_back(v);g[v].push_back(u);}
 vector<int>par(n+1,0),ord={1};vector<long long>dep(n+1,0);par[1]=-1;
 for(int i=0;i<(int)ord.size();i++){int v=ord[i];for(int u:g[v])if(u!=par[v]){par[u]=v;dep[u]=dep[v]+1;ord.push_back(u);}}
 vector<long long>S(n+1),W(n+1),H(n+1),best(n+1,0);
 for(int i=n-1;i>=0;i--){int v=ord[i];S[v]+=a[v];W[v]+=a[v]*dep[v];H[v]=max(H[v],dep[v]);
  long long h1=-1,h2=-1;for(int c:g[v])if(c!=par[v]){if(H[c]>h1){h2=h1;h1=H[c];}else if(H[c]>h2)h2=H[c];}
  for(int c:g[v])if(c!=par[v]){long long O=max(dep[v],H[c]==h1?h2:h1);best[v]=max({best[v],best[c],S[c]*(O-dep[v])});}
  if(par[v]>0){int p=par[v];S[p]+=S[v];W[p]+=W[v];H[p]=max(H[p],H[v]);}}
 for(int r=1;r<=n;r++)printf("%lld ",W[r]-dep[r]*S[r]+best[r]);puts("");}}

