int main(){int n,q;scanf("%d %d",&n,&q);vector<ll>v(n);vector<int>c(n);for(auto&x:v)scanf("%lld",&x);for(auto&x:c)scanf("%d",&x);
 const ll NEG=LLONG_MIN/4;vector<ll>best(n+1);
 while(q--){ll a,b;scanf("%lld %lld",&a,&b);fill(best.begin(),best.end(),NEG);int c1=0,c2=0;ll b1=0,b2=0; // top two colours (0 = empty sequence, value 0)
  for(int i=0;i<n;i++){int col=c[i];ll cur=max(best[col]==NEG?NEG:best[col]+a*v[i],(c1!=col?b1:b2)+b*v[i]);
   if(cur>best[col]){best[col]=cur;
    if(col==c1)b1=cur;else if(cur>b1){c2=c1;b2=b1;c1=col;b1=cur;}else if(cur>b2){c2=col;b2=cur;}}}
  printf("%lld\n",max(0LL,b1));}}

#include <bits/stdc++.h>
using namespace std;
int main(){int n,m;scanf("%d %d",&n,&m);vector<string>g(n);char buf[505];for(auto&s:g){scanf("%s",buf);s=buf;}
 const int P=676;vector<int>dp(P),nd(P);vector<vector<short>>par(n,vector<short>(P,-1));
 auto rowcost=[&](int r,vector<int>&cost){int ce[26]={0},co[26]={0};for(int j=0;j<m;j++)(j%2?co:ce)[g[r][j]-'a']++;
  int ne=(m+1)/2,no=m/2;for(int a=0;a<26;a++)for(int b=0;b<26;b++)cost[a*26+b]=(a==b)?INT_MAX/2:(ne-ce[a])+(no-co[b]);};
 vector<int>cost(P);rowcost(0,cost);dp=cost;
 for(int r=1;r<n;r++){rowcost(r,cost);vector<int>ord(P);iota(ord.begin(),ord.end(),0);sort(ord.begin(),ord.end(),[&](int x,int y){return dp[x]<dp[y];});
  for(int q=0;q<P;q++){nd[q]=INT_MAX/2;if(cost[q]>=INT_MAX/2)continue;int a=q/26,b=q%26;
   for(int id:ord){if(id/26!=a&&id%26!=b){nd[q]=dp[id]+cost[q];par[r][q]=id;break;}}} // at most ~51 rejections
  swap(dp,nd);}
 int q=min_element(dp.begin(),dp.end())-dp.begin();printf("%d\n",dp[q]);vector<int>ch(n);
 for(int r=n-1;r>=0;r--){ch[r]=q;q=par[r][q];}
 for(int r=0;r<n;r++){for(int j=0;j<m;j++)putchar('a'+(j%2?ch[r]%26:ch[r]/26));putchar('\n');}}

