#include <bits/stdc++.h>
using namespace std;
int main(){int t;scanf("%d",&t);while(t--){int n;scanf("%d",&n);vector<int>a(n+1),nz;
 for(int i=1;i<=n;i++){scanf("%d",&a[i]);if(a[i])nz.push_back(i);}
 if(nz.size()%2){puts("-1");continue;}
 vector<pair<int,int>>seg;int pos=1;
 for(size_t k=0;k<nz.size();k+=2){int i=nz[k],j=nz[k+1];
  while(pos<i){seg.push_back({pos,pos});pos++;}
  if(a[i]!=a[j]){for(int x=i;x<=j;x++)seg.push_back({x,x});}
  else if(j==i+1)seg.push_back({i,j});
  else{for(int x=i;x<=j-2;x++)seg.push_back({x,x});seg.push_back({j-1,j});}
  pos=j+1;}
 while(pos<=n){seg.push_back({pos,pos});pos++;}
 printf("%d\n",(int)seg.size());for(auto&p:seg)printf("%d %d\n",p.first,p.second);}}

