#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main(){int t;scanf("%d",&t);while(t--){int n;scanf("%d",&n);vector<ll> a(n);int k=-1;
 for(int i=0;i<n;i++){scanf("%lld",&a[i]);if(a[i]!=1&&a[i]!=-1)k=i;}
 ll mx=0,mn=0,cx=0,cn=0;
 for(int i=0;i<n;i++){if(i==k){cx=cn=0;continue;}cx=max(0LL,cx+a[i]);cn=min(0LL,cn+a[i]);mx=max(mx,cx);mn=min(mn,cn);}
 set<ll> s; for(ll v=mn;v<=mx;v++)s.insert(v);
 if(k>=0){vector<ll> P(n+1,0);for(int i=0;i<n;i++)P[i+1]=P[i]+a[i];
  ll mxR=LLONG_MIN,mnR=LLONG_MAX,mxL=LLONG_MIN,mnL=LLONG_MAX;
  for(int r=k+1;r<=n;r++){mxR=max(mxR,P[r]);mnR=min(mnR,P[r]);}
  for(int l=0;l<=k;l++){mxL=max(mxL,P[l]);mnL=min(mnL,P[l]);}
  for(ll v=mnR-mxL;v<=mxR-mnL;v++)s.insert(v);}
 printf("%d\n",(int)s.size());for(ll v:s)printf("%lld ",v);puts("");}}

