#include <bits/stdc++.h>
using namespace std;
const long long M=1e9+7;
int main(){
    int n; scanf("%d",&n);
    vector<long long> pre(n+1,0);
    for(int i=1;i<=n;i++){
        int p; scanf("%d",&p);
        long long dp=(2+pre[i-1]-pre[p-1]+M)%M;
        pre[i]=(pre[i-1]+dp)%M;
    }
