}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int n,m; scanf("%d %d",&n,&m);
    vector<long long> prev(m),cur(m); vector<int> upP(m,1),upC(m),best(n+1);
    for(int i=1;i<=n;i++){
        int b=i;
        for(int j=0;j<m;j++){
            scanf("%lld",&cur[j]);
            upC[j]= (i>1 && cur[j]>=prev[j]) ? upP[j] : i;
            b=min(b,upC[j]);
        }
        best[i]=b; swap(prev,cur); swap(upP,upC);
    }
    int k; scanf("%d",&k);
    while(k--){int l,r; scanf("%d %d",&l,&r); puts(best[r]<=l?"Yes":"No");}
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main(){
    ll n,x,s; int m,k; scanf("%lld %d %d %lld %lld",&n,&m,&k,&x,&s);
    vector<ll> a(m+1),b(m+1),c(k),d(k);
    for(int i=0;i<m;i++) scanf("%lld",&a[i]);
    for(int i=0;i<m;i++) scanf("%lld",&b[i]);
    a[m]=x; b[m]=0;
    for(auto&v:c) scanf("%lld",&v);
    for(auto&v:d) scanf("%lld",&v);
    ll ans=n*x;
    for(int i=0;i<=m;i++){
        if(b[i]>s) continue;
        ll rem=s-b[i];
        int j=upper_bound(d.begin(),d.end(),rem)-d.begin()-1;
        ll got= j>=0? c[j]:0;
        ans=min(ans,(n-got)*a[i]);
    }
    printf("%lld\n",ans);
}

