#include <bits/stdc++.h>
using namespace std;
vector<long long>a;
long long solve(int l,int r,long long base){if(l>r)return 0;long long m=*min_element(a.begin()+l,a.begin()+r+1);long long c=m-base;int s=l;
 for(int i=l;i<=r;i++)if(a[i]==m){c+=solve(s,i-1,m);s=i+1;}c+=solve(s,r,m);return min<long long>(r-l+1,c);}
int main(){int n;scanf("%d",&n);a.resize(n);for(auto&x:a)scanf("%lld",&x);printf("%lld\n",solve(0,n-1,0));}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main(){ll n,A,cf,cm,m;cin>>n>>A>>cf>>cm>>m;vector<pair<ll,int>>a(n);for(int i=0;i<n;i++){cin>>a[i].first;a[i].second=i;}
sort(a.begin(),a.end());vector<ll>pre(n+1,0);for(int i=0;i<n;i++)pre[i+1]=pre[i]+a[i].first;
ll best=-1,bk=0,bmin=0,suf=0; // k = number of top skills maxed
for(ll k=0;k<=n;k++){ if(k>0)suf+=A-a[n-k].first; if(suf>m)break; ll r=m-suf,mn;
  if(k==n)mn=A; else{ // largest p in [1,n-k] with a[p-1]*p-pre[p]<=r
    ll lo=1,hi=n-k;while(lo<hi){ll md=(lo+hi+1)/2;if(a[md-1].first*md-pre[md]<=r)lo=md;else hi=md-1;}
    mn=min(A,(r+pre[lo])/lo);}
  ll f=cf*k+cm*mn;if(f>best){best=f;bk=k;bmin=mn;}}
vector<ll>res(n);for(int i=0;i<n;i++){ll v=(i>=n-bk)?A:max(a[i].first,bmin);res[a[i].second]=v;}
cout<<best<<"\n";for(ll v:res)cout<<v<<" ";cout<<"\n";}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main(){int t;scanf("%d",&t);while(t--){int n;ll x,y;char A[5005],B[5005];scanf("%d %lld %lld %s %s",&n,&x,&y,A,B);
 vector<int>p;for(int i=0;i<n;i++)if(A[i]!=B[i])p.push_back(i);int k=p.size();
 if(k%2){puts("-1");continue;}if(k==0){puts("0");continue;}
 if(y<=x){ll r=(k==2&&p[1]==p[0]+1)?min(x,2*y):(ll)k/2*y;printf("%lld\n",r);continue;}
 vector<ll>dp(k+1);dp[0]=0;dp[1]=y; // doubled costs: a far partner costs y per endpoint (y/2 real)
 for(int i=2;i<=k;i++)dp[i]=min(dp[i-1]+y,dp[i-2]+2*x*(p[i-1]-p[i-2])); // chain of adjacent flips costs x*dist
 printf("%lld\n",dp[k]/2);}}

