#include <bits/stdc++.h>
using namespace std; typedef long long ll;
int main(){int n,k;scanf("%d %d",&n,&k);vector<ll>p(n+1,0);
 for(int i=1;i<=n;i++){ll x;scanf("%lld",&x);p[i]=p[i-1]+x;}
 auto w=[&](int i){return p[i+k-1]-p[i-1];};
 int best=1,A=0,B=0;ll bs=-1;
 for(int b=k+1;b+k-1<=n;b++){int c=b-k;if(w(c)>w(best))best=c;
  if(w(best)+w(b)>bs){bs=w(best)+w(b);A=best;B=b;}}
 printf("%d %d\n",A,B);}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int t; scanf("%d",&t);
    while(t--){
        int n; scanf("%d",&n); vector<int> p(n);
        for(auto&x:p) scanf("%d",&x);
        vector<int> sm(n+1,0);
        for(int i=n-1;i>=0;i--) sm[i]=max(sm[i+1],p[i]);
        vector<pair<int,int>> e; bool ok=true; int cur=p[0];
        for(int i=1;i<n;i++){
            if(p[i]<cur){
                if(cur>sm[i]){ok=false;break;}
                e.push_back({cur,sm[i]}); cur=p[i];
            } else e.push_back({cur,p[i]});
        }
        if(!ok){puts("No");continue;}
        puts("Yes");
        for(auto [u,v]:e) printf("%d %d\n",u,v);
    }
}

