#include <bits/stdc++.h>
using namespace std;
vector<int> bfs(int s,vector<vector<int>>&g){vector<int> d(g.size(),-1);queue<int> q;q.push(s);d[s]=0;
 while(!q.empty()){int u=q.front();q.pop();for(int v:g[u])if(d[v]<0){d[v]=d[u]+1;q.push(v);}}return d;}
int main(){int t;scanf("%d",&t);while(t--){int n,k;scanf("%d %d",&n,&k);vector<int> mk(k);for(auto&x:mk)scanf("%d",&x);
 vector<vector<int>> g(n+1);for(int i=0;i<n-1;i++){int u,v;scanf("%d %d",&u,&v);g[u].push_back(v);g[v].push_back(u);}
 auto d=bfs(mk[0],g);int u=mk[0];for(int x:mk)if(d[x]>d[u])u=x;
 auto d2=bfs(u,g);int D=0;for(int x:mk)D=max(D,d2[x]);
 printf("%d\n",(D+1)/2);}}

