int main(){int t;scanf("%d",&t);while(t--){int n;scanf("%d",&n);vector<long long> s(n),b(n);
 for(int i=0;i<n;i++){long long h,w;scanf("%lld %lld",&h,&w);s[i]=min(h,w);b[i]=max(h,w);}
 vector<int> id(n);iota(id.begin(),id.end(),0);sort(id.begin(),id.end(),[&](int x,int y){return s[x]<s[y];});
 vector<int> ans(n,-1);long long bestB=LLONG_MAX;int bestI=-1;
 for(int i=0;i<n;){int j=i;while(j<n&&s[id[j]]==s[id[i]])j++;
  for(int q=i;q<j;q++)if(bestB<b[id[q]])ans[id[q]]=bestI+1;
  for(int q=i;q<j;q++)if(b[id[q]]<bestB){bestB=b[id[q]];bestI=id[q];}
  i=j;}
 for(int x:ans)printf("%d ",x);puts("");}}

