 vector<long long>v(n+1),inc(n+1,0),dec(n+1,0);for(int i=1;i<=n;i++)scanf("%lld",&v[i]);
 vector<int>par(n+1,0),ord={1};par[1]=-1;for(int i=0;i<(int)ord.size();i++){int x=ord[i];for(int u:g[x])if(u!=par[x]){par[u]=x;ord.push_back(u);}}
 for(int i=n-1;i>=0;i--){int x=ord[i];long long r=v[x]+inc[x]-dec[x];if(r>0)dec[x]+=r;else inc[x]-=r;
  if(par[x]>0){inc[par[x]]=max(inc[par[x]],inc[x]);dec[par[x]]=max(dec[par[x]],dec[x]);}}
 printf("%lld\n",inc[1]+dec[1]);}

