#include <bits/stdc++.h>
using namespace std;
int main(){int t;scanf("%d",&t);while(t--){int n,k;scanf("%d %d",&n,&k);const long long INF=LLONG_MAX/4;vector<long long>dp(k+1,INF);dp[0]=0;
 for(int i=0;i<n;i++){int a,b;scanf("%d %d",&a,&b);int P=min(k,a+b);vector<long long>c(P+1,INF);
  for(int r=0;r<=b;r++)for(int q=0;q<=a&&r+q<=P;q++)c[r+q]=min(c[r+q],(long long)r*a+(long long)q*b-(long long)r*q);
  vector<long long>nd=dp;for(int j=0;j<=k;j++){if(dp[j]>=INF)continue;for(int p=1;p<(int)c.size();p++){if(c[p]>=INF)continue;int nj=min(k,j+p);nd[nj]=min(nd[nj],dp[j]+c[p]);}}
  dp=nd;}
 printf("%lld\n",dp[k]>=INF?-1:dp[k]);}}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main(){int n,m;scanf("%d %d",&n,&m);const ll NEG=LLONG_MIN/4;vector<ll>dp(m+2,NEG),nd(m+2),pre(m+1);
 for(int i=0;i<n;i++){pre[0]=0;for(int j=1;j<=m;j++){int x;scanf("%d",&x);pre[j]=pre[j-1]+x;}
  if(i==0){for(int c=1;c<=m;c++)dp[c]=pre[c];continue;}
  if(i%2==1){ // need c_i < c_{i-1}: best over prev c' > c (suffix max)
   ll best=NEG;for(int c=m;c>=1;c--){nd[c]=best==NEG?NEG:best+pre[c];best=max(best,dp[c]);}}
  else{ll best=NEG;for(int c=1;c<=m;c++){nd[c]=best==NEG?NEG:best+pre[c];best=max(best,dp[c]);}}
  for(int c=1;c<=m;c++)dp[c]=nd[c];}
 ll ans=NEG;for(int c=1;c<=m;c++)ans=max(ans,dp[c]);printf("%lld\n",ans);}

