#include <bits/stdc++.h>
using namespace std; typedef long long ll;
ll kad(vector<ll>&a){ll best=LLONG_MIN,cur=0;for(ll x:a){cur=max(cur+x,x);best=max(best,cur);}return best;}
int main(){int t;scanf("%d",&t);while(t--){int n;ll k;scanf("%d %lld",&n,&k);char s[200005];scanf("%s",s);
 vector<ll>a(n);for(auto&x:a)scanf("%lld",&x);int p=-1;
 for(int i=0;i<n;i++)if(s[i]=='0'){a[i]=-1e13;if(p<0)p=i;}
 if(kad(a)>k){puts("No");continue;}
 if(p<0){if(kad(a)!=k){puts("No");continue;}}
 else{ll L=0,c=0;for(int i=p-1;i>=0;i--){c+=a[i];L=max(L,c);}
  ll R=0;c=0;for(int i=p+1;i<n;i++){c+=a[i];R=max(R,c);}
  a[p]=k-L-R;}
 puts("Yes");for(ll x:a)printf("%lld ",x);puts("");}}

