#include <bits/stdc++.h>
using namespace std;
int main(){
    int t; scanf("%d",&t);
    while(t--){
        int n; scanf("%d",&n);
        vector<long long> f(n+1,0);
        for(int i=2;i<=n;i++){ printf("? 1 %d\n",i); fflush(stdout); scanf("%lld",&f[i]); }
        int k=-1; for(int i=2;i<=n;i++) if(f[i]>0){k=i;break;}
        if(k==-1){ printf("! IMPOSSIBLE\n"); fflush(stdout); continue; }
        string s(n+1,'0'); int v=f[k];
        s[k]='1';
        for(int j=1;j<k-v;j++) s[j]='1';
        for(int i=k+1;i<=n;i++) s[i]= f[i]>f[i-1]?'1':'0';
        printf("! %s\n",s.substr(1).c_str()); fflush(stdout);
    }
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    long long n,m,s,d; scanf("%lld %lld %lld %lld",&n,&m,&s,&d);
    vector<long long> a(n); for(auto&x:a) scanf("%lld",&x);
    sort(a.begin(),a.end());
    string out; long long pos=0; int i=0;
    while(i<n){
        long long run=a[i]-1-pos;
        if(run<s){puts("IMPOSSIBLE");return 0;}
        int j=i;
        while(j+1<n && a[j+1]-a[j]-2<s) j++;
        long long jump=a[j]+1-(a[i]-1);
        if(jump>d){puts("IMPOSSIBLE");return 0;}
        out+="RUN "+to_string(run)+"\nJUMP "+to_string(jump)+"\n";
        pos=a[j]+1; i=j+1;
    }
    if(pos<m) out+="RUN "+to_string(m-pos)+"\n";
    fputs(out.c_str(),stdout);
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    string s; cin>>s; int n=s.size();
    vector<int> pi(n,0);
    for(int i=1;i<n;i++){
        int j=pi[i-1];
        while(j>0 && s[i]!=s[j]) j=pi[j-1];
        if(s[i]==s[j]) j++;
        pi[i]=j;
    }
    int L=pi[n-1], mx=0;
    for(int i=0;i<n-1;i++) mx=max(mx,pi[i]);
    if(L>0 && mx>=L){ cout<<s.substr(0,L)<<"\n"; return 0; }
    if(L>0 && pi[L-1]>0){ cout<<s.substr(0,pi[L-1])<<"\n"; return 0; }
    cout<<"Just a legend\n";
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int n; scanf("%d",&n); vector<int> a(n);
    map<int,int> dp; int best=0,bv=0;
    for(int i=0;i<n;i++){
        scanf("%d",&a[i]);
        auto it=dp.find(a[i]-1);
        int v=(it==dp.end()?0:it->second)+1;
        dp[a[i]]=max(dp[a[i]],v);
        if(v>best){best=v;bv=a[i];}
    }
    printf("%d\n",best);
    int x=bv-best+1;
    for(int i=0;i<n && x<=bv;i++) if(a[i]==x){ printf("%d ",i+1); x++; }
    puts("");
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int n,h,l,r; scanf("%d %d %d %d",&n,&h,&l,&r);
    vector<int> dp(h,INT_MIN),nd(h); dp[0]=0;
    for(int i=0;i<n;i++){
        int a; scanf("%d",&a);
        fill(nd.begin(),nd.end(),INT_MIN);
        for(int t=0;t<h;t++) if(dp[t]!=INT_MIN)
            for(int nt: {(t+a)%h,(t+a-1)%h})
                nd[nt]=max(nd[nt], dp[t]+(l<=nt && nt<=r));
        swap(dp,nd);
    }
    printf("%d\n",*max_element(dp.begin(),dp.end()));
}

