const long long M=1e9+7;
int main(){long long t;int l,r;cin>>t>>l>>r;vector<int>sp(r+1,0),pr;vector<long long>f(r+1,0);
 for(int i=2;i<=r;i++){if(!sp[i]){sp[i]=i;pr.push_back(i);}for(int p:pr){if(p>sp[i]||(long long)p*i>r)break;sp[p*i]=p;}}
 for(int i=2;i<=r;i++){long long p=sp[i];f[i]=(f[i/p]+(long long)i*(p-1)/2)%M;}
