 vector<long long> sz(n+1,1),dp(n+1,0);
 for(int i=n-1;i>=0;i--){int v=ord[i];long long tot=0,M=0;int big=0;
  for(int c:ch[v]){sz[v]+=sz[c];tot+=sz[c];if(sz[c]>M){M=sz[c];big=c;}}
  if(!big)continue;
  if(M<=tot-M) dp[v]=tot/2; else dp[v]=(tot-M)+min(dp[big],(M-(tot-M))/2);}
 printf("%lld\n",dp[1]);}}

