 long long cnt[201]={0},shorterCost=0,best=LLONG_MAX,done=0;
 for(int i=0;i<n;){int j=i;long long g=0;while(j<n&&v[j].first==v[i].first){g+=v[j].second;j++;}
  long long c=j-i,longer=total-done-g,keep=0,need=c-1;
