 for(int i=0;i<n;i++){vector<vector<int>>r(h+1,vector<int>(k,NEG));r[0][0]=0; // r[cnt][rem] for this row
  for(int j=0;j<m;j++){int x;scanf("%d",&x);for(int c=h;c>=1;c--)for(int q=0;q<k;q++)if(r[c-1][q]>NEG)r[c][(q+x)%k]=max(r[c][(q+x)%k],r[c-1][q]+x);}
  vector<int>best(k,NEG);for(int c=0;c<=h;c++)for(int q=0;q<k;q++)best[q]=max(best[q],r[c][q]);
  vector<int>nt(k,NEG);for(int a=0;a<k;a++)if(tot[a]>NEG)for(int q=0;q<k;q++)if(best[q]>NEG)nt[(a+q)%k]=max(nt[(a+q)%k],tot[a]+best[q]);
  tot=nt;}
