 auto d1=bfs(1,g);int A=max_element(d1.begin()+1,d1.end())-d1.begin();
 auto dA=bfs(A,g);int B=max_element(dA.begin()+1,dA.end())-dA.begin();auto dB=bfs(B,g);
 ll ans=LLONG_MIN;for(int v=1;v<=n;v++)ans=max(ans,k*max(dA[v],dB[v])-c*d1[v]);
