 for(int i=n-1;i>=0;i--){nx[i]=last[a[i]];last[a[i]]=i;}
 int x=-1,y=-1,ans=0;// indices of last elements
 auto val=[&](int i){return i<0?0:a[i];};auto nxt=[&](int i){return i<0?INF:nx[i];};
 for(int i=0;i<n;i++){int v=a[i];
  if(v!=val(x)&&v!=val(y)){ans++;if(nxt(x)<nxt(y))x=i;else y=i;}
  else if(v==val(x)&&v!=val(y)){ans++;y=i;}
