int main(){int n,m;scanf("%d %d",&n,&m);vector<int>c(m+3,0);for(int i=0;i<n;i++){int x;scanf("%d",&x);c[x]++;}
  // dp[x][y]: x runs (i-1,i,i+1) started at i-1, y runs started at i
  const int NEG=-1e9;int dp[3][3],nd[3][3];for(auto&r:dp)for(auto&v:r)v=NEG;dp[0][0]=0;
  for(int i=1;i<=m;i++){for(auto&r:nd)for(auto&v:r)v=NEG;
    for(int x=0;x<3;x++)for(int y=0;y<3;y++)if(dp[x][y]>NEG)for(int z=0;z<3;z++){
      int used=x+y+z;if(used>c[i])continue; // value i used by runs started at i-2 (x), i-1 (y), i (z)
      nd[y][z]=max(nd[y][z],dp[x][y]+z+(c[i]-used)/3);}
    memcpy(dp,nd,sizeof dp);}
  printf("%d\n",dp[0][0]);}

