#include <bits/stdc++.h>
using namespace std;
typedef long long ll;int K,L;
ll g(int hi,int lo){ // min steps from residue hi down to residue lo inside one block of length L
 vector<ll>d(hi+1,LLONG_MAX);d[hi]=0;
 for(int v=hi;v>lo;v--){if(d[v]==LLONG_MAX)continue;d[v-1]=min(d[v-1],d[v]+1);
  for(int x=2;x<=K;x++){int t=v-v%x;if(t>=lo&&t<v)d[t]=min(d[t],d[v]+1);}}
 return d[lo];}
int main(){ll a,b;cin>>a>>b>>K;L=1;for(int x=2;x<=K;x++)L=L/__gcd(L,x)*x; // can never jump over a multiple of L
 ll qa=a/L,qb=b/L;int ra=a%L,rb=b%L;
 if(qa==qb){cout<<g(ra,rb)<<"\n";return 0;}
 ll full=1+g(L-1,0); // from multiple of L to the previous multiple
 cout<<g(ra,0)+(qa-qb-1)*full+1+g(L-1,rb)<<"\n";}

