typedef long long ll;typedef pair<ll,ll> P; // (good count, -weight): maximise lexicographically
int main(){int n;scanf("%d",&n);vector<vector<int>>g(n+1);for(int i=0;i<n-1;i++){int u,v;scanf("%d %d",&u,&v);g[u].push_back(v);g[v].push_back(u);}
 if(n==2){puts("2 2\n1 1");return 0;}
