  for(int c:g[v])if(c!=par[v]){f1[v].first+=f0[c].first;f1[v].second+=f0[c].second;P b=max(f0[c],f1[c]);f0[v].first+=b.first;f0[v].second+=b.second;}}
 vector<int>good(n+1,0);vector<ll>w(n+1);
 for(int v:ord){bool pg=par[v]&&good[par[v]];good[v]=!pg&&f1[v]>f0[v];w[v]=good[v]?g[v].size():1;} // two good vertices can't be adjacent
 P r=max(f0[1],f1[1]);printf("%lld %lld\n",r.first,-r.second);for(int v=1;v<=n;v++)printf("%lld ",w[v]);puts("");}

