#include <bits/stdc++.h>
using namespace std;typedef long long ll;const ll P=1e9+7;int M;
typedef vector<vector<ll>> Mat;
Mat mul(const Mat&A,const Mat&B){Mat C(M,vector<ll>(M,0));for(int i=0;i<M;i++)for(int k=0;k<M;k++)if(A[i][k])for(int j=0;j<M;j++)C[i][j]=(C[i][j]+A[i][k]*B[k][j])%P;return C;}
int main(){ll N;cin>>N>>M;if(N<M){cout<<1<<endl;return 0;}
 // state vector (f(i), f(i-1), ..., f(i-M+1)); f(i+1)=f(i)+f(i-M+1)
 Mat T(M,vector<ll>(M,0));T[0][0]=1;T[0][M-1]=1;for(int i=1;i<M;i++)T[i][i-1]=1;
 Mat R(M,vector<ll>(M,0));for(int i=0;i<M;i++)R[i][i]=1;ll e=N-(M-1);
 while(e){if(e&1)R=mul(R,T);T=mul(T,T);e>>=1;}
 ll ans=0;for(int j=0;j<M;j++)ans=(ans+R[0][j])%P; // initial vector all ones (f(M-1..0)=1)
 cout<<ans<<endl;}

#include <bits/stdc++.h>
using namespace std;typedef long long ll;
ll A,B,h,w;int n;vector<ll>e;
int solve(ll X,ll Y){ll nh=(X+h-1)/h,nw=(Y+w-1)/w;if(nh<=1&&nw<=1)return 0;
  vector<ll>dp(nh+1,-1),nd;dp[1]=1;
  for(int i=0;i<(int)e.size();i++){nd=dp;for(ll x=1;x<=nh;x++)if(dp[x]>=0){
      ll nx=min(nh,x*e[i]);nd[nx]=max(nd[nx],dp[x]);nd[x]=max(nd[x],min(nw,dp[x]*e[i]));}
    dp=nd;if(dp[nh]>=nw)return i+1;}
  return INT_MAX;}
int main(){cin>>A>>B>>h>>w>>n;e.resize(n);for(auto&x:e)cin>>x;sort(e.rbegin(),e.rend());
  if((int)e.size()>34)e.resize(34);
  int r=min(solve(A,B),solve(B,A));cout<<(r==INT_MAX?-1:r)<<endl;}

