int brute(const string&s,const string&t,int l,int r){string a=s.substr(l,r-l+1),b=t.substr(l,r-l+1);int k=a.size();
 for(int i=0;i+2<k;i++)if(a[i]=='0'&&a[i+2]=='0')b[i+1]='1';   // op1 first (uses original zeros)
 for(int i=0;i+2<k;i++)if(b[i]=='1'&&b[i+2]=='1')a[i+1]='1';
 return count(a.begin(),a.end(),'1');}
int main(){int T;scanf("%d",&T);while(T--){int n;static char S[200005],Tt[200005];scanf("%d %s %s",&n,S,Tt);string s(S),t(Tt);
 string tb=t,sa=s;for(int i=1;i+1<n;i++)if(s[i-1]=='0'&&s[i+1]=='0')tb[i]='1';
 for(int i=1;i+1<n;i++)if(tb[i-1]=='1'&&tb[i+1]=='1')sa[i]='1';
 vector<int>P(n+1,0);for(int i=0;i<n;i++)P[i+1]=P[i]+(sa[i]=='1');
 int q;scanf("%d",&q);while(q--){int l,r;scanf("%d %d",&l,&r);l--;r--;
  if(r-l+1<=6){printf("%d\n",brute(s,t,l,r));continue;}
  int ans=P[r-1]-P[l+2];                               // interior l+2..r-2 behaves like the full string
  ans+=(s[l]=='1')+(s[r]=='1');                        // ends never change
  ans+=(s[l+1]=='1'||(t[l]=='1'&&tb[l+2]=='1'));       // b_l can't be changed inside the substring
  ans+=(s[r-1]=='1'||(tb[r-2]=='1'&&t[r]=='1'));
  printf("%d\n",ans);}}}

