int main(){int t;scanf("%d",&t);while(t--){int n;scanf("%d",&n);vector<vector<int>>g(n+1);
  for(int i=0;i<n-1;i++){int u,v;scanf("%d %d",&u,&v);g[u].push_back(v);g[v].push_back(u);}
  vector<int>par(n+1,0),ord={1},cnt(n+1,0);par[1]=-1;
  for(size_t i=0;i<ord.size();i++){int u=ord[i];for(int w:g[u])if(w!=par[u]){par[w]=u;ord.push_back(w);}}
  int L=0;for(int v=1;v<=n;v++)if(g[v].size()<=1){cnt[v]=1;L++;}
  for(int i=n-1;i>0;i--)cnt[par[ord[i]]]+=cnt[ord[i]];
  long long base=0;for(int v=2;v<=n;v++)base+=cnt[v]&1; // edge v-par[v]
  if(L%2==0){printf("%lld\n",base);continue;}
  vector<int>delta(n+1,0);int best=INT_MAX; // delta = sum over path edges of (even?+1:-1)
  for(int i=1;i<n;i++){int v=ord[i];delta[v]=delta[par[v]]+((cnt[v]&1)?-1:1);}
  for(int v=1;v<=n;v++)if(g[v].size()<=1)best=min(best,delta[v]);
