#include <bits/stdc++.h>
using namespace std;
int H,T,R,n,m;vector<int>hh,ht,th,tt;vector<vector<int>>col,lp;bool cyc=false;
vector<pair<int,int>> nxt(int h,int t){vector<pair<int,int>>r; // (-1,-1) = dragon wins
  for(int i=1;i<=min(n,h);i++){int a=h-i+hh[i],b=t+ht[i];r.push_back(a+b>R?make_pair(-1,-1):make_pair(a,b));}
  for(int j=1;j<=min(m,t);j++){int a=h+th[j],b=t-j+tt[j];r.push_back(a+b>R?make_pair(-1,-1):make_pair(a,b));}return r;}
int dfs(int h,int t){ // longest #blows until the dragon wins; detects cycles
  if(col[h][t]==2)return lp[h][t];if(col[h][t]==1){cyc=true;return 0;}col[h][t]=1;int b=0;
  for(auto[a,c]:nxt(h,t)){if(a<0)b=max(b,1);else b=max(b,1+dfs(a,c));if(cyc)return 0;}
  col[h][t]=2;return lp[h][t]=b;}
int main(){cin>>H>>T>>R>>n;hh.resize(n+1);ht.resize(n+1);for(int i=1;i<=n;i++)cin>>hh[i]>>ht[i];
