#include <bits/stdc++.h>
using namespace std;
int n,m;vector<vector<int>>g;vector<char>att;
vector<int> bfs(int s){vector<int>d(n+1,-1);queue<int>q;q.push(s);d[s]=0;while(!q.empty()){int u=q.front();q.pop();for(int v:g[u])if(d[v]<0){d[v]=d[u]+1;q.push(v);}}return d;}
int far(const vector<int>&d){int b=-1;for(int v=1;v<=n;v++)if(att[v]&&(b<0||d[v]>d[b]))b=v;return b;} // smallest index on ties
int main(){scanf("%d %d",&n,&m);g.resize(n+1);att.assign(n+1,0);for(int i=0;i<n-1;i++){int u,v;scanf("%d %d",&u,&v);g[u].push_back(v);g[v].push_back(u);}
  int any=0;for(int i=0;i<m;i++){int x;scanf("%d",&x);att[x]=1;any=x;}
  int u=far(bfs(any));auto du=bfs(u);int v=far(du);int diam=du[v];
  // count Steiner tree edges: nodes whose subtree (rooted at u) holds an attacked node
  vector<int>par(n+1,0),ord={u};par[u]=-1;for(size_t i=0;i<ord.size();i++){int x=ord[i];for(int y:g[x])if(y!=par[x]){par[y]=x;ord.push_back(y);}}
  vector<char>has(att);int cnt=0;for(int i=n-1;i>=0;i--){int x=ord[i];if(has[x]){cnt++;if(par[x]>0)has[par[x]]=1;}}
  printf("%d\n%d\n",min(u,v),2*(cnt-1)-diam);}

