#include <bits/stdc++.h>
using namespace std;
int par[1005];
int f(int x){return par[x]==x?x:par[x]=f(par[x]);}
int main(){
    int n,m,W; scanf("%d %d %d",&n,&m,&W);
    vector<int> w(n+1); vector<long long> b(n+1);
    for(int i=1;i<=n;i++) scanf("%d",&w[i]);
    for(int i=1;i<=n;i++) scanf("%lld",&b[i]);
    for(int i=1;i<=n;i++) par[i]=i;
    while(m--){int x,y;scanf("%d %d",&x,&y);par[f(x)]=f(y);}
    map<int,vector<int>> g; for(int i=1;i<=n;i++) g[f(i)].push_back(i);
    vector<long long> dp(W+1,0);
    for(auto& [r,mem]:g){
        vector<pair<int,long long>> opt; int sw=0; long long sb=0;
        for(int i:mem){opt.push_back({w[i],b[i]}); sw+=w[i]; sb+=b[i];}
        opt.push_back({sw,sb});
        vector<long long> nd=dp;
        for(auto [wt,bt]:opt) for(int c=W;c>=wt;c--) nd[c]=max(nd[c],dp[c-wt]+bt);
        dp=nd;
    }
    printf("%lld\n",dp[W]);
}

