 if(!dp[B][n]){puts("-1");return 0;}
 vector<char>inA(B,0);int s=n;for(int i=B;i>0;i--){if(dp[i-1][s])continue;inA[i-1]=1;s-=bl[i-1].second;}
 vector<int>A,Bv;for(int i=0;i<B;i++)for(int k=0;k<bl[i].second;k++)(inA[i]?A:Bv).push_back(c[bl[i].first+k]);
