string fix(string s){size_t i=0;while(i+1<s.size()&&s[i]=='0')i++;return s.substr(i);} // strip leading zeros, keep one "0"
string rem(string s,int r,int k){ // erase k rightmost digits with digit%3==r
 for(int i=s.size()-1;i>=0&&k;i--)if((s[i]-'0')%3==r){s.erase(i,1);k--;}return k?string():s;}
int main(){string s;cin>>s;int sum=0;for(char c:s)sum+=c-'0';int r=sum%3;
 if(r==0){cout<<s<<"\n";return 0;}
 string a=rem(s,r,1),b=rem(s,3-r,2),best;
 if(!a.empty())a=fix(a);if(!b.empty())b=fix(b);
 best=a.size()>=b.size()?a:b;cout<<(best.empty()?"-1":best)<<"\n";}

