int main(){f[0]=1;for(int i=1;i<N;i++)f[i]=f[i-1]*i%MOD;inv[N-1]=pw(f[N-1],MOD-2);for(int i=N-1;i>0;i--)inv[i-1]=inv[i]*i%MOD;
 int t;scanf("%d",&t);while(t--){int c[26];int L=0;for(int i=0;i<26;i++){scanf("%d",&c[i]);L+=c[i];}
  int O=(L+1)/2,E=L/2;vector<ll> w(O+1,0);w[0]=1;ll den=1;
