int main(){int t;scanf("%d",&t);while(t--){int n;scanf("%d",&n);vector<int>a(n);for(auto&x:a)scanf("%d",&x);
 int ans=0;vector<int>cnt(n+2),fe(n+2),ls(n+2);
 for(int L=1;2*L<=n;L++){fill(cnt.begin(),cnt.end(),0);fill(fe.begin(),fe.end(),INT_MAX);fill(ls.begin(),ls.end(),-1);
  deque<int>mn,mx;int dup=0;
  for(int r=0;r<n;r++){if(++cnt[a[r]]==2)dup++;
   while(!mn.empty()&&a[mn.back()]>=a[r])mn.pop_back();mn.push_back(r);
   while(!mx.empty()&&a[mx.back()]<=a[r])mx.pop_back();mx.push_back(r);
   if(r>=L){if(--cnt[a[r-L]]==1)dup--;}
   while(mn.front()<=r-L)mn.pop_front();while(mx.front()<=r-L)mx.pop_front();
   if(r>=L-1&&!dup&&a[mx.front()]-a[mn.front()]==L-1){int v=a[mn.front()];fe[v]=min(fe[v],r);ls[v]=max(ls[v],r-L+1);}}
  for(int v=1;v+L<=n;v++){int w=v+L;if(ls[v]<0||ls[w]<0)continue;
   if(fe[v]<ls[w]||fe[w]<ls[v]){ans=L;break;}}}
 printf("%d\n",ans);}}

