#include <bits/stdc++.h>
using namespace std;
int solve(vector<long long>a,vector<long long>b){if(a.empty()||b.empty())return 0;
 int n=a.size();set<long long>sb(b.begin(),b.end());vector<int>suf(n+1,0);
 for(int i=n-1;i>=0;i--)suf[i]=suf[i+1]+(int)sb.count(a[i]);int best=suf[0];
 for(long long x:b){int t=upper_bound(a.begin(),a.end(),x)-a.begin();if(t==0)continue;
  int c=upper_bound(b.begin(),b.end(),x)-lower_bound(b.begin(),b.end(),x-t+1);
  best=max(best,c+suf[t]);}
 return best;}
int main(){int T;scanf("%d",&T);while(T--){int n,m;scanf("%d %d",&n,&m);vector<long long>a(n),b(m);
 for(auto&x:a)scanf("%lld",&x);for(auto&x:b)scanf("%lld",&x);
 vector<long long>ap,an,bp,bn;
 for(auto x:a)(x>0?ap:an).push_back(llabs(x));for(auto x:b)(x>0?bp:bn).push_back(llabs(x));
 reverse(an.begin(),an.end());reverse(bn.begin(),bn.end());
 printf("%d\n",solve(ap,bp)+solve(an,bn));}}

typedef long long ll;
ll f(ll n){if(n<0)return 0;ll r=n%4;return r==0?n:r==1?1:r==2?n+1:0;}
ll X(ll l,ll r){return f(r)^f(l-1);}
ll solve(ll l,ll r,int i,ll k){
  ll m=1LL<<i, ans=X(l,r);
  if(r<k) return ans;
  ll lo = l<=k?0:(l-k+m-1)/m, hi=(r-k)/m;
  if(lo>hi) return ans;
  ll ex=X(lo,hi)<<i; if((hi-lo+1)&1) ex|=k;
  return ans^ex;
}

