int f(int m,int k){ // min #factors (each <=k) whose product is m; INF if impossible
 vector<int>d;for(int i=1;(long long)i*i<=m;i++)if(m%i==0){d.push_back(i);if(i!=m/i)d.push_back(m/i);}
 sort(d.begin(),d.end());vector<int>dp(d.size(),INT_MAX);dp[0]=0; // dp over divisors
 for(size_t i=1;i<d.size();i++)for(size_t j=0;j<i;j++)if(d[i]%d[j]==0&&d[i]/d[j]<=k&&dp[j]!=INT_MAX)dp[i]=min(dp[i],dp[j]+1);
 return dp.back();}
