typedef long long ll;
int main(){int t;scanf("%d",&t);while(t--){int n,k;ll x;scanf("%d %d %lld",&n,&k,&x);vector<ll>a(n);for(auto&v:a)scanf("%lld",&v);
 const ll NEG=LLONG_MIN/4;vector<ll>dp(k+1,NEG),nd(k+1);dp[0]=0;ll ans=0; // dp[j]: best sum ending here (or empty), j pluses used so far
 for(int i=0;i<n;i++){for(int j=0;j<=k;j++){nd[j]=NEG;
   if(j>i+1||i+1-j>n-k)continue;               // impossible split of the prefix
   ll best=0;                                   // start fresh (element outside the subarray)
   if(dp[j]>NEG)best=max(best,dp[j]+a[i]-x);
   if(j&&dp[j-1]>NEG)best=max(best,dp[j-1]+a[i]+x);
   nd[j]=best;ans=max(ans,best);}
  swap(dp,nd);}
 printf("%lld\n",ans);}}

