#include <bits/stdc++.h>
using namespace std;
const int M=998244353,OFF=90000;
int main(){int n;scanf("%d",&n);vector<int>a(n);for(auto&x:a)scanf("%d",&x);
 vector<long long>dp(2*OFF+1,0),nd(2*OFF+1);dp[a[1]+OFF]=1; // dp[v] = ways current middle value a[i] equals v
 for(int i=1;i<=n-2;i++){fill(nd.begin(),nd.end(),0);
  for(int v=-OFF;v<=OFF;v++){long long w=dp[v+OFF];if(!w)continue;int nx=a[i+1];
   nd[nx+v+OFF]=(nd[nx+v+OFF]+w)%M;
   if(v!=0)nd[nx-v+OFF]=(nd[nx-v+OFF]+w)%M;} // v==0: both directions give the same array
  swap(dp,nd);}
 long long ans=0;for(auto w:dp)ans=(ans+w)%M;printf("%lld\n",ans);}

