const long long M=1e9+7;const int N=1000100;int spf[N];long long f[N],inv[N];
long long pw(long long b,long long e){long long r=1;b%=M;while(e){if(e&1)r=r*b%M;b=b*b%M;e>>=1;}return r;}
long long C(int n,int k){return f[n]*inv[k]%M*inv[n-k]%M;}
int main(){for(int i=2;i<N;i++)if(!spf[i])for(int j=i;j<N;j+=i)if(!spf[j])spf[j]=i;
 f[0]=1;for(int i=1;i<N;i++)f[i]=f[i-1]*i%M;inv[N-1]=pw(f[N-1],M-2);for(int i=N-1;i>0;i--)inv[i-1]=inv[i]*i%M;
 int q;scanf("%d",&q);while(q--){int x,y;scanf("%d %d",&x,&y);long long ans=pw(2,y-1);
  while(x>1){int p=spf[x],e=0;while(x%p==0){x/=p;e++;}ans=ans*C(e+y-1,y-1)%M;}
  printf("%lld\n",ans);}}

