int main(){int n,m;string s;cin>>n>>s>>m;
  // cb[p][i]: # of 'b' at positions <i with parity p; ca similarly; cq = # of '?'
  vector<array<int,2>>ca(n+1,{0,0}),cb(n+1,{0,0});vector<int>cq(n+1,0);
  for(int i=0;i<n;i++){ca[i+1]=ca[i];cb[i+1]=cb[i];cq[i+1]=cq[i]+(s[i]=='?');
    if(s[i]=='a')ca[i+1][i&1]++;if(s[i]=='b')cb[i+1][i&1]++;}
  vector<pair<int,int>>dp(n+1,{0,0}); // (count, -cost)
  for(int i=1;i<=n;i++){dp[i]=dp[i-1];if(i>=m){int st=i-m,p=st&1;
      bool ok=cb[i][p]-cb[st][p]==0&&ca[i][p^1]-ca[st][p^1]==0;
      if(ok){pair<int,int>c={dp[st].first+1,dp[st].second-(cq[i]-cq[st])};dp[i]=max(dp[i],c);}}}
  cout<<-dp[n].second<<endl;}

