using namespace std;
int main(){int t;scanf("%d",&t);while(t--){int n,k;scanf("%d %d",&n,&k);vector<int>x(k);for(auto&v:x)scanf("%d",&v);
 vector<vector<int>>g(n+1);for(int i=0;i<n-1;i++){int u,v;scanf("%d %d",&u,&v);g[u].push_back(v);g[v].push_back(u);}
 vector<int>df(n+1,-1);queue<int>q;for(int v:x){df[v]=0;q.push(v);}
 while(!q.empty()){int u=q.front();q.pop();for(int w:g[u])if(df[w]<0){df[w]=df[u]+1;q.push(w);}}
 vector<int>d(n+1,-1),par(n+1,0),ord={1};d[1]=0;
 for(int i=0;i<(int)ord.size();i++){int u=ord[i];for(int w:g[u])if(d[w]<0){d[w]=d[u]+1;par[w]=u;ord.push_back(w);}}
 vector<long long>res(n+1,0);vector<char>bad(n+1,0);
 for(int i=n-1;i>=0;i--){int v=ord[i];
  if(v!=1&&df[v]<=d[v]){res[v]=1;bad[v]=0;}
  else if(v!=1&&g[v].size()==1){bad[v]=1;}
  if(v!=1){int p=par[v];if(bad[v])bad[p]=1;else res[p]+=res[v];}}
 // note: children's contributions were added before v is finalized; reset if v itself is cut
 printf("%lld\n",bad[1]?-1LL:res[1]);}}

