 vector<ll>f(n+1,1);for(int i=1;i<=n;i++)f[i]=f[i-1]*i%p;ll ans=0;
 // fix the last removed peg; s = removed pegs on its two sides inside the final run (each side <= t-1, s+1 >= t)
 for(int s=t-1;s<=n-2;s++){ll pairs=0;for(int x=0;x<=t-1;x++){int y=s-x;if(y>=0&&y<=t-1)pairs++;}if(!pairs)continue;
  int m=max(0LL,n-s-3);ll sum=0;for(int k=0;k<=m;k++)sum=(sum+C[m][k]*f[s+k])%p; // k more pegs removed elsewhere, any order
  ans=(ans+pairs%p*sum)%p;}
 cout<<ans*(n%p)%p<<"\n";}

