  if(r>0)for(int pa=0;pa<A&&!done;pa++)if((pa*10+d)%A==a&&vis[i-1][pa][b][r-1]){res[i-1]='R';a=pa;r--;done=true;}
  if(!done)for(int pb=0;pb<B&&!done;pb++)if((pb*10+d)%B==b&&vis[i-1][a][pb][r]){res[i-1]='B';b=pb;done=true;}}
 puts(res.c_str());}}

