using namespace std;typedef long long ll;
int main(){int n,k;scanf("%d %d",&n,&k);vector<vector<pair<int,int>>>g(n);
  for(int i=0;i<n-1;i++){int u,v,c;scanf("%d %d %d",&u,&v,&c);g[u].push_back({v,c});g[v].push_back({u,c});}
  vector<int>par(n,-1),ord={0};vector<char>vis(n,0);vis[0]=1;
  for(size_t i=0;i<ord.size();i++){int u=ord[i];for(auto[v,c]:g[u])if(!vis[v]){vis[v]=1;par[v]=u;ord.push_back(v);}}
  vector<ll>d0(n,0),d1(n,0);
  for(int i=n-1;i>=0;i--){int v=ord[i];vector<pair<ll,ll>>ch; // (a=dp0+w, b=dp1+w)
    for(auto[c,w]:g[v])if(par[c]==v)ch.push_back({d0[c]+w,d1[c]+w});
    sort(ch.rbegin(),ch.rend());int r=k-1,sz=ch.size();
    ll top=0;for(int j=0;j<min(r,sz);j++)top+=ch[j].first;d0[v]=top;
    ll topk=top+(r<sz?ch[r].first:0),best=top;
    for(int j=0;j<sz;j++){ll v2=ch[j].second+(j<r?topk-ch[j].first:top);best=max(best,v2);}
    d1[v]=best;}
  printf("%lld\n",d1[0]);}

