#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
pair<ll,ll> best;
void rec(ll m,ll cnt,ll used){ // greedy tower of remaining volume m
 if(m==0){best=max(best,make_pair(cnt,used));return;}
 ll a=cbrtl((long double)m);while((a+1)*(a+1)*(a+1)<=m)a++;while(a*a*a>m)a--;
 rec(m-a*a*a,cnt+1,used+a*a*a);                     // take the biggest cube a^3
 if(a>1)rec(a*a*a-1-(a-1)*(a-1)*(a-1),cnt+1,used+(a-1)*(a-1)*(a-1)); // take (a-1)^3, cap rest below a^3
}
int main(){ll m;cin>>m;rec(m,0,0);cout<<best.first<<" "<<best.second<<endl;}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;const ll INF=LLONG_MAX/4;
int main(){int T;scanf("%d",&T);while(T--){int n,m;scanf("%d %d",&n,&m);vector<ll>a(n);for(auto&x:a)scanf("%lld",&x);
 vector<vector<int>>opt(n);vector<ll>tt(m);vector<int>pp(m);
 for(int i=0;i<m;i++){int e;scanf("%d %lld %d",&e,&tt[i],&pp[i]);opt[e-1].push_back(i);}
 ll time=0;bool ok=true;vector<int>res;
 for(int task=0;task<n&&ok;task++){auto&o=opt[task];int c=o.size();
  // 0/1 knapsack: dp[j][p] = min time using first j options to reach p% (capped at 100)
  vector<vector<ll>>dp(c+1,vector<ll>(101,INF));dp[0][0]=0;
  for(int j=0;j<c;j++){int id=o[j];for(int p=0;p<=100;p++){dp[j+1][p]=min(dp[j+1][p],dp[j][p]);
    if(dp[j][p]<INF){int np=min(100,p+pp[id]);dp[j+1][np]=min(dp[j+1][np],dp[j][p]+tt[id]);}}}
  if(dp[c][100]>=INF||time+dp[c][100]>a[task]){ok=false;break;}
  time+=dp[c][100];
  // reconstruct
  int p=100;for(int j=c;j>0;j--){if(dp[j][p]==dp[j-1][p])continue;int id=o[j-1];res.push_back(id+1);
   // find previous p
   for(int q=0;q<=100;q++)if(dp[j-1][q]<INF&&min(100,q+pp[id])==p&&dp[j-1][q]+tt[id]==dp[j][p]){p=q;break;}}}
 if(!ok){puts("-1");continue;}
 printf("%d\n",(int)res.size());for(int x:res)printf("%d ",x);puts("");}}

