#include <bits/stdc++.h>
using namespace std;
int main(){int t;scanf("%d",&t);while(t--){int n;static char r0[100005],r1[100005];scanf("%d %s %s",&n,r0,r1);
 auto A=[&](int row,int c){return (row?r1[c]:r0[c])=='A';};
 auto w=[&](int x,int y,int z){return (x+y+z)>=2?1:0;};
 const int NEG=-1e9;vector<array<int,3>>dp(n+4,{NEG,NEG,NEG});dp[0][0]=0;
 auto up=[&](int i,int s,int v){if(i<=n&&v>dp[i][s])dp[i][s]=v;};
 for(int i=0;i<n;i++){
  int v=dp[i][0];if(v>NEG){
   if(i+1<n){up(i+1,1,v+w(A(0,i),A(1,i),A(0,i+1)));up(i+1,2,v+w(A(0,i),A(1,i),A(1,i+1)));}
   if(i+2<n)up(i+3,0,v+w(A(0,i),A(0,i+1),A(0,i+2))+w(A(1,i),A(1,i+1),A(1,i+2)));}
  for(int s=1;s<=2;s++){v=dp[i][s];if(v<=NEG)continue;int o=(s==1)?1:0,f=1-o;
   if(i+1<n)up(i+2,0,v+w(A(o,i),A(o,i+1),A(f,i+1)));
   if(i+3<n)up(i+3,s,v+w(A(o,i),A(o,i+1),A(o,i+2))+w(A(f,i+1),A(f,i+2),A(f,i+3)));}}
 printf("%d\n",dp[n][0]);}}

