  vector<ll>nd=dp;
  for(int j=0;j<10;j++){if(dp[j]==LLONG_MIN)continue;for(int cnt=1;cnt<=3;cnt++)for(auto[s,mx]:opt[cnt]){
   ll v=dp[j]+s+(j+cnt>=10?mx:0);int nj=(j+cnt)%10;nd[nj]=max(nd[nj],v);}}
  dp=nd;}
 printf("%lld\n",*max_element(dp.begin(),dp.end()));}

