using namespace std;typedef long long ll;
ll ev(const vector<ll>&num,const string&op){ll sum=0,term=num[0]; // op[i] between num[i],num[i+1]
  for(size_t i=0;i<op.size();i++){if(op[i]=='*')term*=num[i+1];else{sum+=term;term=num[i+1];}}return sum+term;}
int main(){string s;cin>>s;int k=s.size()/2+1;vector<ll>num(k);string op;
  for(int i=0;i<k;i++)num[i]=s[2*i]-'0';for(int i=0;i<k-1;i++)op+=s[2*i+1];
  vector<int>st={0},en={k-1};for(int i=0;i<k-1;i++)if(op[i]=='*'){st.push_back(i+1);en.push_back(i);}
  ll best=ev(num,op);
  for(int l:st)for(int r:en)if(l<r){ // bracket numbers l..r
    vector<ll>in(num.begin()+l,num.begin()+r+1);ll v=ev(in,op.substr(l,r-l));
    vector<ll>nn(num.begin(),num.begin()+l);nn.push_back(v);nn.insert(nn.end(),num.begin()+r+1,num.end());
    string no=op.substr(0,l)+op.substr(r);best=max(best,ev(nn,no));}
  cout<<best<<endl;}

