#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
vector<int>par,st,len;vector<array<char,2>>hm; // hm[root][parity]: segment has a global max at that absolute index parity
int fnd(int x){while(par[x]!=x)x=par[x]=par[par[x]];return x;}
bool good(int r){return len[r]%2==0?(hm[r][0]||hm[r][1]):hm[r][st[r]%2];} // can take ceil(len/2) incl. a max
int main(){int t;scanf("%d",&t);while(t--){int n;scanf("%d",&n);vector<ll>a(n);for(auto&x:a)scanf("%lld",&x);
 ll M=*max_element(a.begin(),a.end());par.resize(n);st.resize(n);len.assign(n,0);hm.assign(n,{0,0});
 vector<int>ord(n);iota(ord.begin(),ord.end(),0);sort(ord.begin(),ord.end(),[&](int i,int j){return a[i]>a[j];});
 vector<char>act(n,0);ll cnt=0;int goodSeg=0;ll best=0;
 auto rem=[&](int r){cnt-=(len[r]+1)/2;goodSeg-=good(r);};auto add=[&](int r){cnt+=(len[r]+1)/2;goodSeg+=good(r);};
 for(int idx=0;idx<n;idx++){int i=ord[idx];act[i]=1;par[i]=i;st[i]=i;len[i]=1;hm[i]={0,0};if(a[i]==M)hm[i][i%2]=1;add(i);
  for(int j:{i-1,i+1})if(j>=0&&j<n&&act[j]){int x=fnd(i),y=fnd(j);rem(x);rem(y);par[y]=x;st[x]=min(st[x],st[y]);len[x]+=len[y];
   hm[x][0]|=hm[y][0];hm[x][1]|=hm[y][1];add(x);}
  if(idx+1<n&&a[ord[idx+1]]==a[i])continue; // finish the whole group of equal values first
  best=max(best,M+a[i]+cnt-(goodSeg?0:1));}
 printf("%lld\n",best);}}

