int main(){int n;ll x,y;scanf("%d %lld %lld",&n,&x,&y);vector<vector<int>>g(n+1);
 for(int i=1;i<n;i++){int u,v;scanf("%d %d",&u,&v);g[u].push_back(v);g[v].push_back(u);}
 if(x>=y){bool star=false;for(int v=1;v<=n;v++)if((int)g[v].size()==n-1)star=true;
  printf("%lld\n",star?(ll)(n-2)*y+x:(ll)(n-1)*y);return 0;} // avoid tree edges; a star forces one
 // x<y: max number of tree edges in a vertex-disjoint path cover (greedy from leaves)
 vector<int>par(n+1,0),ord={1};for(size_t i=0;i<ord.size();i++)for(int u:g[ord[i]])if(u!=par[ord[i]]){par[u]=ord[i];ord.push_back(u);}
 vector<int>freeEnd(n+1,1);ll used=0; // freeEnd[v]: v can still accept an edge to its parent
 for(int k=n-1;k>=0;k--){int v=ord[k];int take=0;for(int u:g[v])if(u!=par[v]&&freeEnd[u]&&take<2)take++;
  used+=take;freeEnd[v]=(take<2);}
 printf("%lld\n",used*x+(n-1-used)*y);}

