typedef long long ll;vector<vector<int>>ch;vector<ll>s;
pair<ll,ll> dfs(int u,ll cnt){ // returns {value, gain of one extra path}
 ll val=s[u]*cnt; int c=ch[u].size(); if(!c) return {val,s[u]};
 ll q=cnt/c,r=cnt%c; vector<ll> g;
 for(int v:ch[u]){auto [a,b]=dfs(v,q);val+=a;g.push_back(b);}
 sort(g.rbegin(),g.rend()); for(int i=0;i<r;i++)val+=g[i];
 return {val,s[u]+g[r]};}
