int main(){int t;scanf("%d",&t);while(t--){long long n,k;scanf("%lld %lld",&n,&k);int pc=__builtin_popcountll(n);
 if(k>=31){printf("%lld\n",pc+k-1);continue;}
 if(k==0){printf("0\n");continue;}
 int K=k;const int INF=1e9,B=62; // dp[carry][used][sv]
 static int dp[2][32][32],nd[2][32][32];
 for(auto&a:dp)for(auto&b:a)for(auto&c:b)c=INF; dp[0][0][0]=0;
 for(int b=0;b<B;b++){for(auto&a:nd)for(auto&x:a)for(auto&c:x)c=INF;int nb=(n>>b)&1;
  for(int c=0;c<2;c++)for(int u=0;u<=K;u++)for(int sv=0;sv<=K;sv++){int v=dp[c][u][sv];if(v>=INF)continue;
   for(int s=0;s<2;s++){int nu=u+s;if(nu>K)continue;int tot=nb+c+s;
    int nsv=sv; if(s){ long long add = b<6?(1LL<<b):K; nsv=(int)min<long long>(K,sv+add);}
    int &r=nd[tot>>1][nu][nsv]; r=min(r,v+(tot&1));}}
  memcpy(dp,nd,sizeof dp);}
 int best=INF;for(int u=0;u<=K;u++)best=min(best,dp[0][u][K]);
 printf("%d\n",pc+K-best);}}

