 for(long long p=2;p*p<=t;p++)if(t%p==0){pr.push_back(p);while(t%p==0)t/=p;}if(t>1)pr.push_back(t);
 long long ans=0;int k=pr.size();
 for(int mask=0;mask<(1<<k);mask++){long long d=1;for(int i=0;i<k;i++)if(mask>>i&1)d*=pr[i];
  long long term=pw(2,s/d-1);if(__builtin_popcount(mask)&1)ans=(ans-term+M)%M;else ans=(ans+term)%M;}
