using namespace std;typedef long long ll;const ll M=998244353;
ll pw(ll b,ll e){ll r=1;b%=M;while(e){if(e&1)r=r*b%M;b=b*b%M;e>>=1;}return r;}
int main(){int n,x;cin>>n>>x;vector<vector<ll>>C(n+1,vector<ll>(n+1,0));for(int i=0;i<=n;i++){C[i][0]=1;for(int j=1;j<=i;j++)C[i][j]=(C[i-1][j-1]+C[i-1][j])%M;}
 vector<vector<ll>>dp(n+1,vector<ll>(x+1,0));for(int j=0;j<=x;j++)dp[0][j]=1;
 for(int i=2;i<=n;i++)for(int j=1;j<=x;j++){
  if(j<=i-1){dp[i][j]=pw(j,i);continue;}
  ll s=0,p=1; // p=(i-1)^k
  for(int k=0;k<=i;k++){if(i-k!=1)s=(s+C[i][k]*p%M*dp[i-k][j-i+1])%M;p=p*(i-1)%M;}
  dp[i][j]=s;}
 cout<<dp[n][x]<<endl;}

