    f[L]=dp[n];g[L]=(f[L]-f[L-1]+MOD)%MOD;}
  long long ans=0;for(long long a=1;a<=n;a++)for(long long b=1;b<=n&&a*b<k;b++)ans=(ans+g[a]*g[b])%MOD;
