using namespace std;typedef long long ll;
int n,m;ll mod;vector<vector<ll>>memo;
ll f(int c1,int c2){if(c1==0&&c2==0)return 1;ll&r=memo[c1][c2];if(r>=0)return r;r=0;
  if(c2>=2)r=(r+(ll)c2*(c2-1)/2%mod*f(c1+2,c2-2))%mod;
  if(c1>=1&&c2>=1)r=(r+(ll)c1*c2%mod*f(c1,c2-1))%mod;
  if(c1>=2)r=(r+(ll)c1*(c1-1)/2%mod*f(c1-2,c2))%mod;return r;}
int main(){cin>>n>>m>>mod;vector<int>col(n,0);for(int i=0;i<m;i++){string s;cin>>s;for(int j=0;j<n;j++)col[j]+=s[j]=='1';}
  int c1=0,c2=0;for(int x:col){if(x==0)c2++;else if(x==1)c1++;}
  memo.assign(n+1,vector<ll>(n+1,-1));cout<<f(c1,c2)%mod<<endl;}

#include <bits/stdc++.h>
using namespace std;typedef long long ll;const ll M=998244353;
int main(){int n;scanf("%d",&n);vector<int>A(n+1);for(int i=1;i<=n;i++)scanf("%d",&A[i]);
  vector<int>inc(n+1);for(int i=1;i<=n;i++)inc[i]=(i>1&&A[i-1]<A[i])?inc[i-1]:i;
  vector<ll>pw(n+1,1);for(int i=1;i<=n;i++)pw[i]=pw[i-1]*2%M;
  vector<ll>dp(n+1,0),G(n+2,0);dp[1]=1; // p=0 popped, discovered up to 1
  for(int p=0;p<n;p++){ // pop A[p+1]; need r>=p+1
    G.assign(n+2,0);for(int r=1;r<=n;r++){ll g=(r>=p+1)?dp[r]*pw[r-p-1]%M:0;G[r]=(G[r-1]+g)%M;}
    vector<ll>nd(n+1,0);for(int r2=p+1;r2<=n;r2++){int lo=max(p+1,inc[r2]-1);if(lo>r2)continue;nd[r2]=(G[r2]-G[lo-1]+M)%M;}
    dp=nd;}
  printf("%lld\n",dp[n]);}

