int main(){int n,k;scanf("%d %d",&n,&k);vector<ll>c(n+2);for(int i=1;i<=n;i++){ll a;scanf("%lld",&a);c[i]=a-i;}
  vector<int>b={0};for(int j=0;j<k;j++){int x;scanf("%d",&x);b.push_back(x);}b.push_back(n+1);
  c[0]=LLONG_MIN/4;c[n+1]=LLONG_MAX/4;int ans=0;
  for(size_t j=0;j+1<b.size();j++){int L=b[j],R=b[j+1];if(c[L]>c[R]){puts("-1");return 0;}
    vector<ll>t; // longest non-decreasing subsequence of values in [c[L], c[R]]
    for(int i=L+1;i<R;i++){if(c[i]<c[L]||c[i]>c[R])continue;auto it=upper_bound(t.begin(),t.end(),c[i]);if(it==t.end())t.push_back(c[i]);else *it=c[i];}
    ans+=(R-L-1)-t.size();}
  printf("%d\n",ans);}

