int main(){int n,m;cin>>n>>m;vector<int>x(n),s(n);for(int i=0;i<n;i++)cin>>x[i]>>s[i];
  vector<int>dp(m+2,0); // dp[p]: min cost to cover positions p+1..m
  for(int p=m-1;p>=0;p--){int q=p+1;bool cov=false;for(int i=0;i<n;i++)if(x[i]-s[i]<=q&&q<=x[i]+s[i])cov=true;
    if(cov){dp[p]=dp[p+1];continue;}dp[p]=m-p;
    for(int i=0;i<n;i++){int L=x[i]-s[i];if(L>q){int c=L-q;int R=min(m,x[i]+s[i]+c);dp[p]=min(dp[p],c+dp[R]);}}}
  cout<<dp[0]<<endl;}

