#include <bits/stdc++.h>
using namespace std;
int main(){
    int t; scanf("%d",&t);
    while(t--){
        int n; scanf("%d",&n); vector<long long> a(n+1);
        for(int i=1;i<=n;i++) scanf("%lld",&a[i]);
        vector<vector<int>> g(n+1);
        for(int i=0;i<n-1;i++){int u,v;scanf("%d %d",&u,&v);g[u].push_back(v);g[v].push_back(u);}
        vector<int> par(n+1,0),ord,sz(n+1,1),st={1}; par[1]=-1;
        while(!st.empty()){int u=st.back();st.pop_back();ord.push_back(u);
            for(int w:g[u]) if(w!=par[u]){par[w]=u;st.push_back(w);}}
        for(int i=n-1;i>0;i--) sz[par[ord[i]]]+=sz[ord[i]];
        long long ans=0;
        for(int m=1;m<=n;m++){
            long long r=llround(sqrt((double)a[m])); if(r*r!=a[m]) continue;
            long long e1=0,e2=0,e3=0;
            auto add=[&](long long s){e3+=e2*s;e2+=e1*s;e1+=s;};
            for(int c:g[m]) if(c!=par[m]) add(sz[c]);
            if(m!=1) add(n-sz[m]);
            ans+=e2+e3;
        }
        printf("%lld\n",ans);
    }
}

