int main(){int t;scanf("%d",&t);while(t--){long long x,y;scanf("%lld %lld",&x,&y);const int B=31;const long long INF=LLONG_MAX/4;
 long long dp[B+1][3][3];int pr[B+1][3][3][3];for(auto&a:dp)for(auto&b:a)for(auto&c:b)c=INF;dp[B][0][0]=0;
 auto step=[&](int s,int bit,int xb,long long w,long long&c){if(s==0){if(bit==xb)return 0;c+=w;return bit>xb?1:2;}c+=(s==1?(bit-xb):(xb-bit))*w;return s;};
 for(int i=B-1;i>=0;i--){long long w=1LL<<i;int xb=x>>i&1,yb=y>>i&1;
  for(int a=0;a<3;a++)for(int b=0;b<3;b++){if(dp[i+1][a][b]>=INF)continue;
   int ch[3][2]={{0,0},{1,0},{0,1}};
   for(int k=0;k<3;k++){long long c=dp[i+1][a][b];int na=step(a,ch[k][0],xb,w,c),nb=step(b,ch[k][1],yb,w,c);
    if(c<dp[i][na][nb]){dp[i][na][nb]=c;pr[i][na][nb][0]=a;pr[i][na][nb][1]=b;pr[i][na][nb][2]=k;}}}}
 int a=0,b=0;long long best=INF;for(int i=0;i<3;i++)for(int j=0;j<3;j++)if(dp[0][i][j]<best){best=dp[0][i][j];a=i;b=j;}
 long long p=0,q=0;int ch[3][2]={{0,0},{1,0},{0,1}};
 for(int i=0;i<B;i++){int k=pr[i][a][b][2],na=pr[i][a][b][0],nb=pr[i][a][b][1];p|=(long long)ch[k][0]<<i;q|=(long long)ch[k][1]<<i;a=na;b=nb;}
 printf("%lld %lld\n",p,q);}}

