#include <bits/stdc++.h>
using namespace std;
typedef long long ll;int M;vector<pair<int,int>>tr; // (best length, index) max segment tree
void upd(int p,pair<int,int>v){for(tr[p+=M]=max(tr[p+M],v);p>1;p>>=1)tr[p>>1]=max(tr[p],tr[p^1]);}
pair<int,int> qry(int l,int r){pair<int,int>res{0,-1};for(l+=M,r+=M+1;l<r;l>>=1,r>>=1){if(l&1)res=max(res,tr[l++]);if(r&1)res=max(res,tr[--r]);}return res;}
int main(){int n;ll d;scanf("%d %lld",&n,&d);vector<ll>h(n);for(auto&x:h)scanf("%lld",&x);
 vector<ll>s=h;sort(s.begin(),s.end());s.erase(unique(s.begin(),s.end()),s.end());M=s.size();tr.assign(2*M,{0,-1});
 vector<int>dp(n),pr(n);int bi=0;
 for(int i=0;i<n;i++){pair<int,int>b{0,-1};
  int hi=upper_bound(s.begin(),s.end(),h[i]-d)-s.begin()-1;if(hi>=0)b=max(b,qry(0,hi));        // h_j <= h_i - d
  int lo=lower_bound(s.begin(),s.end(),h[i]+d)-s.begin();if(lo<M)b=max(b,qry(lo,M-1));          // h_j >= h_i + d
  dp[i]=b.first+1;pr[i]=b.second;upd(lower_bound(s.begin(),s.end(),h[i])-s.begin(),{dp[i],i});if(dp[i]>dp[bi])bi=i;}
 vector<int>res;for(int i=bi;i>=0;i=pr[i])res.push_back(i+1);reverse(res.begin(),res.end());
 printf("%d\n",(int)res.size());for(int v:res)printf("%d ",v);puts("");}

