int main(){int t;scanf("%d",&t);while(t--){int n;ll k,l;scanf("%d %lld %lld",&n,&k,&l);vector<ll>d(n);for(auto&x:d)scanf("%lld",&x);
 bool ok=true;ll tide=k;bool down=true; // at shore: may leave when the tide is k and falling
 for(int i=0;i<n&&ok;i++){if(d[i]+k<=l){tide=k;down=true;continue;} // always-safe cell resets state
  if(d[i]>l){ok=false;break;}ll lim=l-d[i];
  if(down){tide=min(tide-1,lim);if(tide<=0){tide=0;down=false;}} // wait earlier so we arrive at <= lim
  else{tide++;if(tide>lim)ok=false;}}
 puts(ok?"Yes":"No");}}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;const ll MOD=998244353;const int N=5005;
ll F[N],IF[N];ll pw(ll b,ll e){ll r=1;b%=MOD;while(e){if(e&1)r=r*b%MOD;b=b*b%MOD;e>>=1;}return r;}
ll C(int a,int b){return (b<0||a<0||b>a)?0:F[a]*IF[b]%MOD*IF[a-b]%MOD;}
int main(){F[0]=1;for(int i=1;i<N;i++)F[i]=F[i-1]*i%MOD;IF[N-1]=pw(F[N-1],MOD-2);for(int i=N-1;i>0;i--)IF[i-1]=IF[i]*i%MOD;
 int t;scanf("%d",&t);while(t--){int n;scanf("%d",&n);vector<int>a(n);for(auto&x:a)scanf("%d",&x);int k=n/2;
 vector<pair<int,int>>vals;for(int i=n-1;i>=0;){int j=i;while(j>=0&&a[j]==a[i])j--;vals.push_back({a[i],i-j});i=j;} // descending
 // peaks p_1<..<p_k at even positions; slot 1 and slot i+1 (i<k) take values < p_1 / < p_i.
 // processing values descending, state j = #peaks chosen; opened(j) = max(0,j-1) + (j==k)
 auto opened=[&](int j){return max(0,j-1)+(j==k?1:0);};
 vector<ll>dp(k+1,0),nd(k+1);dp[0]=1;int processed=0;
 for(auto [v,c]:vals){fill(nd.begin(),nd.end(),0);
  for(int j=0;j<=k;j++)if(dp[j]){int filled=processed-j;int fr=opened(j)-filled;if(fr<0)continue;
   nd[j]=(nd[j]+dp[j]*C(fr,c))%MOD;                       // all copies go to open slots
   if(j<k)nd[j+1]=(nd[j+1]+dp[j]*C(fr,c-1))%MOD;}          // one copy becomes the next (smaller) peak
  swap(dp,nd);processed+=c;}
 printf("%lld\n",dp[k]);}} // all n placed: processed = n, filled = k

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;const ll MOD=1e9+7;typedef array<array<ll,2>,2> Mt;
Mt mul(const Mt&a,const Mt&b){Mt c{};for(int i=0;i<2;i++)for(int j=0;j<2;j++)for(int k=0;k<2;k++)c[i][j]=(c[i][j]+a[i][k]*b[k][j])%MOD;return c;}
int main(){int m;ll n;cin>>m>>n;vector<ll>s(m),l(m);for(auto&x:s)cin>>x;for(auto&x:l)cin>>x;
 // T[i][j] = t_i t_j - l_i l_j (t = s + l): rank 2, so T = A B^T with A = [t, l], B = [t, -l]
 ll tt=0,tl=0,ll_=0,St=0,Sl=0;
 for(int i=0;i<m;i++){ll t=s[i]+l[i];tt=(tt+t*t)%MOD;tl=(tl+t*l[i])%MOD;ll_=(ll_+l[i]*l[i])%MOD;St=(St+t)%MOD;Sl=(Sl+l[i])%MOD;}
 Mt C{};C[0][0]=tt;C[0][1]=tl;C[1][0]=(MOD-tl)%MOD;C[1][1]=(MOD-ll_)%MOD; // C = B^T A
 Mt R{};R[0][0]=R[1][1]=1;ll e=n-1;while(e){if(e&1)R=mul(R,C);C=mul(C,C);e>>=1;}
 ll r0=s[0]+l[0],r1=l[0],w0=St,w1=(MOD-Sl)%MOD; // answer = r C^{n-1} w
 ll v0=(r0*R[0][0]+r1*R[1][0])%MOD,v1=(r0*R[0][1]+r1*R[1][1])%MOD;
 cout<<(v0*w0+v1*w1)%MOD<<endl;}

