int main(){string s;cin>>s;int n=s.size();
 // runs of equal-direction edges around the cycle; each run is a chain, adjacent runs share an endpoint
 int st=0;while(st<n&&s[st]==s[(st+n-1)%n])st++; // start at a run boundary (exists because the graph is acyclic)
 vector<int>len;for(int i=0;i<n;){int j=i;while(j<n&&s[(st+j)%n]==s[(st+i)%n])j++;len.push_back(j-i);i=j;}
 int k=len.size(),longs=0;for(int x:len)if(x>=2)longs++;
 if(longs==0){printf("%d\n",k/2);return 0;}
 int r=0;while(len[r]<2)r++; // rotate so we start at a long run
 int ans=longs,blk=0;for(int t=1;t<=k;t++){int x=len[(r+t)%k];if(x>=2){ans+=blk/2;blk=0;}else blk++;}
 printf("%d\n",ans);}

