int n;vector<long long>a;vector<pair<int,int>>ops;
void op(int l,int r){set<long long>s(a.begin()+l,a.begin()+r+1);long long m=0;while(s.count(m))m++;for(int i=l;i<=r;i++)a[i]=m;ops.push_back({l+1,r+1});}
void zero(int l,int r){bool z=false;for(int i=l;i<=r;i++)z|=a[i]==0;if(z)op(l,r);bool allz=true;for(int i=l;i<=r;i++)allz&=a[i]==0;if(!allz)op(l,r);}
void stair(int l,int r){if(l==r)return;stair(l+1,r);op(l,r);zero(l+1,r);stair(l+1,r);} // zeros -> [k-1,...,1,0]
int main(){cin>>n;a.resize(n);for(auto&x:a)cin>>x;long long best=-1;int bm=0;
 for(int m=0;m<(1<<n);m++){long long s=0;for(int i=0;i<n;){if(m>>i&1){int j=i;while(j<n&&(m>>j&1))j++;s+=(long long)(j-i)*(j-i);i=j;}else s+=a[i++];}
  if(s>best){best=s;bm=m;}}
 for(int i=0;i<n;){if(bm>>i&1){int j=i;while(j<n&&(bm>>j&1))j++;zero(i,j-1);stair(i,j-1);op(i,j-1);i=j;}else i++;}
 printf("%lld %d\n",best,(int)ops.size());for(auto[l,r]:ops)printf("%d %d\n",l,r);}

