int main(){int t;scanf("%d",&t);while(t--){int m;scanf("%d",&m);vector<ll>a[2];for(int r=0;r<2;r++){a[r].resize(m);for(auto&x:a[r])scanf("%lld",&x);}
 vector<ll>sm[2],sp[2]; // suffix max of a-k and a+k
 for(int r=0;r<2;r++){sm[r].assign(m+1,LLONG_MIN/2);sp[r].assign(m+1,LLONG_MIN/2);for(int k=m-1;k>=0;k--){sm[r][k]=max(sm[r][k+1],a[r][k]-k);sp[r][k]=max(sp[r][k+1],a[r][k]+1+k);}}
 ll T=0,ans=LLONG_MAX;int r=0; // T = time we stand at (r,j) having covered columns <j and (r,j)
 for(int j=0;j<m;j++){
  ll total=2LL*(m-j)-1,fin=T+total;                 // hook: right along row r, back along row !r
  if(j+1<m)fin=max(fin,sm[r][j+1]+2LL*m-j);
  fin=max(fin,sp[!r][j]-j);ans=min(ans,fin);
  T=max(T+1,a[!r][j]+1);r=!r;                       // snake: switch row in column j
  if(j+1<m)T=max(T+1,a[r][j+1]+1);}
 printf("%lld\n",ans);}}

