int main(){int t;scanf("%d",&t);while(t--){int n;scanf("%d",&n);vector<int>a(n);for(auto&x:a)scanf("%d",&x);
 int ans=0;vector<int>L(n),R(n);
 for(int x=1;x<=100;x++){ // med >= x  <=>  sum of (+1 if >=x else -1) >= 0
  for(int i=0;i<n;i++){int v=a[i]>=x?1:-1;L[i]=v+max(0,i?L[i-1]:0);}       // best sum of subarray ending at i
  for(int i=n-1;i>=0;i--){int v=a[i]>=x?1:-1;R[i]=v+max(0,i+1<n?R[i+1]:0);} // best sum starting at i
  for(int i=0;i<n;i++){int v=a[i]>=x?1:-1;if(L[i]+R[i]-v>=0)ans=max(ans,x-a[i]);}}
 printf("%d\n",ans);}}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;const ll MOD=998244353;
ll k;vector<ll>same_,diff_;
ll pw(ll b,ll e){ll r=1;b%=MOD;while(e>0){if(e&1)r=r*b%MOD;b=b*b%MOD;e>>=1;}return r;}
// count fillings of a sequence (no two adjacent equal), -1 = free
ll solve(const vector<ll>&v){int n=v.size();if(!n)return 1;
 for(int i=0;i+1<n;i++)if(v[i]!=-1&&v[i]==v[i+1])return 0;
 vector<int>fx;for(int i=0;i<n;i++)if(v[i]!=-1)fx.push_back(i);
 if(fx.empty())return k%MOD*pw(k-1,n-1)%MOD;
 ll r=pw(k-1,fx[0])*pw(k-1,n-1-fx.back())%MOD; // free prefix/suffix
 for(size_t q=0;q+1<fx.size();q++){int L=fx[q+1]-fx[q]-1;r=r*(v[fx[q]]==v[fx[q+1]]?same_[L]:diff_[L])%MOD;}
 return r;}
int main(){int n;scanf("%d %lld",&n,&k);vector<ll>a(n);for(auto&x:a)scanf("%lld",&x);
 same_.assign(n+1,0);diff_.assign(n+1,0);same_[0]=0;diff_[0]=1; // L blanks between two equal / different fixed values
 for(int L=1;L<=n;L++){same_[L]=(k-1)%MOD*diff_[L-1]%MOD;diff_[L]=(same_[L-1]+(k-2)%MOD*diff_[L-1])%MOD;}
 vector<ll>ev,od;for(int i=0;i<n;i++)(i%2?od:ev).push_back(a[i]); // odd palindrome <=> a[i]==a[i+2]
 printf("%lld\n",solve(ev)*solve(od)%MOD);}

