typedef long long ll;
int main(){int n,k;ll m;cin>>n>>k>>m;
 auto pw=[&](ll b,ll e){ll r=1%m;b%=m;while(e){if(e&1)r=r*b%m;b=b*b%m;e>>=1;}return r;};
 // ticket is lucky iff some digit d has 2d == S (mod k), S = total sum. Count unlucky per target S.
 ll bad=0;
 for(int S=0;S<k;S++){vector<char>ban(k,0);for(int d=0;d<k;d++)if((2*d)%k==S)ban[d]=1;
  vector<ll>dp(k,0);dp[0]=1%m;
  for(int i=0;i<n;i++){vector<ll>nd(k,0);for(int r=0;r<k;r++)if(dp[r])for(int d=0;d<k;d++)if(!ban[d])nd[(r+d)%k]=(nd[(r+d)%k]+dp[r])%m;dp=nd;}
  bad=(bad+dp[S])%m;}
 cout<<((pw(k,n)-bad)%m+m)%m<<endl;}

#include <bits/stdc++.h>
using namespace std;
int n,k;vector<vector<pair<int,int>>>g;vector<vector<vector<int>>>lay;vector<int>ch,che,sz;const int INF=1e9;
vector<vector<int>>kids,kide;vector<int>cut;
void dfs(int v,int p){ // lay[v][c][s]: min boundary edges, component of v has size s, using its first c children
 for(auto[u,e]:g[v])if(u!=p){kids[v].push_back(u);kide[v].push_back(e);dfs(u,v);}
 lay[v].assign(kids[v].size()+1,vector<int>(n+1,INF));lay[v][0][1]=1-1;
 for(size_t c=0;c<kids[v].size();c++){int u=kids[v][c];auto&pr=lay[v][c];auto&nx=lay[v][c+1];auto&du=lay[u].back();
  for(int s=1;s<=n;s++)if(pr[s]<INF){nx[s]=min(nx[s],pr[s]+1); // cut the edge to the child
   for(int t=1;s+t<=n;t++)if(du[t]<INF)nx[s+t]=min(nx[s+t],pr[s]+du[t]);}}}
void rec(int v,int s){for(int c=kids[v].size();c>0;c--){int u=kids[v][c-1];auto&pr=lay[v][c-1];int cur=lay[v][c][s];
  if(pr[s]<INF&&pr[s]+1==cur){cut.push_back(kide[v][c-1]);continue;}
  for(int t=1;t<s;t++)if(pr[s-t]<INF&&lay[u].back()[t]<INF&&pr[s-t]+lay[u].back()[t]==cur){rec(u,t);s-=t;break;}}}
int main(){cin>>n>>k;g.resize(n+1);kids.resize(n+1);kide.resize(n+1);lay.resize(n+1);vector<int>par(n+1,0),pe(n+1,0);
 for(int i=1;i<n;i++){int x,y;cin>>x>>y;g[x].push_back({y,i});g[y].push_back({x,i});}
 dfs(1,0);for(int v=1;v<=n;v++)for(size_t c=0;c<kids[v].size();c++){par[kids[v][c]]=v;pe[kids[v][c]]=kide[v][c];}
 int best=INF,bv=1;for(int v=1;v<=n;v++){int val=lay[v].back()[k];if(val<INF&&val+(v!=1)<best){best=val+(v!=1);bv=v;}}
 rec(bv,k);if(bv!=1)cut.push_back(pe[bv]);
 printf("%d\n",(int)cut.size());for(int e:cut)printf("%d ",e);puts("");}

