const long long M=1e9+7;long long P[32],T[32],score;long long k;
// T[i]=ops to fully clear i (=2^(i-1)), P[i]=product of all removed values
void partial(long long m){score=score*(m%M)%M;k--;
 for(int i=1;i<m&&k>0;i++){if(T[i]<=k){score=score*P[i]%M;k-=T[i];}else{partial(i);return;}}}
