 pre[1]=0;for(int i=2;i<N;i++)pre[i]=pre[i-1]+phi[i]; // coprime pairs in 1..i
 int t;scanf("%d",&t);while(t--){long long n,m;scanf("%lld %lld",&n,&m);long long cost=0;
  for(long long w=n;w>=2&&m>0;w--){long long f=pre[n/w];long long ops=min(f/(w-1),m/(w-1));cost+=ops*w;m-=ops*(w-1);}
