int main(){int n;scanf("%d",&n);vector<ll>a(n),b(n);for(auto&x:a)scanf("%lld",&x);for(auto&x:b)scanf("%lld",&x);
 vector<ll>dp(n,0);deque<pair<ll,ll>>h; // lines y = m*x + c with m = b_j (decreasing), queries x = a_i (increasing)
 auto bad=[](pair<ll,ll>l1,pair<ll,ll>l2,pair<ll,ll>l3){return (L)(l3.second-l1.second)*(l1.first-l2.first)<=(L)(l2.second-l1.second)*(l1.first-l3.first);};
 h.push_back({b[0],0});
 for(int i=1;i<n;i++){while(h.size()>=2&&h[1].first*a[i]+h[1].second<=h[0].first*a[i]+h[0].second)h.pop_front();
  dp[i]=h[0].first*a[i]+h[0].second;pair<ll,ll>ln{b[i],dp[i]};
  while(h.size()>=2&&bad(h[h.size()-2],h.back(),ln))h.pop_back();h.push_back(ln);}
 printf("%lld\n",dp[n-1]);}

