 vector<char>bad(n+1,0);for(int v=1;v<=n;v++)if(cnt[v])for(int k=v;k<=n;k+=v){if(bad[k])continue;bad[k]=1;}
 vector<ll>e(n+1,0);ll ans=0;
 for(int g=n;g>=1;g--){ll c=0;for(int k=g;k<=n;k+=g)c+=cnt[k];e[g]=c*(c-1)/2;for(int k=2*g;k<=n;k+=g)e[g]-=e[k];if(!bad[g])ans+=e[g];}
