#include <bits/stdc++.h>
using namespace std;typedef long long ll;
ll full(ll w){ll t=(ll)((sqrt(8.0L*w+1)-1)/2);while((t+1)*(t+2)/2<=w)t++;while(t*(t+1)/2>w)t--;return (t+1)*w-t*(t+1)*(t+2)/6;}
int main(){int n,m;scanf("%d %d",&n,&m);vector<int>X(m),Y(m);vector<ll>W(m);vector<int>head(n+1,-1),nxt(m);
 for(int i=0;i<m;i++){scanf("%d %d %lld",&X[i],&Y[i],&W[i]);nxt[i]=head[X[i]];head[X[i]]=i;}int s;scanf("%d",&s);
 // iterative Tarjan from s
 vector<int>idx(n+1,-1),low(n+1),comp(n+1,-1),it(n+1);vector<char>on(n+1,0);vector<int>stk,cs;int T=0,C=0;
 cs.push_back(s);idx[s]=low[s]=T++;stk.push_back(s);on[s]=1;it[s]=head[s];
 while(!cs.empty()){int u=cs.back();
  if(it[u]!=-1){int e=it[u];it[u]=nxt[e];int v=Y[e];
   if(idx[v]<0){idx[v]=low[v]=T++;stk.push_back(v);on[v]=1;it[v]=head[v];cs.push_back(v);}else if(on[v])low[u]=min(low[u],idx[v]);}
  else{cs.pop_back();if(!cs.empty())low[cs.back()]=min(low[cs.back()],low[u]);
   if(low[u]==idx[u]){while(true){int v=stk.back();stk.pop_back();on[v]=0;comp[v]=C;if(v==u)break;}C++;}}}
 // Tarjan numbers SCCs in reverse topological order: comp 0 is a sink
 vector<ll>inner(C,0),best(C,0);vector<vector<pair<int,ll>>>out(C);
 for(int i=0;i<m;i++){if(comp[X[i]]<0)continue;int a=comp[X[i]],b=comp[Y[i]];if(a==b)inner[a]+=full(W[i]);else out[a].push_back({b,W[i]});}
 for(int c=0;c<C;c++){ll bst=0;for(auto[b,w]:out[c])bst=max(bst,best[b]+w);best[c]=inner[c]+bst;}
 printf("%lld\n",best[comp[s]]);}

