int main(){int T;scanf("%d",&T);while(T--){int n,m;ll k;scanf("%d %d %lld",&n,&m,&k);vector<ll>h(n+1),t(n+1);for(int i=1;i<=n;i++)scanf("%lld",&h[i]);
 vector<vector<int>>g(n+1);vector<int>indeg(n+1,0);for(int i=0;i<m;i++){int a,b;scanf("%d %d",&a,&b);g[a].push_back(b);indeg[b]++;}
 for(int i=1;i<=n;i++)t[i]=h[i];
 for(int u=1;u<=n;u++)for(int v:g[u])t[v]=max(t[v],t[u]+((h[v]-h[u])%k+k)%k); // a<b so index order is topological
 ll mx=*max_element(t.begin()+1,t.end());vector<int>src;for(int i=1;i<=n;i++)if(!indeg[i])src.push_back(i);
 sort(src.begin(),src.end(),[&](int a,int b){return h[a]<h[b];});ll ans=LLONG_MAX;
 for(int s:src){ans=min(ans,mx-h[s]);
  if(t[s]<h[s]+k){t[s]=h[s]+k;mx=max(mx,t[s]);queue<int>q;q.push(s);
   while(!q.empty()){int u=q.front();q.pop();for(int v:g[u]){ll c=t[u]+((h[v]-h[u])%k+k)%k;if(c>t[v]){t[v]=c;mx=max(mx,c);q.push(v);}}}}}
 printf("%lld\n",ans);}}

