const long long MOD=998244353;
int main(){int t;scanf("%d",&t);while(t--){int n,m;scanf("%d %d",&n,&m);vector<int>ml(n+2,0); // ml[r]=max l of intervals ending at r
 for(int i=0;i<m;i++){int l,r;scanf("%d %d",&l,&r);ml[r]=max(ml[r],l);}
 // beautiful <=> substring has >=2 blocks <=> not constant.
 // f[j]: ways where position j starts a new block (j=1 is the first block); a run [k,j-1] must contain no interval
 vector<long long>f(n+2,0),P(n+2,0);f[1]=2;P[1]=2;int M=0;
 for(int j=2;j<=n+1;j++){M=max(M,ml[j-1]);long long v=(P[j-1]-P[M]+MOD)%MOD; // k in [M+1, j-1]
  if(j==n+1){printf("%lld\n",v);break;}f[j]=v;P[j]=(P[j-1]+f[j])%MOD;}}}

