int main(){int n,m,k;scanf("%d %d %d",&n,&m,&k);vector<vector<ll>>c(n+2,vector<ll>(n+2,INF));
  for(int i=0;i<m;i++){int l,r;ll w;scanf("%d %d %lld",&l,&r,&w);c[l][r]=min(c[l][r],w);}
  for(int l=1;l<=n;l++)for(int r=n;r>=l;r--)c[l][r]=min({c[l][r],c[l-1][r],c[l][r+1]}); // min cost covering [l,r]
  vector<vector<ll>>dp(n+1,vector<ll>(n+1,INF));dp[0][0]=0;
  for(int i=1;i<=n;i++)for(int j=0;j<=i;j++){ll b=dp[i-1][j];
    for(int l=i;l>=1;l--){int len=i-l+1;if(len>j)break;if(dp[l-1][j-len]<INF&&c[l][i]<INF)b=min(b,dp[l-1][j-len]+c[l][i]);}
    dp[i][j]=b;}
  ll ans=INF;for(int j=k;j<=n;j++)ans=min(ans,dp[n][j]);printf("%lld\n",ans>=INF?-1:ans);}

#include <bits/stdc++.h>
using namespace std;
int n,X;vector<int>L,R,f;vector<vector<int>>endAt; // intervals ending at coordinate
// best packing of intervals strictly inside [lo,hi] excluding self; returns h array
vector<int> pack(int lo,int hi,int self){vector<int>h(hi-lo+1,0);
  for(int x=lo+1;x<=hi;x++){h[x-lo]=h[x-lo-1];for(int j:endAt[x])if(j!=self&&L[j]>=lo)h[x-lo]=max(h[x-lo],h[L[j]-lo]+f[j]);}
  return h;}
void collect(int lo,int hi,int self,vector<int>&out){auto h=pack(lo,hi,self);int x=hi;
  while(x>lo){if(h[x-lo]==h[x-lo-1]){x--;continue;}
    for(int j:endAt[x])if(j!=self&&L[j]>=lo&&h[L[j]-lo]+f[j]==h[x-lo]){out.push_back(j);collect(L[j],R[j],j,out);x=L[j];break;}}}
int main(){scanf("%d",&n);L.resize(n);R.resize(n);f.assign(n,0);vector<int>xs;
  for(int i=0;i<n;i++){long long c,r;scanf("%lld %lld",&c,&r);L[i]=c-r;R[i]=c+r;xs.push_back(L[i]);xs.push_back(R[i]);}
  sort(xs.begin(),xs.end());xs.erase(unique(xs.begin(),xs.end()),xs.end());X=xs.size();endAt.assign(X,{});
  for(int i=0;i<n;i++){L[i]=lower_bound(xs.begin(),xs.end(),L[i])-xs.begin();R[i]=lower_bound(xs.begin(),xs.end(),R[i])-xs.begin();endAt[R[i]].push_back(i);}
  vector<int>o(n);iota(o.begin(),o.end(),0);sort(o.begin(),o.end(),[&](int a,int b){return R[a]-L[a]<R[b]-L[b];});
  for(int i:o){f[i]=1+pack(L[i],R[i],i).back();}
  vector<int>out;collect(0,X-1,-1,out);printf("%d\n",(int)out.size());for(int i:out)printf("%d ",i+1);puts("");}

