using namespace std;typedef long long ll;const ll BAD=-1;
int main(){int t;scanf("%d",&t);while(t--){int n;scanf("%d",&n);vector<ll>a(n);for(auto&x:a)scanf("%lld",&x);
  vector<ll>p(n),s(n); // p[i]: leftover of a[i] after clearing prefix, BAD if impossible
  for(int i=0;i<n;i++){ll prev=i?p[i-1]:0;p[i]=(prev==BAD||a[i]<prev)?BAD:a[i]-prev;}
  for(int i=n-1;i>=0;i--){ll nx=i<n-1?s[i+1]:0;s[i]=(nx==BAD||a[i]<nx)?BAD:a[i]-nx;}
  bool ok=p[n-1]==0;
  for(int i=0;i+1<n&&!ok;i++){ll L=i?p[i-1]:0,R=i+2<n?s[i+2]:0;if(L==BAD||R==BAD)continue;
    ll x=a[i+1]-L;if(x<0)continue;ll y=a[i]-x;if(y<0)continue;if(y==R)ok=true;}
  puts(ok?"YES":"NO");}}

