using namespace std;typedef long long ll;const ll M=1e9+7;const int A=1000001;
int main(){int n;scanf("%d",&n);vector<int>c(A,0);for(int i=0;i<n;i++){int x;scanf("%d",&x);c[x]++;}
  vector<ll>p2(n+1,1);for(int i=1;i<=n;i++)p2[i]=p2[i-1]*2%M;vector<ll>g(A,0);ll ans=0;
  for(int d=A-1;d>=2;d--){ll k=0;for(int m=d;m<A;m+=d)k+=c[m];if(!k)continue;
    ll f=k%M*p2[k-1]%M;for(int m=2*d;m<A;m+=d)f=(f-g[m]+M)%M;g[d]=f;ans=(ans+f*d)%M;}
  printf("%lld\n",ans);}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int n;vector<ll>sm;vector<ll>lz;vector<char>has;
void app(int o,int l,int r,ll v){sm[o]=v*(r-l+1);lz[o]=v;has[o]=1;}
void push(int o,int l,int r){if(has[o]){int m=(l+r)/2;app(2*o,l,m,lz[o]);app(2*o+1,m+1,r,lz[o]);has[o]=0;}}
void assign(int o,int l,int r,int a,int b,ll v){if(b<l||r<a)return;if(a<=l&&r<=b){app(o,l,r,v);return;}push(o,l,r);int m=(l+r)/2;
 assign(2*o,l,m,a,b,v);assign(2*o+1,m+1,r,a,b,v);sm[o]=sm[2*o]+sm[2*o+1];}
ll query(int o,int l,int r,int a,int b){if(b<l||r<a)return 0;if(a<=l&&r<=b)return sm[o];push(o,l,r);int m=(l+r)/2;return query(2*o,l,m,a,b)+query(2*o+1,m+1,r,a,b);}
int main(){int t;scanf("%d",&t);while(t--){int k,q;scanf("%d %d %d",&n,&k,&q);vector<int>a(n);for(auto&x:a)scanf("%d",&x);
 int W=n-k+1;vector<ll>c(W); // c[s] = k - max frequency of (a_i - i) in window [s, s+k)
 {map<int,int>cnt;vector<int>cc(n+2,0);int mx=0;
  auto add=[&](int v){int&x=cnt[v];cc[x]--;x++;cc[x]++;mx=max(mx,x);};
  auto rem=[&](int v){int&x=cnt[v];cc[x]--;if(mx==x&&cc[x]==0)mx--;x--;cc[x]++;};
  cc[0]=n+1;for(int i=0;i<n;i++){add(a[i]-i);if(i>=k)rem(a[i-k]-(i-k));if(i>=k-1)c[i-k+1]=k-mx;}}
 vector<vector<pair<int,int>>>byL(W);vector<ll>ans(q);
 for(int i=0;i<q;i++){int l,r;scanf("%d %d",&l,&r);l--;r--;byL[l].push_back({r-k+1,i});}
 sm.assign(4*W,0);lz.assign(4*W,0);has.assign(4*W,0);
 // sweep l from right to left; position s holds min(c[l..s]); new c[l] overwrites values > c[l] (a prefix, via stack)
 vector<int>st;
 for(int l=W-1;l>=0;l--){while(!st.empty()&&c[st.back()]>=c[l])st.pop_back();int to=st.empty()?W-1:st.back()-1;
  assign(1,0,W-1,l,to,c[l]);st.push_back(l);
  for(auto[R,id]:byL[l])ans[id]=query(1,0,W-1,l,R);}
 for(ll x:ans)printf("%lld\n",x);}}

