 for(int i=0;i<n;i++){int a;scanf("%d",&a);if(x%a)continue;vector<int>add;bool hit=false;
  for(int d:cur){long long p=(long long)d*a;if(p<=x&&x%p==0){if(p==x)hit=true;else if(!has[p])add.push_back(p);}}
  if(hit){ans++;for(int d:cur)has[d]=0;cur={1};has[1]=1;if(!has[a]){has[a]=1;cur.push_back(a);}}
