int main(){int n;scanf("%d",&n);vector<long long>a(n);for(auto&x:a)scanf("%lld",&x);
 vector<int>pr;{vector<bool>c(10001,false);for(int i=2;i<=10000;i++)if(!c[i]){pr.push_back(i);for(int j=i*i;j<=10000;j+=i)c[j]=true;}}
 for(auto&x:a){if(x==0)continue;long long s=x<0?-1:1,v=llabs(x);for(int p:pr){if((long long)p*p>v)break;while(v%((long long)p*p)==0)v/=(long long)p*p;}x=s*v;}
 vector<long long>vals;for(auto x:a)if(x)vals.push_back(x);sort(vals.begin(),vals.end());vals.erase(unique(vals.begin(),vals.end()),vals.end());
 vector<int>id(n,-1);for(int i=0;i<n;i++)if(a[i])id[i]=lower_bound(vals.begin(),vals.end(),a[i])-vals.begin();
 vector<int>res(n+1,0),seen(vals.size()+1,-1);
 for(int l=0;l<n;l++){int d=0;for(int r=l;r<n;r++){if(id[r]>=0&&seen[id[r]]!=l){seen[id[r]]=l;d++;}res[max(1,d)]++;}}
