int main(){int n;scanf("%d",&n);vector<ll>k(n+1);for(int i=1;i<=n;i++)scanf("%lld",&k[i]);
  vector<vector<int>>g(n+1);for(int i=0;i<n-1;i++){int a,b;scanf("%d %d",&a,&b);g[a].push_back(b);g[b].push_back(a);}
  int s;scanf("%d",&s);vector<int>par(n+1,0),ord={s};
  for(size_t i=0;i<ord.size();i++){int u=ord[i];for(int v:g[u])if(v!=par[u]){par[v]=u;ord.push_back(v);}}
  vector<ll>dp(n+1),left(n+1);
  for(int i=n-1;i>=0;i--){int v=ord[i];ll av=k[v]-(v!=s);ll tot=(v!=s);vector<ll>ch;ll sl=0;
    for(int c:g[v])if(c!=par[v]){ch.push_back(dp[c]);sl+=left[c];}
    sort(ch.rbegin(),ch.rend());
    for(ll d:ch){if(av<=0)break;tot+=d+1;av--;}
    ll b=min(av,sl);tot+=2*b;av-=b;dp[v]=tot;left[v]=av;}
  printf("%lld\n",dp[s]);}

