int main(){int n;scanf("%d",&n);vector<int>a(n),last(n+1,-1);for(int i=0;i<n;i++){scanf("%d",&a[i]);last[a[i]]=i;}
  long long ans=0;int i=0;
  while(i<n){int L=i,cur=last[a[i]];if(cur==L){i++;continue;}int cnt=1,j=L+1,best=cur;
    while(true){while(j<=cur){best=max(best,last[a[j]]);j++;}if(best>cur){cnt++;cur=best;}else break;}
    ans+=(cur-L+1)-(cnt+1);i=cur+1;}
  printf("%lld\n",ans);}

#include <bits/stdc++.h>
using namespace std;typedef pair<int,int> P; // (dp value, row)
int K;vector<P>t,lz;
void app(int x,P v){t[x]=max(t[x],v);lz[x]=max(lz[x],v);}
void upd(int x,int l,int r,int ql,int qr,P v){if(qr<l||r<ql)return;if(ql<=l&&r<=qr){app(x,v);return;}
  app(2*x,lz[x]);app(2*x+1,lz[x]);int m=(l+r)/2;upd(2*x,l,m,ql,qr,v);upd(2*x+1,m+1,r,ql,qr,v);t[x]=max(t[2*x],t[2*x+1]);}
P qry(int x,int l,int r,int ql,int qr){if(qr<l||r<ql)return {0,0};if(ql<=l&&r<=qr)return t[x];
  app(2*x,lz[x]);app(2*x+1,lz[x]);int m=(l+r)/2;return max(qry(2*x,l,m,ql,qr),qry(2*x+1,m+1,r,ql,qr));}
int main(){int n,m;scanf("%d %d",&n,&m);vector<vector<pair<int,int>>>seg(n+1);vector<int>xs;
  for(int i=0;i<m;i++){int r,a,b;scanf("%d %d %d",&r,&a,&b);seg[r].push_back({a,b});xs.push_back(a);xs.push_back(b);}
  sort(xs.begin(),xs.end());xs.erase(unique(xs.begin(),xs.end()),xs.end());K=xs.size();t.assign(4*K,{0,0});lz.assign(4*K,{0,0});
  auto id=[&](int v){return int(lower_bound(xs.begin(),xs.end(),v)-xs.begin());};
  vector<int>prv(n+1,0);P best={0,0};
  for(int i=1;i<=n;i++){P b={0,0};for(auto[l,r]:seg[i])b=max(b,qry(1,0,K-1,id(l),id(r)));
    P me={b.first+1,i};prv[i]=b.second;for(auto[l,r]:seg[i])upd(1,0,K-1,id(l),id(r),me);best=max(best,me);}
  vector<char>keep(n+1,0);for(int v=best.second;v;v=prv[v])keep[v]=1;
  printf("%d\n",n-best.first);for(int i=1;i<=n;i++)if(!keep[i])printf("%d ",i);puts("");}

