using namespace std;typedef long long ll;
int main(){int n,m;scanf("%d %d",&n,&m);vector<ll>w(n+1);for(int i=1;i<=n;i++)scanf("%lld",&w[i]);
  vector<vector<int>>g(n+1);vector<int>deg(n+1,0);for(int i=0;i<m;i++){int u,v;scanf("%d %d",&u,&v);g[u].push_back(v);g[v].push_back(u);deg[u]++;deg[v]++;}
  int s;scanf("%d",&s);vector<char>rem(n+1,0);vector<ll>best(n+1,0);queue<int>qu;
  for(int v=1;v<=n;v++)if(deg[v]==1&&v!=s)qu.push(v);
  while(!qu.empty()){int v=qu.front();qu.pop();rem[v]=1;ll dv=w[v]+best[v];
    for(int u:g[v])if(!rem[u]){best[u]=max(best[u],dv);if(--deg[u]==1&&u!=s)qu.push(u);}}
  ll sum=0,ext=0;for(int v=1;v<=n;v++)if(!rem[v]){sum+=w[v];ext=max(ext,best[v]);}
  printf("%lld\n",sum+ext);}

#include <bits/stdc++.h>
using namespace std;typedef long long ll;const ll M=998244353;
int main(){int n;cin>>n;vector<ll>v(n,-1);for(int i=0;i<n;i++){char c;cin>>c;if(c=='+')cin>>v[i];}
  ll ans=0;
  for(int i=0;i<n;i++)if(v[i]>=0){vector<ll>dp(n+1,0);dp[0]=1;
    auto smaller=[&](int j){return v[j]<v[i]||(v[j]==v[i]&&j<i);};
    for(int j=0;j<n;j++){if(j==i)continue;vector<ll>nd(dp);
      if(v[j]<0){for(int c=0;c<=n;c++)if(dp[c]){if(c>0)nd[c-1]=(nd[c-1]+dp[c])%M;else if(j<i)nd[0]=(nd[0]+dp[0])%M;}}
      else if(smaller(j)){for(int c=0;c<n;c++)if(dp[c])nd[c+1]=(nd[c+1]+dp[c])%M;}
      else for(int c=0;c<=n;c++)nd[c]=dp[c]*2%M;
      dp=nd;}
    ll ways=0;for(ll x:dp)ways=(ways+x)%M;ans=(ans+ways*(v[i]%M))%M;}
  cout<<ans<<endl;}

#include <bits/stdc++.h>
using namespace std;typedef long long ll;const ll M=998244353;
int main(){int n,m;scanf("%d %d",&n,&m);vector<int>l(n),r(n);for(int i=0;i<n;i++)scanf("%d %d",&l[i],&r[i]);
  vector<int>mu(m+1,0);mu[1]=1;for(int i=1;i<=m;i++)for(int j=2*i;j<=m;j+=i)mu[j]-=mu[i];
  ll ans=0;
  for(int d=1;d<=m;d++){if(!mu[d])continue;int S=m/d;vector<ll>dp(S+1,0),nd(S+1),pre(S+2);dp[0]=1;bool ok=true;
    for(int i=0;i<n&&ok;i++){int lo=(l[i]+d-1)/d,hi=r[i]/d;if(lo>hi){ok=false;break;}
      pre[0]=0;for(int s=0;s<=S;s++)pre[s+1]=(pre[s]+dp[s])%M;
      for(int s=0;s<=S;s++){int a=s-hi,b=s-lo;if(b<0){nd[s]=0;continue;}a=max(a,0);nd[s]=(pre[b+1]-pre[a]+M)%M;}
      swap(dp,nd);}
    if(!ok)continue;ll tot=0;for(ll x:dp)tot=(tot+x)%M;ans=(ans+mu[d]*tot%M+M)%M;}
  printf("%lld\n",ans);}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;const ll MOD=998244353;
int main(){int n,m;cin>>n>>m;
 // w[e]: ways to split one suit's m ranks so that (scanning high->low) the beating side never runs short, ending with surplus e
 vector<vector<ll>>c(m+1,vector<ll>(m+2,0));c[0][0]=1;
 for(int i=0;i<m;i++)for(int b=0;b<=i;b++)if(c[i][b]){c[i+1][b+1]=(c[i+1][b+1]+c[i][b])%MOD;if(b)c[i+1][b-1]=(c[i+1][b-1]+c[i][b])%MOD;}
 vector<ll>w(m+1);for(int e=0;e<=m;e++)w[e]=c[m][e];
 // suits 2..n: second player keeps surplus e (needs e trump cards); dp over total surplus
 vector<ll>dp(m+1,0);dp[0]=1;
 for(int s=2;s<=n;s++){vector<ll>nd(m+1,0);for(int a=0;a<=m;a++)if(dp[a])for(int e=0;a+e<=m;e++)nd[a+e]=(nd[a+e]+dp[a]*w[e])%MOD;dp=nd;}
 ll ans=0;for(int E=0;E<=m;E++)ans=(ans+dp[E]*w[E])%MOD; // suit 1: first player has surplus E
 cout<<ans<<endl;}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;const ll MOD=998244353;
int main(){int t;scanf("%d",&t);while(t--){int n;scanf("%d",&n);
 // d[i]: ways to finish from length i once inversions k exceed every element:
 // inserting k at the end keeps k, elsewhere (i spots) makes k_new > all -> d[i] = i*sum_{j>i} d[j] + 1
 // before that, arrays look like 0..0 1 0..0 (n-1 of them); entering big state at length m: (m-2)(m-1)/2 - 1 ways
 ll s=0,ans=n-1;
 for(int i=n;i>=3;i--){ll d=(ll(i)*s+1)%MOD;s=(s+d)%MOD;
  ll w=((ll(i-2)*(i-1)/2-1)%MOD+MOD)%MOD;ans=(ans+w*d)%MOD;}
 printf("%lld\n",ans);}}

#include <bits/stdc++.h>
using namespace std;
const long long MOD=1e9+7;
int main(){int t;cin>>t;while(t--){int n,I,J,x,y;cin>>n>>I>>J>>x>>y;
 auto ok=[&](int pos,int v){return (pos==I)==(v==x)&&(pos==J)==(v==y);};
 // place values 1..n-1 in increasing order at the leftmost or rightmost free slot; l = #placed on the left
 vector<long long>dp(n+1,0);dp[0]=1;
 for(int v=1;v<n;v++){vector<long long>nd(n+1,0);
  for(int l=0;l<v;l++)if(dp[l]){int r=v-1-l;
   if(ok(l+1,v))nd[l+1]=(nd[l+1]+dp[l])%MOD;          // left slot
   if(ok(n-r,v))nd[l]=(nd[l]+dp[l])%MOD;}             // right slot
  dp=nd;}
 long long ans=0;for(int l=0;l<n;l++){int pos=l+1;if(pos>=2&&pos<=n-1&&ok(pos,n))ans=(ans+dp[l])%MOD;} // peak n
 cout<<ans<<"\n";}}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;const ll MOD=998244353;
int main(){int t;scanf("%d",&t);while(t--){int n;scanf("%d",&n);vector<ll>a(n+1,0);for(int i=1;i<=n;i++)scanf("%lld",&a[i]);
 ll ans=(a[n]==n)?1:0;
 for(int i=1;i<=n&&ans;i++){ll d=a[i]-a[i-1],fr=(i-1)-a[i-1]; // free rows (and free columns) among the first i-1
  if(fr<0||d<0||d>2){ans=0;break;}
  if(d==1)ans=ans*((2*fr+1)%MOD)%MOD;       // rook in new row, new column, or the corner (i,i)
  else if(d==2)ans=ans*(fr*fr%MOD)%MOD;}    // one rook in each new strip
 printf("%lld\n",ans);}}

