int main(){int T;scanf("%d",&T);while(T--){int n,m,r;scanf("%d %d %d",&n,&m,&r);map<int,vector<pair<int,int>>>sh;
 for(int i=0;i<r;i++){int t,d,c;scanf("%d %d %d",&t,&d,&c);sh[t].push_back({d,c});}
 int W=m+1;vector<char>cur((n+1)*W,0),nx;cur[0]=1;int ans=-1;
 for(int t=1;t<=n+m+r&&ans<0;t++){nx=cur; // stay
  for(int i=0;i<=n;i++)for(int j=0;j<=m;j++)if(cur[i*W+j]){if(i<n)nx[(i+1)*W+j]=1;if(j<m)nx[i*W+j+1]=1;}
  auto it=sh.find(t);if(it!=sh.end())for(auto[d,c]:it->second){
   if(d==1)for(int j=0;j<=m;j++)nx[c*W+j]=0;else for(int i=0;i<=n;i++)nx[i*W+c]=0;}
  cur.swap(nx);if(cur[n*W+m])ans=t;}
 printf("%d\n",ans);}}

