int main(){int n;cin>>n;vector<int>l(n),r(n);for(int i=0;i<n;i++)cin>>l[i]>>r[i];
 // greedy: always close the innermost open bracket as soon as its distance allows
 string s;vector<pair<int,int>>st;int nxt=0;
 for(int pos=0;pos<2*n;pos++){
  if(!st.empty()&&pos-st.back().first>=l[st.back().second]){
   if(pos-st.back().first>r[st.back().second]){puts("IMPOSSIBLE");return 0;}
   s+=')';st.pop_back();}
  else{if(nxt==n){puts("IMPOSSIBLE");return 0;}
   if(!st.empty()&&pos-st.back().first>r[st.back().second]){puts("IMPOSSIBLE");return 0;}
   s+='(';st.push_back({pos,nxt++});}}
 if(!st.empty()){puts("IMPOSSIBLE");return 0;}cout<<s<<endl;}

