ll pw(ll b,ll e){ll r=1;b%=M;while(e){if(e&1)r=r*b%M;b=b*b%M;e>>=1;}return r;}
int main(){int t;scanf("%d",&t);while(t--){ll n,m,k;scanf("%lld %lld %lld",&n,&m,&k);ll S=0;
 for(int i=0;i<m;i++){ll a,b,f;scanf("%lld %lld %lld",&a,&b,&f);S=(S+f)%M;}
 ll inv=pw(n*(n-1)/2%M,M-2);
 ll ans=(k%M*S%M*inv + m%M*inv%M*inv%M*((k*(k-1)/2)%M))%M;
 printf("%lld\n",ans);}}

