 for(int i=0;i<n-1;i++){int u,v;scanf("%d %d",&u,&v);g[u].push_back(v);g[v].push_back(u);}
 ll mx=*max_element(a.begin()+1,a.end());int cM=0,cM1=0;for(int i=1;i<=n;i++){cM+=a[i]==mx;cM1+=a[i]==mx-1;}
 ll ans=mx+2;
