 for(int i=0;i<n;i++){long long a;scanf("%lld",&a);int t=0,f=0;while(a%2==0){a/=2;t++;}while(a%5==0){a/=5;f++;}
  for(int j=min(i+1,k);j>=1;j--)for(int s=F;s>=f;s--)if(dp[j-1][s-f]>=0)dp[j][s]=max(dp[j][s],dp[j-1][s-f]+t);}
