#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main(){int n,m,k,q;scanf("%d %d %d %d",&n,&m,&k,&q);
 vector<int>L(n+1,INT_MAX),R(n+1,0);
 for(int i=0;i<k;i++){int r,c;scanf("%d %d",&r,&c);L[r]=min(L[r],c);R[r]=max(R[r],c);}
 vector<int>safe(q);for(auto&x:safe)scanf("%d",&x);sort(safe.begin(),safe.end());
 if(L[1]==INT_MAX){L[1]=R[1]=1;}
 // after row 1: at L (having visited R first) or at R
 ll dL=(R[1]-1)+(R[1]-L[1]),dR=(R[1]-1);int pL=L[1],pR=R[1],last=1;
 for(int r=2;r<=n;r++){if(L[r]==INT_MAX)continue;ll up=r-last;ll nL=LLONG_MAX,nR=LLONG_MAX;
  for(int s=0;s<2;s++){int p=s?pR:pL;ll base=(s?dR:dL)+up;
   auto it=lower_bound(safe.begin(),safe.end(),p);vector<int>cs;if(it!=safe.end())cs.push_back(*it);if(it!=safe.begin())cs.push_back(*prev(it));
   for(int c:cs){ll b=base+abs(p-c);nL=min(nL,b+abs(c-R[r])+(R[r]-L[r]));nR=min(nR,b+abs(c-L[r])+(R[r]-L[r]));}}
  dL=nL;dR=nR;pL=L[r];pR=R[r];last=r;}
 printf("%lld\n",min(dL,dR));}

#include <bits/stdc++.h>
using namespace std;typedef long long ll;const ll M=1e9+7;
// count a>=1 with b=2(a&~b) (bitwise), a<b, c=a^b<=n
ll solve(ll n){ // state: bprev bit b_i, cmpAB (0 eq,1 a<b,2 a>b), cmpCN (0 eq,1 c<n,2 c>n), aNonzero
  ll dp[2][3][3][2]={};dp[0][0][0][0]=1;
  for(int i=0;i<=62;i++){ll nd[2][3][3][2]={};int nb=(n>>i)&1;
    for(int bi=0;bi<2;bi++)for(int x=0;x<3;x++)for(int y=0;y<3;y++)for(int z=0;z<2;z++)if(dp[bi][x][y][z])
      for(int ai=0;ai<=(i<=60);ai++){int ci=ai^bi,bn=ai&!bi;
        int X=ai<bi?1:ai>bi?2:x,Y=ci<nb?1:ci>nb?2:y;
        ll &r=nd[bn][X][Y][z|ai];r=(r+dp[bi][x][y][z])%M;}
    memcpy(dp,nd,sizeof dp);}
  ll s=0;for(int y=0;y<2;y++)s=(s+dp[0][1][y][1])%M;return s;}
int main(){int t;scanf("%d",&t);while(t--){ll n;scanf("%lld",&n);printf("%lld\n",solve(n));}}

#include <bits/stdc++.h>
using namespace std;typedef long long ll;const ll M=1e9+7;
int main(){int n,k;cin>>n>>k;int A=0,B=0;for(int i=0;i<n;i++){int w;cin>>w;(w==50?A:B)++;}
  ll C[51][51]={};for(int i=0;i<=50;i++){C[i][0]=1;for(int j=1;j<=i;j++)C[i][j]=(C[i-1][j-1]+C[i-1][j])%M;}
  // state (fifties on left, hundreds on left, boat side 0=left)
  vector<int>dist(52*52*2,-1);vector<ll>ways(52*52*2,0);auto id=[](int a,int b,int s){return (a*52+b)*2+s;};
  queue<array<int,3>>q;q.push({A,B,0});dist[id(A,B,0)]=0;ways[id(A,B,0)]=1;
  while(!q.empty()){auto[a,b,s]=q.front();q.pop();int cur=id(a,b,s);
    int ha=s?A-a:a,hb=s?B-b:b; // people on the boat's side
    for(int i=0;i<=ha;i++)for(int j=0;j<=hb;j++){if(i+j==0||50*i+100*j>k)continue;
      int na=s?a+i:a-i,nb=s?b+j:b-j,nx=id(na,nb,!s);ll w=ways[cur]*C[ha][i]%M*C[hb][j]%M;
      if(dist[nx]==-1){dist[nx]=dist[cur]+1;q.push({na,nb,!s});}
      if(dist[nx]==dist[cur]+1)ways[nx]=(ways[nx]+w)%M;}}
  int t=id(0,0,1);if(dist[t]<0)cout<<"-1\n0\n";else cout<<dist[t]<<"\n"<<ways[t]<<"\n";}

#include <bits/stdc++.h>
using namespace std;
int main(){int n;cin>>n;map<int,int>cnt;int S=0;for(int i=0;i<n;i++){int a;cin>>a;cnt[a]++;S+=a;}
  if(cnt.size()<=2){cout<<n<<endl;return 0;}
  // dp[k][s] = number of distinct multisets (capped at 2) of size k and sum s
  vector<vector<int>>dp(n+1,vector<int>(S+1,0));dp[0][0]=1;
  for(auto[v,c]:cnt){auto nd=dp;
    for(int k=0;k<=n;k++)for(int s=0;s<=S;s++)if(dp[k][s])
      for(int j=1;j<=c&&k+j<=n&&s+j*v<=S;j++)nd[k+j][s+j*v]=min(2,nd[k+j][s+j*v]+dp[k][s]);
    dp=nd;}
  int best=1;for(auto[v,c]:cnt)for(int k=1;k<=c;k++)if(dp[k][k*v]==1)best=max(best,k);
  cout<<best<<endl;}

#include <bits/stdc++.h>
using namespace std;typedef long long ll;const ll M=1e9+7;
int main(){ll n,l,k;cin>>n>>l>>k;vector<ll>a(n);for(auto&x:a)cin>>x;
  ll q=l/n,r=l%n;vector<int>ord(n);iota(ord.begin(),ord.end(),0);sort(ord.begin(),ord.end(),[&](int x,int y){return a[x]<a[y];});
  vector<ll>dp(n,1),nd(n);ll ans=0;
  for(ll j=1;j<=k&&j<=q+1;j++){
    if(j>1){ // nd[i] = sum of dp[i'] with a[i'] <= a[i]
      ll run=0;for(int p=0;p<n;){int e=p;ll add=0;while(e<n&&a[ord[e]]==a[ord[p]]){add=(add+dp[ord[e]])%M;e++;}
        run=(run+add)%M;for(int z=p;z<e;z++)nd[ord[z]]=run;p=e;}dp=nd;}
    ll tot=0;for(int i=0;i<n;i++)tot=(tot+dp[i])%M;
    if(j<=q)ans=(ans+tot*((q-j+1)%M))%M;
    for(int i=0;i<r;i++)ans=(ans+dp[i])%M;}
  cout<<ans<<endl;}

