int main(){int n,m;cin>>n>>m;vector<int>adj(n,0);for(int i=0;i<m;i++){int a,b;cin>>a>>b;a--;b--;adj[a]|=1<<b;adj[b]|=1<<a;}
  vector<vector<ll>>dp(1<<n,vector<ll>(n,0));for(int v=0;v<n;v++)dp[1<<v][v]=1;ll ans=0;
  for(int mask=1;mask<(1<<n);mask++){int s=__builtin_ctz(mask);
    for(int v=0;v<n;v++)if(dp[mask][v]){
      if((adj[v]>>s&1)&&__builtin_popcount(mask)>=3)ans+=dp[mask][v];
      for(int u=s+1;u<n;u++)if((adj[v]>>u&1)&&!(mask>>u&1))dp[mask|1<<u][u]+=dp[mask][v];}}
  cout<<ans/2<<endl;}

#include <bits/stdc++.h>
using namespace std;
int main(){string s;cin>>s;int n=s.size(),c1=count(s.begin(),s.end(),'1'),c0=n-c1;int T=c0*c1/2,S=c0*c1;
  const int INF=1e9;vector<vector<int>>dp(c1+1,vector<int>(S+1,INF));dp[0][0]=0; // dp[j][x]: j ones placed, x "01" pairs
  for(int i=0;i<n;i++){for(int j=min(i,c1);j>=0;j--)for(int x=S;x>=0;x--){if(dp[j][x]>=INF)continue;int v=dp[j][x];
      // placing 0 at i keeps the state; placing 1 costs 1 if s[i] was 0 (one swap each)
      if(j<c1){int z=i-j;if(x+z<=S)dp[j+1][x+z]=min(dp[j+1][x+z],v+(s[i]=='0'));}}}
  printf("%d\n",dp[c1][T]);}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;const ll MOD=998244353;
ll pw(ll b,ll e){ll r=1;b%=MOD;while(e){if(e&1)r=r*b%MOD;b=b*b%MOD;e>>=1;}return r;}
int main(){int t;scanf("%d",&t);while(t--){int k;ll n;scanf("%d %lld",&k,&n);const int J=17;
 // g[j][x]: sequences of j elements, each >=2, with product x
 vector<vector<ll>>g(J+1,vector<ll>(k+1,0));for(int x=2;x<=k;x++)g[1][x]=1;
 for(int j=2;j<=J;j++)for(int x=2;x<=k;x++)if(g[j-1][x])for(ll y=2;x*y<=k;y++)g[j][x*y]=(g[j][x*y]+g[j-1][x])%MOD;
 // inserting ones: sum_{len=1..n} C(len,j) = C(n+1,j+1)
 vector<ll>Cn(J+2);for(int j=0;j<=J;j++){ll num=1,den=1;for(int i=0;i<=j;i++){num=num*((n+1-i)%MOD)%MOD;den=den*(i+1)%MOD;}Cn[j]=num*pw(den,MOD-2)%MOD;}
 for(int x=1;x<=k;x++){ll ans=0;if(x==1)ans=n%MOD;else for(int j=1;j<=J;j++)ans=(ans+g[j][x]*Cn[j])%MOD;printf("%lld ",ans);}puts("");}}

#include <bits/stdc++.h>
using namespace std;
vector<int>p;int fnd(int x){while(p[x]!=x)x=p[x]=p[p[x]];return x;}
int main(){int n,m;scanf("%d %d",&n,&m);int N=n*m;vector<int>a(N);for(auto&x:a)scanf("%d",&x);
 p.resize(N);iota(p.begin(),p.end(),0);
 // equal values in the same row/column must get equal results: union them
 for(int i=0;i<n;i++){vector<int>id(m);iota(id.begin(),id.end(),0);sort(id.begin(),id.end(),[&](int x,int y){return a[i*m+x]<a[i*m+y];});
  for(int j=1;j<m;j++)if(a[i*m+id[j]]==a[i*m+id[j-1]])p[fnd(i*m+id[j])]=fnd(i*m+id[j-1]);}
 for(int j=0;j<m;j++){vector<int>id(n);iota(id.begin(),id.end(),0);sort(id.begin(),id.end(),[&](int x,int y){return a[x*m+j]<a[y*m+j];});
  for(int i=1;i<n;i++)if(a[id[i]*m+j]==a[id[i-1]*m+j])p[fnd(id[i]*m+j)]=fnd(id[i-1]*m+j);}
 vector<int>ord(N);iota(ord.begin(),ord.end(),0);sort(ord.begin(),ord.end(),[&](int x,int y){return a[x]<a[y];});
 vector<int>rowMx(n,0),colMx(m,0),val(N,0),res(N);
 for(int s=0;s<N;){int e=s;while(e<N&&a[ord[e]]==a[ord[s]])e++;
  for(int q=s;q<e;q++){int c=ord[q],r=fnd(c);val[r]=max(val[r],max(rowMx[c/m],colMx[c%m])+1);} // component value
  for(int q=s;q<e;q++){int c=ord[q];res[c]=val[fnd(c)];}
  for(int q=s;q<e;q++){int c=ord[q];rowMx[c/m]=max(rowMx[c/m],res[c]);colMx[c%m]=max(colMx[c%m],res[c]);}
  s=e;}
 for(int i=0;i<n;i++){for(int j=0;j<m;j++)printf("%d ",res[i*m+j]);puts("");}}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main(){int t;scanf("%d",&t);while(t--){int n,m;scanf("%d %d",&n,&m);const int INF=1e9;
 vector<vector<int>>d(n+1,vector<int>(n+1,INF));for(int i=1;i<=n;i++)d[i][i]=0;
 vector<array<ll,3>>e(m);for(auto&x:e){scanf("%lld %lld %lld",&x[0],&x[1],&x[2]);d[x[0]][x[1]]=d[x[1]][x[0]]=1;}
 for(int k=1;k<=n;k++)for(int i=1;i<=n;i++)if(d[i][k]<INF)for(int j=1;j<=n;j++)d[i][j]=min(d[i][j],d[i][k]+d[k][j]); // hop distances
 ll ans=LLONG_MAX;
 for(auto&x:e){int u=x[0],v=x[1];ll w=x[2];
  ll best=min(d[1][u]+d[v][n],d[1][v]+d[u][n])+1;          // slide ends to 1 and n, then cross once
  for(int y=1;y<=n;y++)best=min(best,(ll)min(d[u][y],d[v][y])+1+d[y][1]+d[y][n]+1); // collapse to self-loop at y first
  ans=min(ans,best*w);}
 printf("%lld\n",ans);}}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;const ll MOD=1e9+7;
// f(w) = prod_{i=1}^{n-1} (w_i ? 2 : i-1), and 0 unless w_n = 1 (and w_1 = 1)
int main(){int t;scanf("%d",&t);while(t--){int n;ll c;static char buf[200005];scanf("%d %lld %s",&n,&c,buf);string s(buf);
 if(c==1||s[0]=='0'||s[n-1]=='0'){puts("-1");continue;}
 int e=__builtin_ctzll(c);ll codd=c>>e;
 // cheapest choice: '?' at i=2 -> 0 (factor 1), at i>=3 -> 1 (factor 2)
 vector<int>fac(n,0);ll v2=0,oddmod=1%codd;vector<int>cand; // cand: '?' at even i>=4 (factor i-1 odd)
 for(int i=1;i<=n-1;i++){char ch=s[i-1];ll f;
  if(ch=='1')f=2;else if(ch=='0')f=i-1;else{f=(i==2)?1:2;if(i%2==0&&i>=4)cand.push_back(i);}
  fac[i]=f;ll x=f;while(x%2==0){x/=2;v2++;}oddmod=oddmod*(x%codd)%codd;}
 bool divisible=(v2>=e)&&(oddmod%codd==0);
 if(divisible){ll r=v2-e+1; // need to remove r factors of 2: switch r cheapest candidates 2 -> (i-1)
  if((ll)cand.size()<r){puts("-1");continue;}
  for(ll q=0;q<r;q++)fac[cand[q]]=cand[q]-1;}
 ll ans=1;for(int i=1;i<=n-1;i++)ans=ans*(fac[i]%MOD)%MOD;printf("%lld\n",ans);}}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;const ll MOD=998244353;const int MX=3000;
static short G[MX+1][MX+1]; // G[a][b], a<=b: final common value for subsequence with min a, max b
int main(){vector<int>rad(MX+1,1);for(int p=2;p<=MX;p++)if(rad[p]==1)for(int k=p;k<=MX;k+=p)rad[k]*=p;
 // greedy: if b has a prime not dividing a, decrement b alone; otherwise decrement both
 for(int b=1;b<=MX;b++){G[b][b]=b;for(int a=1;a<b;a++)G[a][b]=(a%rad[b]!=0)?G[a][b-1]:(a-1==b-1?a-1:G[a-1][b-1]);}
 vector<ll>p2(MX+1,1);for(int i=1;i<=MX;i++)p2[i]=p2[i-1]*2%MOD;
 int t;scanf("%d",&t);while(t--){int n;scanf("%d",&n);vector<int>c(n+1,0);for(int i=0;i<n;i++){int x;scanf("%d",&x);c[x]++;}
  vector<int>pre(n+1,0);for(int v=1;v<=n;v++)pre[v]=pre[v-1]+c[v];ll ans=0;
  for(int u=1;u<=n;u++)if(c[u]){ll wu=(p2[c[u]]-1+MOD)%MOD;ans=(ans+wu*u)%MOD;
   for(int v=u+1;v<=n;v++)if(c[v])ans=(ans+wu*((p2[c[v]]-1+MOD)%MOD)%MOD*p2[pre[v-1]-pre[u]]%MOD*G[u][v])%MOD;}
  printf("%lld\n",ans);}}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;const ll MOD=1e9+7;const int MX=500000;
int spf[MX+1];
ll coef(const vector<int>&caps,int M,int D){ // [t^D] prod (1+t+..+t^{min(b,M)})
 if(M<0)return 0;vector<ll>p(D+1,0);p[0]=1;
 for(int b:caps){int m=min(b,M);vector<ll>q(D+1);ll w=0;
  for(int d=0;d<=D;d++){w+=p[d];if(d-m-1>=0)w-=p[d-m-1];q[d]=((w%MOD)+MOD)%MOD;}p=q;} // sliding window
 return p[D];}
int main(){for(int i=2;i<=MX;i++)if(!spf[i])for(int j=i;j<=MX;j+=i)if(!spf[j])spf[j]=i;
 int t;scanf("%d",&t);while(t--){int n,x;scanf("%d %d",&n,&x);map<int,vector<int>>caps;map<int,int>cx;
  for(int i=0;i<n;i++){int a;scanf("%d",&a);while(a>1){int p=spf[a],e=0;while(a%p==0){a/=p;e++;}caps[p].push_back(e);}}
  while(x>1){int p=spf[x];while(x%p==0){x/=p;cx[p]++;}}
  ll ans=1;
  for(auto&[p,c]:cx)if(!caps.count(p))ans=0; // need sum - max = c > 0 but every exponent is 0
  for(auto&[p,v]:caps){if(!ans)break;int c=cx.count(p)?cx[p]:0,mb=*max_element(v.begin(),v.end());ll s=0;
   for(int M=0;M<=mb;M++)s+=coef(v,M,M+c)-coef(v,M-1,M+c); // the max exponent is exactly M, the rest sum to c
   ans=ans*(((s%MOD)+MOD)%MOD)%MOD;}
  printf("%lld\n",ans);}}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;const ll MOD=998244353;
ll pw(ll b,ll e){ll r=1;b%=MOD;while(e){if(e&1)r=r*b%MOD;b=b*b%MOD;e>>=1;}return r;}
int main(){int n,m;cin>>n>>m;string A,B;cin>>A>>B;vector<ll>ca(27,0),cb(27,0);for(char c:A)ca[c-'A']++;for(char c:B)cb[c-'A']++;
 vector<ll>F(n+1,1),IF(n+1);for(int i=1;i<=n;i++)F[i]=F[i-1]*i%MOD;IF[n]=pw(F[n],MOD-2);for(int i=n;i>0;i--)IF[i-1]=IF[i]*i%MOD;
 auto C=[&](int a,int b)->ll{return b<0||b>a?0:F[a]*IF[b]%MOD*IF[a-b]%MOD;};
 // x_c = how many A-letters c are matched to c+1; need (ca[c]-x_c) + x_{c-1} <= cb[c]
 vector<ll>dp(1,1);
 for(int c=0;c<26;c++){int mx=(c==25)?0:ca[c];vector<ll>pre(dp.size()+1,0);for(size_t i=0;i<dp.size();i++)pre[i+1]=(pre[i]+dp[i])%MOD;
  vector<ll>nd(mx+1,0);
  for(int x=0;x<=mx;x++){ll lim=cb[c]-ca[c]+x;if(lim<0)continue;lim=min<ll>(lim,dp.size()-1);nd[x]=pre[lim+1]*C(ca[c],x)%MOD;}
  dp=nd;}
 ll ways=0;for(int x=0;x<(int)dp.size();x++){ll lim=cb[26]-ca[26]+x; if(x<=lim)ways=(ways+dp[x])%MOD;} // nothing after 'Z'
 ll perm=F[n];for(int c=0;c<26;c++)perm=perm*IF[ca[c]]%MOD;
 cout<<perm*ways%MOD<<endl;}

#include <bits/stdc++.h>
