string S;int n;static short lcp[5001][5001],G[5001][5002]; // G[j][k] = max over k'>=k of f(j,k'); -1 = impossible
int k0(int i,int j){int L=j-i,l=lcp[i][j];if(l>=L)return j+L+1;if(j+l>=n||S[j+l]<S[i+l])return n+1;return j+l+1;} // next word S[j..k) > S[i..j) iff k >= k0
int f(int i,int j){if(j==n)return 1;int k=k0(i,j);if(k>n||G[j][k]<0)return -1;return G[j][k]+1;}
int main(){cin>>S;n=S.size();for(int i=n-1;i>=0;i--)for(int j=n-1;j>=0;j--)lcp[i][j]=S[i]==S[j]?lcp[i+1][j+1]+1:0;
 for(int i=n-1;i>=0;i--){G[i][n+1]=-1;for(int j=n;j>i;j--)G[i][j]=max<int>(G[i][j+1],f(i,j));}
 vector<string>w;int i=0,j=-1,need=G[0][1];for(int t=i+1;t<=n;t++)if(f(0,t)==need){j=t;break;}
 while(true){w.push_back(S.substr(i,j-i));if(j==n)break;int k=k0(i,j),want=f(i,j)-1;
  for(int t=k;t<=n;t++)if(f(j,t)==want){i=j;j=t;break;}}
 printf("%d\n",(int)w.size());for(auto&x:w)puts(x.c_str());}

