 for(int j=1;j<=n;j++){if(s[j]=='0'){W[2*j]=j-1;W[2*j+1]=n-j;}else W[2*j]=1;}
 for(int j=1;j<=n;j++){
  if(s[j]=='0'&&j<n&&s[j+1]=='0'){un(2*j,2*j+2);un(2*j+1,2*j+3);}
  if(s[j]=='1'){if(j>1&&s[j-1]=='0')un(2*j,2*j-1); if(j<n&&s[j+1]=='0')un(2*j,2*j+2);}}
