using namespace std;typedef long long ll;const ll NEG=LLONG_MIN/4;
int N;vector<ll>mx,lz;
void app(int x,ll v){if(mx[x]>NEG/2)mx[x]+=v;lz[x]+=v;}
void push(int x){if(lz[x]){app(2*x,lz[x]);app(2*x+1,lz[x]);lz[x]=0;}}
void add(int x,int l,int r,int ql,int qr,ll v){if(qr<l||r<ql)return;if(ql<=l&&r<=qr){app(x,v);return;}push(x);int m=(l+r)/2;add(2*x,l,m,ql,qr,v);add(2*x+1,m+1,r,ql,qr,v);mx[x]=max(mx[2*x],mx[2*x+1]);}
ll qry(int x,int l,int r,int ql,int qr){if(qr<l||r<ql)return NEG;if(ql<=l&&r<=qr)return mx[x];push(x);int m=(l+r)/2;return max(qry(2*x,l,m,ql,qr),qry(2*x+1,m+1,r,ql,qr));}
void chmax(int x,int l,int r,int p,ll v){if(l==r){mx[x]=max(mx[x],v);return;}push(x);int m=(l+r)/2;if(p<=m)chmax(2*x,l,m,p,v);else chmax(2*x+1,m+1,r,p,v);mx[x]=max(mx[2*x],mx[2*x+1]);}
int main(){int t;scanf("%d",&t);while(t--){int n;scanf("%d",&n);vector<ll>v(n+1);for(int i=1;i<=n;i++)scanf("%lld",&v[i]);
 vector<int>a(n),pb(n+1);for(auto&x:a)scanf("%d",&x);for(int i=1;i<=n;i++){int x;scanf("%d",&x);pb[x]=i;}
 N=n+1;mx.assign(4*N,NEG);lz.assign(4*N,0);chmax(1,0,n,0,0); // state T in [0,n]: max b-position among excluded items
 for(int x:a){int p=pb[x];ll m=qry(1,0,n,0,p-1);add(1,0,n,0,p-1,v[x]);chmax(1,0,n,p,m);}
 printf("%lld\n",qry(1,0,n,0,n));}}

#include <bits/stdc++.h>
using namespace std;typedef long long ll;const ll M=998244353;
int main(){int t;scanf("%d",&t);while(t--){int n;scanf("%d",&n);vector<ll>p(n);for(auto&x:p)scanf("%lld",&x);
 vector<ll>dp(n),pre(n+1,0);vector<int>st;ll stsum=0; // stsum = sum of dp over stack
 for(int i=0;i<n;i++){
  while(!st.empty()&&p[st.back()]>p[i]){stsum=(stsum-dp[st.back()]+M)%M;st.pop_back();}
  ll v;
  if(st.empty()) v=(1+pre[i])%M; // all earlier j valid (interior>p_i) plus start
  else{int L=st.back();v=((pre[i]-pre[L]+M)%M + stsum - dp[L] + M)%M; // j in [L,i-1] plus stack elems below L
  }
  dp[i]=v;pre[i+1]=(pre[i]+v)%M;st.push_back(i);stsum=(stsum+v)%M;}
 printf("%lld\n",stsum);}}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main(){int t;scanf("%d",&t);while(t--){int n,m;ll p;scanf("%d %d %lld",&n,&m,&p);
 vector<ll>w(n);for(auto&x:w)scanf("%lld",&x);
 vector<vector<pair<int,ll>>>g(n);for(int i=0;i<m;i++){int a,b;ll s;scanf("%d %d %lld",&a,&b,&s);g[a-1].push_back({b-1,s});}
 // state (v,b): best pair (perf min, coins max)
 const ll INF=LLONG_MAX;vector<pair<ll,ll>>best((size_t)n*n,{INF,0});
 priority_queue<tuple<ll,ll,int,int>,vector<tuple<ll,ll,int,int>>,greater<>>pq;
 best[0]={0,p};pq.push({0,-p,0,0});ll ans=-1;
 while(!pq.empty()){auto[k,nc,v,b]=pq.top();pq.pop();ll c=-nc;
  if(make_pair(k,c)!=best[(size_t)v*n+b])continue;
  if(v==n-1){ans=k;break;}
  for(auto[u,s]:g[v]){ll kk=k,cc=c;if(cc<s){ll need=(s-cc+w[b]-1)/w[b];kk+=need;cc+=need*w[b];}cc-=s;
   int nb=w[u]>w[b]?u:b;auto&B=best[(size_t)u*n+nb];
   if(kk<B.first||(kk==B.first&&cc>B.second)){B={kk,cc};pq.push({kk,-cc,u,nb});}}}
 printf("%lld\n",ans);}}

