#include <bits/stdc++.h>
using namespace std;typedef long long ll;const ll M=1e9+7;
ll pw(ll b,ll e){ll r=1;b%=M;for(;e;e>>=1,b=b*b%M)if(e&1)r=r*b%M;return r;}
bool lucky(ll v){while(v){if(v%10!=4&&v%10!=7)return false;v/=10;}return true;}
int main(){int n,k;scanf("%d %d",&n,&k);map<ll,ll>cnt;ll U=0;
  for(int i=0;i<n;i++){ll v;scanf("%lld",&v);if(lucky(v))cnt[v]++;else U++;}
  vector<ll>dp(cnt.size()+1,0);dp[0]=1;int L=0;
  for(auto&[v,c]:cnt){L++;for(int j=L;j>=1;j--)dp[j]=(dp[j]+dp[j-1]*c)%M;}
  vector<ll>f(n+1,1);for(int i=1;i<=n;i++)f[i]=f[i-1]*i%M;
  auto C=[&](ll a,ll b)->ll{if(b<0||b>a)return 0;return f[a]*pw(f[b]*f[a-b],M-2)%M;};
  ll ans=0;for(int j=0;j<=L&&j<=k;j++)ans=(ans+dp[j]*C(U,k-j))%M;
  printf("%lld\n",ans);}

#include <bits/stdc++.h>
using namespace std;
int main(){int n,m;scanf("%d %d",&n,&m);vector<vector<pair<int,int>>>g(n+1);
  for(int i=0;i<m;i++){int a,b,c;scanf("%d %d %d",&a,&b,&c);g[a].push_back({b,c});g[b].push_back({a,c});}
  vector<int>s(n+1,0);vector<double>cc(n+1,0),ans(n+1,0);vector<int>vis(n+1,0);
  for(int r=1;r<=n;r++)if(!vis[r]){vector<int>comp={r};vis[r]=1;s[r]=1;cc[r]=0;bool fixed=false;double t=0;
    for(size_t i=0;i<comp.size();i++){int u=comp[i];for(auto[v,w]:g[u]){
      if(!vis[v]){vis[v]=1;s[v]=-s[u];cc[v]=w-cc[u];comp.push_back(v);continue;}
      int ss=s[u]+s[v];double cs=cc[u]+cc[v];
      if(ss==0){if(fabs(cs-w)>1e-9){puts("NO");return 0;}}
      else{double tt=(w-cs)/ss;if(fixed&&fabs(tt-t)>1e-9){puts("NO");return 0;}fixed=true;t=tt;}}}
    if(!fixed){vector<double>pts;for(int v:comp)pts.push_back(-s[v]*cc[v]);
      nth_element(pts.begin(),pts.begin()+pts.size()/2,pts.end());t=pts[pts.size()/2];}
    for(int v:comp)ans[v]=s[v]*t+cc[v];}
  puts("YES");for(int i=1;i<=n;i++)printf("%.6f ",ans[i]);puts("");}

#include <bits/stdc++.h>
using namespace std;
int main(){int n;scanf("%d",&n);vector<int>h(n);for(auto&x:h)scanf("%d",&x);
  vector<int>dp(n,0),up,dn;up.push_back(0);dn.push_back(0); // up: increasing-height stack, dn: decreasing
  for(int i=1;i<n;i++){dp[i]=dp[i-1]+1;
    while(!up.empty()&&h[up.back()]<h[i]){up.pop_back();if(!up.empty())dp[i]=min(dp[i],dp[up.back()]+1);} // between are lower
    while(!up.empty()&&h[up.back()]==h[i])up.pop_back();
    while(!dn.empty()&&h[dn.back()]>h[i]){dn.pop_back();if(!dn.empty())dp[i]=min(dp[i],dp[dn.back()]+1);} // between are higher
    while(!dn.empty()&&h[dn.back()]==h[i])dn.pop_back();
    up.push_back(i);dn.push_back(i);}
  printf("%d\n",dp[n-1]);}

