    dp[i]=((x[i]-y[i])%MOD+pre[i]-pre[j]+MOD)%MOD;pre[i+1]=(pre[i]+dp[i])%MOD;if(s[i])ans=(ans+dp[i])%MOD;}
  printf("%lld\n",ans);}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;const ll MOD=1e9+7;const int N=5005;ll F[N],IF[N];
ll pw(ll b,ll e){ll r=1;b%=MOD;while(e){if(e&1)r=r*b%MOD;b=b*b%MOD;e>>=1;}return r;}
ll C(int a,int b){return b<0||b>a?0:F[a]*IF[b]%MOD*IF[a-b]%MOD;}
int main(){F[0]=1;for(int i=1;i<N;i++)F[i]=F[i-1]*i%MOD;IF[N-1]=pw(F[N-1],MOD-2);for(int i=N-1;i>0;i--)IF[i-1]=IF[i]*i%MOD;
 int t;scanf("%d",&t);while(t--){int n,k;scanf("%d %d",&n,&k);vector<int>c(n+1);for(int i=1;i<=n;i++)scanf("%d",&c[i]);
 vector<int>len(n+1,-1);vector<ll>cnt(n+1,0);len[0]=0;cnt[0]=1;
 for(int i=1;i<=n;i++){int same=0;
  for(int j=i-1;j>=0;j--){if(same>=k-1&&len[j]>=0){ll w=cnt[j]*C(same,k-1)%MOD;
    if(len[j]+1>len[i]){len[i]=len[j]+1;cnt[i]=w;}else if(len[j]+1==len[i])cnt[i]=(cnt[i]+w)%MOD;}
   if(j>=1&&c[j]==c[i])same++;}}
 int mx=*max_element(len.begin(),len.end());ll ans=0;for(int i=0;i<=n;i++)if(len[i]==mx)ans=(ans+cnt[i])%MOD;
 printf("%lld\n",ans);}}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;const ll NEG=LLONG_MIN/4;
int main(){int t;scanf("%d",&t);while(t--){int n;scanf("%d",&n);vector<ll>a(n+1);for(int i=1;i<=n;i++)scanf("%lld",&a[i]);
 vector<vector<int>>g(n+1);for(int i=1;i<n;i++){int u,v;scanf("%d %d",&u,&v);g[u].push_back(v);g[v].push_back(u);}
 vector<int>par(n+1,0),ord={1};for(size_t i=0;i<ord.size();i++)for(int u:g[ord[i]])if(u!=par[ord[i]]){par[u]=ord[i];ord.push_back(u);}
 // dp[v]: best sum inside v's subtree when v is kept and also attached to its parent
 vector<ll>dp(n+1);ll ans=0;
 for(int k=n-1;k>=0;k--){int v=ord[k];vector<ll>c;for(int u:g[v])if(u!=par[v])c.push_back(dp[u]);
  sort(c.rbegin(),c.rend());ll pos=0;for(size_t i=0;i<c.size();i++)if(i>=3&&c[i]>0)pos+=c[i];
  ll pos2=pos+(c.size()>2&&c[2]>0?c[2]:0); // positive children beyond the top two
  ll best=a[v];                                      // leaf: degree 1
  if(c.size()>=1)best=max(best,c[0]);                // degree 2: v is compressed away
  if(c.size()>=2)best=max(best,a[v]+c[0]+c[1]+pos2); // degree >= 3: kept
  dp[v]=best;
  // v as the topmost vertex (no parent edge)
  ans=max(ans,a[v]);                                 // isolated
  if(c.size()>=1)ans=max(ans,a[v]+c[0]);             // degree 1
  if(c.size()>=2)ans=max(ans,c[0]+c[1]);             // degree 2 -> compressed
  if(c.size()>=3)ans=max(ans,a[v]+c[0]+c[1]+c[2]+pos);} // degree >= 3
 printf("%lld\n",ans);}}

#include <bits/stdc++.h>
using namespace std;
int main(){int n;cin>>n;vector<int>s(n);for(auto&x:s)cin>>x;sort(s.rbegin(),s.rend());
 int m;cin>>m;vector<char>act(m);vector<int>team(m);for(int i=0;i<m;i++)cin>>act[i]>>team[i];
 // only the m strongest heroes can matter; dp[mask] = (team1 - team2) from action popcount(mask) on
 vector<int>dp(1<<m,0);
 for(int mask=(1<<m)-1;mask>=0;mask--){int i=__builtin_popcount(mask);if(i>=m){dp[mask]=0;continue;}
  bool mx=team[i]==1;int best=mx?INT_MIN:INT_MAX;
  if(act[i]=='p'){int j=0;while(mask>>j&1)j++; // picking: always take the strongest available
   best=dp[mask|1<<j]+(mx?s[j]:-s[j]);}
  else for(int j=0;j<m;j++)if(!(mask>>j&1)){int v=dp[mask|1<<j];best=mx?max(best,v):min(best,v);}
  dp[mask]=best;}
 cout<<dp[0]<<endl;}

