  for(int a0=0;a0<2;a0++)for(int a1=0;a1<2;a1++){long long dp[2][2]={};dp[a0][a1]=1; // dp[P_{i-1}][P_i]
    for(int i=1;i<n-1;i++){long long nd[2][2]={};
      for(int x=0;x<2;x++)for(int y=0;y<2;y++)if(dp[x][y])for(int z=0;z<2;z++)if(out(x,y,z)==s[i])nd[y][z]+=dp[x][y];
      memcpy(dp,nd,sizeof dp);}
    for(int x=0;x<2;x++)for(int y=0;y<2;y++)if(dp[x][y]&&out(x,y,a0)==s[n-1]&&out(y,a0,a1)==s[0])total+=dp[x][y];}
