int main(){int d,s;cin>>d>>s;
 // BFS on (remainder, digit sum); digits tried in increasing order -> shortest, then lexicographically smallest
 vector<int>par((size_t)d*(s+1),-1);vector<char>dig((size_t)d*(s+1));vector<char>vis((size_t)d*(s+1),0);
 queue<int>q;q.push(0);vis[0]=1;int target=-1;
 while(!q.empty()){int u=q.front();q.pop();int r=u/(s+1),sm=u%(s+1);if(r==0&&sm==s){target=u;break;}
  for(int c=0;c<=9;c++){int ns=sm+c;if(ns>s)break;int nr=(r*10+c)%d,v=nr*(s+1)+ns;if(vis[v])continue;vis[v]=1;par[v]=u;dig[v]='0'+c;q.push(v);}}
 if(target<0){puts("-1");return 0;}
