int main(){int t;scanf("%d",&t);while(t--){int n,m,q;scanf("%d %d %d",&n,&m,&q);vector<vector<int>>rg(n+1);vector<int>out(n+1,0);
 for(int i=0;i<m;i++){int u,v;scanf("%d %d",&u,&v);rg[v].push_back(u);out[u]++;}
 // win[v][p]: Cry wins with token at v and player p to move (0 = Cry, 1 = River). Initially all true.
 vector<array<char,2>>win(n+1,{1,1});vector<int>cnt=out; // cnt[v]: successors u whose (u, River) is still winning
