  while(!st.empty()){auto [x,px]=st.back();st.pop_back();
   for(int y:rg[x]){int py=1-px; // predecessor state (y, py) moves into (x, px)
    if(!win[y][py])continue;
    if(py==1){win[y][1]=0;st.push_back({y,1});}           // River picks the losing move
    else if(--cnt[y]==0){win[y][0]=0;st.push_back({y,0});}}}}; // Cry has no winning move left
 vector<char>red(n+1,0);
 while(q--){int x,u;scanf("%d %d",&x,&u);
  if(x==1){red[u]=1;for(int p=0;p<2;p++)if(win[u][p])lose(u,p);}
  else puts(win[u][0]?"YES":"NO");}}}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;const ll MOD=998244353;const int N=200005;ll F[N],IF[N],P2[N];
ll pw(ll b,ll e){ll r=1;b%=MOD;while(e){if(e&1)r=r*b%MOD;b=b*b%MOD;e>>=1;}return r;}
ll C(int a,int b){return b<0||b>a?0:F[a]*IF[b]%MOD*IF[a-b]%MOD;}
int main(){F[0]=1;P2[0]=1;for(int i=1;i<N;i++){F[i]=F[i-1]*i%MOD;P2[i]=P2[i-1]*2%MOD;}IF[N-1]=pw(F[N-1],MOD-2);for(int i=N-1;i>0;i--)IF[i-1]=IF[i]*i%MOD;
 int t;scanf("%d",&t);while(t--){int n;scanf("%d",&n);vector<int>cnt(n+1,0);for(int i=0;i<n;i++){int x;scanf("%d",&x);cnt[x]++;}
 // score = sum_i min(c_0..c_i). dp[m] = #ways to choose copies of values 0..i with prefix-min count m (m>=1)
 ll ans=0;int done=0;vector<ll>dp;
 for(int i=0;i<n;i++){int c=cnt[i];done+=c;if(c==0)break;
  vector<ll>nd(c+1,0);
  if(i==0){for(int j=1;j<=c;j++)nd[j]=C(c,j);}
  else{int M=dp.size()-1;vector<ll>sufC(c+2,0),sufD(M+2,0);
   for(int j=c;j>=0;j--)sufC[j]=(sufC[j+1]+C(c,j))%MOD;for(int m=M;m>=0;m--)sufD[m]=(sufD[m+1]+dp[m])%MOD;
   for(int m=1;m<=min(c,M);m++)nd[m]=(dp[m]*sufC[m]+C(c,m)*sufD[m+1])%MOD;} // min(m_old, j) = m
  while(nd.size()>1&&nd.back()==0)nd.pop_back();dp=nd;
  ll s=0;for(int m=1;m<(int)dp.size();m++)s=(s+m*dp[m])%MOD;
  ans=(ans+s*P2[n-done])%MOD;}                       // elements with values > i are free
 printf("%lld\n",ans);}}

