// R[x][y][a][b]: x sets won by A, y by B, with point totals a, b; PA/PB = the last set's score
static bool R[4][4][201][201];static short PA[4][4][201][201],PB[4][4][201][201];
int main(){R[0][0][0][0]=1;
 for(int x=0;x<=3;x++)for(int y=0;y<=3;y++){if(x==3&&y==3)continue;
  for(int a=0;a<=200;a++)for(int b=0;b<=200;b++)for(int w=0;w<2&&!R[x][y][a][b];w++){
   int px=x-(w==0),py=y-(w==1);if(px<0||py<0||px==3||py==3)continue; // previous state must be unfinished
   int T=(px+py==4)?15:25;
   for(int L=0;L<=200&&!R[x][y][a][b];L++){int W=L<=T-2?T:L+2; // last set: winner W, loser L
    int sa=w==0?W:L,sb=w==0?L:W,pa=a-sa,pb=b-sb;
    if(pa>=0&&pb>=0&&R[px][py][pa][pb]){R[x][y][a][b]=1;PA[x][y][a][b]=sa;PB[x][y][a][b]=sb;}}}}
 int m;scanf("%d",&m);int ord[6][2]={{3,0},{3,1},{3,2},{2,3},{1,3},{0,3}};string out;
 while(m--){int a,b;scanf("%d %d",&a,&b);bool f=false;
  for(auto&o:ord){int x=o[0],y=o[1];if(!R[x][y][a][b])continue;f=true;vector<string>s;int ca=a,cb=b,cx=x,cy=y;
   while(cx+cy>0){int sa=PA[cx][cy][ca][cb],sb=PB[cx][cy][ca][cb];s.push_back(to_string(sa)+":"+to_string(sb));
    if(sa>sb)cx--;else cy--;ca-=sa;cb-=sb;}
   reverse(s.begin(),s.end());out+=to_string(x)+":"+to_string(y)+"\n";for(auto&z:s)out+=z+" ";out+="\n";break;}
  if(!f)out+="Impossible\n";}
 fputs(out.c_str(),stdout);}

