typedef long long ll;int K;ll X;
string build(int n,char f,char l,int c){ // length n, first f, last l, exactly c "AC"; "" if this try fails
 if(n==1&&f!=l)return "";
 for(int off=0;off<2;off++){string s(n,'B');s[0]=f;s[n-1]=l;int got=0;
  for(int i=off;i+1<n&&got<c;i+=2){if(i==0&&f!='A')continue;if(i+1==n-1&&l!='C')break;s[i]='A';s[i+1]='C';got++;}
  s[0]=f;s[n-1]=l;int cnt=0;for(int i=0;i+1<n;i++)cnt+=s[i]=='A'&&s[i+1]=='C';if(cnt==c)return s;}
 return "";}
int main(){int n,m;cin>>K>>X>>n>>m;string F="ACB";
 for(char f1:F)for(char l1:F)for(int c1=0;2*c1<=n;c1++){string s1=build(n,f1,l1,c1);if(s1.empty())continue;
  for(char f2:F)for(char l2:F)for(int c2=0;2*c2<=m;c2++){string s2=build(m,f2,l2,c2);if(s2.empty())continue;
   ll a=c1,b=c2;char af=f1,al=l1,bf=f2,bl=l2; // s_i = s_{i-2}+s_{i-1}: count adds a junction AC if al=='A' && bf=='C'
   for(int i=3;i<=K&&b<=X;i++){ll c=a+b+(al=='A'&&bf=='C');char cf=af,cl=bl;a=b;af=bf;al=bl;b=c;bf=cf;bl=cl;}
   if(b==X){cout<<s1<<"\n"<<s2<<"\n";return 0;}}}
 puts("Happy new year!");}

