int main(){scanf("%d %d",&n,&m);d.resize(n+1);int neg=0,sum=0;
 for(int i=1;i<=n;i++){scanf("%d",&d[i]);if(d[i]==-1)neg=i;else sum+=d[i];}
 if(!neg&&sum%2){puts("-1");return 0;}
 for(int i=1;i<=n;i++)if(d[i]==-1)d[i]=0;
 if(neg&&sum%2)d[neg]=1;               // fix parity using one free vertex
 adj.resize(n+1);for(int i=1;i<=m;i++){int u,v;scanf("%d %d",&u,&v);adj[u].push_back({v,i});adj[v].push_back({u,i});}
 par.assign(n+1,0);pe.assign(n+1,0);vector<char>vis(n+1,0);
 vector<int>st={1};vis[1]=1;while(!st.empty()){int u=st.back();st.pop_back();order_.push_back(u);
  for(auto[v,id]:adj[u])if(!vis[v]){vis[v]=1;par[v]=u;pe[v]=id;st.push_back(v);}}
 vector<int>ans;for(int i=n-1;i>0;i--){int u=order_[i];if(d[u]){ans.push_back(pe[u]);d[par[u]]^=1;}}
 printf("%d\n",(int)ans.size());for(int x:ans)printf("%d\n",x);}

