typedef long long ll;
int main(){int t;scanf("%d",&t);static char buf[1000005];while(t--){int n,q;scanf("%d %d %s",&n,&q,buf);string s(buf);
 while(q--){int l,r;scanf("%d %d",&l,&r);l--;string u=s.substr(l,r-l);int m=u.size();
  vector<int>z(m,0);z[0]=m;for(int i=1,L=0,R=0;i<m;i++){if(i<R)z[i]=min(R-i,z[i-L]);while(i+z[i]<m&&u[z[i]]==u[i+z[i]])z[i]++;if(i+z[i]>R){L=i;R=i+z[i];}}
  // dp[len] = f(u[0..len)); last piece u[a..len) must be a prefix: z[a] >= len-a. Take the largest such a.
  vector<int>dp(m+1,0);vector<int>st;ll sum=0;
  for(int len=1;len<=m;len++){if(len-1>=1)st.push_back(len-1);
   while(!st.empty()&&st.back()+z[st.back()]<len)st.pop_back();
   dp[len]=st.empty()?1:dp[st.back()]+1;sum+=dp[len];}
  printf("%lld\n",sum);}}}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;const ll MOD=1e9+7;
ll pw(ll b,ll e){ll r=1;b%=MOD;while(e){if(e&1)r=r*b%MOD;b=b*b%MOD;e>>=1;}return r;}
int main(){int t;scanf("%d",&t);while(t--){int n,l,k;scanf("%d %d %d",&n,&l,&k);
 // keys are matched one by one; with r unmatched locks the success comes on attempt X ~ Uniform{1..r}
 vector<ll>dist(n,0),e(n,0);dist[0]=1; // dist[p]: prob. that the next turn belongs to member p
 for(int r=l;r>=1;r--){ll inv=pw(r,MOD-2);vector<ll>cnt(n,0);for(int d=0;d<n;d++){ll c=(r>=d?(r-d)/n+(d>0?1:0):0);if(d==0)c=r/n;cnt[d]=c%MOD;} // #x in [1,r], x%n==d
  vector<ll>nd(n,0);
  for(int p=0;p<n;p++)if(dist[p])for(int d=0;d<n;d++)if(cnt[d]){ll pr=dist[p]*cnt[d]%MOD*inv%MOD;
   int np=(p+d)%n;nd[np]=(nd[np]+pr)%MOD;e[(np-1+n)%n]=(e[(np-1+n)%n]+pr)%MOD;} // success on the X-th turn
  dist=nd;}
 for(int i=0;i<n;i++)printf("%lld ",e[i]);puts("");}}

#include <bits/stdc++.h>
using namespace std;
const int K=10; // answer <= 9: a length-k cover needs 2^k distinct substrings, and only ~100k can exist
struct S{string pre,suf;vector<vector<char>>has;};
S make(const string&s){S r;r.has.assign(K+1,{});for(int k=1;k<=K;k++){r.has[k].assign(1<<k,0);
  for(int i=0;i+k<=(int)s.size();i++)r.has[k][stoi(s.substr(i,k),nullptr,2)]=1;}
 r.pre=s.substr(0,min<size_t>(s.size(),K));r.suf=s.substr(s.size()-min<size_t>(s.size(),K));return r;}
int main(){int n;cin>>n;vector<S>v;for(int i=0;i<n;i++){string s;cin>>s;v.push_back(make(s));}
 int m;cin>>m;while(m--){int a,b;cin>>a>>b;a--;b--;
  S c=make(v[a].suf+v[b].pre); // substrings that cross the boundary
  for(int k=1;k<=K;k++)for(int x=0;x<(1<<k);x++)c.has[k][x]|=v[a].has[k][x]|v[b].has[k][x];
  string p=v[a].pre+v[b].pre,s=v[a].suf+v[b].suf;
  c.pre=p.substr(0,min<size_t>(p.size(),K));c.suf=s.substr(s.size()-min<size_t>(s.size(),K));
  int ans=0;for(int k=1;k<=K;k++){bool all=true;for(int x=0;x<(1<<k);x++)if(!c.has[k][x])all=false;if(all)ans=k;else break;}
  printf("%d\n",ans);v.push_back(c);}}

