typedef long long ll;int n,m;ll k,a[20][20];int half;vector<map<ll,ll>>mp;ll ans=0;
void f1(int i,int j,ll x){x^=a[i][j];if(i+j==half){mp[i][x]++;return;}if(i+1<n)f1(i+1,j,x);if(j+1<m)f1(i,j+1,x);}
void f2(int i,int j,ll x){if(i+j==half){auto it=mp[i].find(x^k);if(it!=mp[i].end())ans+=it->second;return;}x^=a[i][j]; // middle cell counted in first half only
 if(i>0)f2(i-1,j,x);if(j>0)f2(i,j-1,x);}
