int main(){int n,m,q;scanf("%d %d %d",&n,&m,&q);vector<vector<int>>g(n+1);p.resize(n+1);iota(p.begin(),p.end(),0);dia.assign(n+1,0);
 for(int i=0;i<m;i++){int a,b;scanf("%d %d",&a,&b);g[a].push_back(b);g[b].push_back(a);p[find(a)]=find(b);}
 vector<int>dist(n+1,-1),dist2(n+1,-1);
 auto bfs=[&](int s,vector<int>&d){vector<int>vis{s};d[s]=0;for(size_t i=0;i<vis.size();i++)for(int w:g[vis[i]])if(d[w]<0){d[w]=d[vis[i]]+1;vis.push_back(w);}
  int far=s;for(int v:vis)if(d[v]>d[far])far=v;return make_pair(far,d[far]);};
 for(int v=1;v<=n;v++)if(dist[v]<0){int a=bfs(v,dist).first;dia[find(v)]=bfs(a,dist2).second;} // diameter of each initial tree
 while(q--){int t;scanf("%d",&t);if(t==1){int x;scanf("%d",&x);printf("%d\n",dia[find(x)]);}
  else{int x,y;scanf("%d %d",&x,&y);x=find(x);y=find(y);if(x==y)continue;
   int d=max({dia[x],dia[y],(dia[x]+1)/2+(dia[y]+1)/2+1});p[x]=y;dia[y]=d;}}} // connect the two centres

#include <bits/stdc++.h>
using namespace std;typedef long long ll;const ll NEG=LLONG_MIN/4;
struct BIT{int n;vector<ll>t;void init(int N){n=N;t.assign(n+1,NEG);}void upd(int i,ll v){for(;i<=n;i+=i&-i)t[i]=max(t[i],v);}ll q(int i){ll r=NEG;for(;i>0;i-=i&-i)r=max(r,t[i]);return r;}};
int main(){int T;scanf("%d",&T);while(T--){int n;scanf("%d",&n);vector<ll>P(n+1,0);for(int i=1;i<=n;i++){ll x;scanf("%lld",&x);P[i]=P[i-1]+x;}
 vector<ll>vals(P);sort(vals.begin(),vals.end());vals.erase(unique(vals.begin(),vals.end()),vals.end());int K=vals.size();
 auto id=[&](ll v){return int(lower_bound(vals.begin(),vals.end(),v)-vals.begin())+1;};
 BIT lo,hi;lo.init(K);hi.init(K);vector<ll>eq(K+1,NEG);
 auto ins=[&](int j,ll d){int c=id(P[j]);lo.upd(c,d-j);hi.upd(K+1-c,d+j);eq[c]=max(eq[c],d);};
 ins(0,0);ll dp=0;
 for(int i=1;i<=n;i++){int c=id(P[i]);ll best=NEG;ll a=lo.q(c-1);if(a>NEG)best=max(best,a+i);ll b=hi.q(K-c);if(b>NEG)best=max(best,b-i);best=max(best,eq[c]);dp=best;ins(i,dp);}
 printf("%lld\n",dp);}}

#include <bits/stdc++.h>
using namespace std;
int main(){int t;scanf("%d",&t);while(t--){int n,m;scanf("%d %d",&n,&m);vector<long long>a(n+1);
 for(int i=1;i<=n;i++)scanf("%lld",&a[i]);vector<vector<int>>g(n+1),rg(n+1);
 for(int i=0;i<m;i++){int u,v;scanf("%d %d",&u,&v);g[u].push_back(v);rg[v].push_back(u);}
 // Kosaraju (iterative)
 vector<int>ord,comp(n+1,-1);vector<char>vis(n+1,0);
 for(int s=1;s<=n;s++){if(vis[s])continue;vector<pair<int,int>>st={{s,0}};vis[s]=1;
  while(!st.empty()){auto&[u,i]=st.back();if(i<(int)g[u].size()){int v=g[u][i++];if(!vis[v]){vis[v]=1;st.push_back({v,0});}}
   else{ord.push_back(u);st.pop_back();}}}
 int C=0;for(int k=n-1;k>=0;k--){int s=ord[k];if(comp[s]>=0)continue;vector<int>st={s};comp[s]=C;
  while(!st.empty()){int u=st.back();st.pop_back();for(int v:rg[u])if(comp[v]<0){comp[v]=C;st.push_back(v);}}C++;}
 // components are numbered in topological order (0 = source side)
 vector<long long>sz(C,0),sm(C,0);for(int i=1;i<=n;i++){sz[comp[i]]++;sm[comp[i]]+=a[i];}
 vector<vector<int>>cg(C);for(int u=1;u<=n;u++)for(int v:g[u])if(comp[u]!=comp[v])cg[comp[u]].push_back(comp[v]);
 vector<pair<long long,long long>>best(C); // (length, -?) longest path starting at comp: max len, min sum
 pair<long long,long long>ans={0,0};
 for(int c=C-1;c>=0;c--){long long L=0,S=0;for(int d:cg[c]){if(best[d].first>L||(best[d].first==L&&best[d].second<S)){L=best[d].first;S=best[d].second;}}
  best[c]={L+sz[c],S+sm[c]};
  if(best[c].first>ans.first||(best[c].first==ans.first&&best[c].second<ans.second))ans=best[c];}
 printf("%lld %lld\n",ans.first,ans.second);}}

