 for(int i=1;i<=n;i++)scanf("%d",&c[i]);const int INF=1e9;
 // dp[i][j]: ball i kept, j gaps of removed balls so far, min removed count
 vector<vector<int>>dp(n+2,vector<int>(n+2,INF));dp[0][0]=0;
 for(int i=1;i<=n+1;i++)for(int p=0;p<i;p++){if(c[p]>c[i])continue;int add=(p<i-1);
  for(int j=0;j+add<=n;j++)if(dp[p][j]<INF)dp[i][j+add]=min(dp[i][j+add],dp[p][j]+i-p-1);}
 int cur=INF;for(int k=0;k<=n;k++){cur=min(cur,dp[n+1][k]);if(k)printf("%d ",cur);}puts("");}}

