int n,k;vector<vector<int>>g;
void cnt(int v,int p,int d,vector<int>&c){if((int)c.size()<=d)c.resize(d+1,0);c[d]++;for(int u:g[v])if(u!=p)cnt(u,v,d+1,c);}
int main(){int t;cin>>t;while(t--){cin>>n>>k;g.assign(n+1,{});for(int i=1;i<n;i++){int u,v;cin>>u>>v;g[u].push_back(v);g[v].push_back(u);}
 if(k==2){cout<<(long long)n*(n-1)/2%MOD<<"\n";continue;}
 long long ans=0;
 for(int c=1;c<=n;c++){ // center; chosen vertices at equal depth d in k different neighbour branches
  vector<vector<int>>br;for(int u:g[c]){vector<int>x;cnt(u,c,1,x);br.push_back(x);}
  for(int d=1;d<=n;d++){vector<long long>dp(k+1,0);dp[0]=1; // choose k branches, one vertex each at depth d
   for(auto&b:br){long long w=d<(int)b.size()?b[d]:0;if(!w)continue;for(int j=k;j>=1;j--)dp[j]=(dp[j]+dp[j-1]*w)%MOD;}
   ans=(ans+dp[k])%MOD;}}
 cout<<ans<<"\n";}}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;const ll MOD=998244353;
ll pw(ll b,ll e){ll r=1;b%=MOD;if(b<0)b+=MOD;while(e){if(e&1)r=r*b%MOD;b=b*b%MOD;e>>=1;}return r;}
int main(){int n;ll k;cin>>n>>k;vector<ll>h(n);for(auto&x:h)cin>>x;
 int m=0;for(int i=0;i<n;i++)if(h[i]!=h[(i+1)%n])m++; // positions where a_i can change the score difference
 if(m==0){cout<<0<<endl;return 0;}
 vector<vector<ll>>C(m+1,vector<ll>(m+1,0));for(int i=0;i<=m;i++){C[i][0]=1;for(int j=1;j<=i;j++)C[i][j]=(C[i-1][j-1]+C[i-1][j])%MOD;}
 // each such position: +1 (a_i=h_{i+1}), -1 (a_i=h_i), 0 (k-2 ways). zero = # with total 0
 ll zero=0;for(int j=0;2*j<=m;j++)zero=(zero+C[m][j]*C[m-j][j]%MOD*pw(k-2,m-2*j))%MOD;
 ll pos=(pw(k,m)-zero+MOD)%MOD*pw(2,MOD-2)%MOD;   // symmetry: #positive = #negative
 cout<<pos*pw(k,n-m)%MOD<<endl;}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
// f(x)=x*lowbit(x)= x + sum_{j>=1} 2^{j-1} * x*[2^j | x]; with x=i-l+1 each term is linear in i on a stride-2^j progression
int main(){int t;scanf("%d",&t);while(t--){int n,q;scanf("%d %d",&n,&q);int LG=1;while((1<<LG)<=n)LG++;
 vector<vector<ll>>C(LG,vector<ll>(n+2,0)),K(LG,vector<ll>(n+2,0)); // stride difference arrays
 vector<pair<int,int>>Q(q);for(auto&[l,r]:Q)scanf("%d %d",&l,&r);
 for(auto [l,r]:Q)for(int j=0;j<LG;j++){int st=1<<j;int s=(j==0)?l:l-1+st;if(s>r)break;
  ll w=(j==0)?1:(1LL<<(j-1));int e=s+(r-s)/st*st;
  C[j][s]+=w;K[j][s]-=w*(l-1);if(e+st<=n){C[j][e+st]-=w;K[j][e+st]+=w*(l-1);}}
 vector<ll>ans(n+1,0);
 for(int j=0;j<LG;j++){int st=1<<j;for(int i=1;i<=n;i++){if(i>st){C[j][i]+=C[j][i-st];K[j][i]+=K[j][i-st];}
  ans[i]+=C[j][i]*i+K[j][i];}}
 string o;for(int i=1;i<=n;i++)o+=to_string(ans[i])+" ";puts(o.c_str());}}

#include <bits/stdc++.h>
