int n;vector<vector<int>>g;int badv;
long long solve(int root){ // returns path length from root, or -1; sets badv when a non-root vertex has 2 lengths
 vector<int>par(n+1,0),ord;ord.reserve(n);vector<int>st={root};par[root]=-1;
 while(!st.empty()){int v=st.back();st.pop_back();ord.push_back(v);for(int u:g[v])if(u!=par[v]){par[u]=v;st.push_back(u);}}
 vector<long long>len(n+1,0);
 for(int k=n-1;k>=0;k--){int v=ord[k];set<long long>S;
  for(int u:g[v])if(u!=par[v]){if(len[u]<0)return -1;S.insert(len[u]+1);}
  if(S.size()<=1)len[v]=S.empty()?0:*S.begin();
  else if(S.size()==2&&v==root)len[v]=*S.begin()+*S.rbegin();
  else{if(S.size()==2)badv=v;return -1;}}
 return len[root];}
int main(){scanf("%d",&n);g.assign(n+1,{});for(int i=0;i<n-1;i++){int u,v;scanf("%d %d",&u,&v);g[u].push_back(v);g[v].push_back(u);}
 badv=0;long long L=solve(1);if(L<0&&badv){int r=badv;badv=0;L=solve(r);}
 if(L<0){puts("-1");return 0;}while(L%2==0)L/=2;printf("%lld\n",L);}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;const ll INF=4e18;
int n,m;vector<int>g,par;vector<ll>w; // weighted DSU: an informed v points along g; w = distance to the parent
pair<int,ll> find(int v){vector<int>path;while(par[v]!=v){path.push_back(v);v=par[v];} // v = root (uninformed or sentinel)
 ll acc=0;for(int i=path.size()-1;i>=0;i--){int u=path[i];acc=min(INF,acc+w[u]);w[u]=acc;par[u]=v;}
 return {v,path.empty()?0:w[path[0]]};}
int main(){scanf("%d %d",&n,&m);g.resize(n+2);for(int i=1;i<=n;i++)scanf("%d",&g[i]);vector<ll>v(m),b(m);
 for(auto&x:v)scanf("%lld",&x);for(auto&x:b)scanf("%lld",&x);
 par.resize(n+2);w.assign(n+2,0);for(int i=0;i<=n+1;i++)par[i]=i;int SENT=n+1;ll res=0;
 for(int i=0;i<m;i++){int cur=(v[i]+res-1)%n+1;ll rem=b[i];res=0; // a_i = (v_i + res_{i-1} - 1) mod n + 1
  while(rem>0){auto[r,d]=find(cur);if(r==SENT||d>=rem)break;res++;rem-=d+1;
   auto[r2,d2]=find(g[r]);if(r2==r){par[r]=SENT;w[r]=INF;}else{par[r]=g[r];w[r]=1;} // closing a fully informed cycle -> sentinel
   cur=g[r];}
  printf("%lld\n",res);}}

