 auto solve=[&](bool rows,vector<ll>&c){ll d0=0,d1=c[0];
  for(int i=1;i<n;i++){bool bad[3]={false,false,false}; // delta -1,0,1 -> index 0,1,2
   for(int j=0;j<n;j++){ll df=rows?h[i-1][j]-h[i][j]:h[j][i-1]-h[j][i];if(df>=-1&&df<=1)bad[df+1]=true;}
