typedef long long ll;ll cnt[31][2];
void solve(vector<int>&v,int b){if(v.empty()||b<0)return;vector<int>L,R;ll ones=0,zeros=0;
 for(int x:v){if(x>>b&1){ones++;R.push_back(x);}else{zeros++;cnt[b][0]+=ones;L.push_back(x);}} // 1 before 0 = inversion
 cnt[b][1]+=ones*zeros; // all different-bit pairs; (total - cnt[b][0]) become inversions if bit b is flipped
 solve(L,b-1);solve(R,b-1);}
