using namespace std;
const long long MOD=998244353;const int A=1000001;int spf[A];long long S[A];
int main(){for(int i=2;i<A;i++)if(!spf[i])for(int j=i;j<A;j+=i)if(!spf[j])spf[j]=i;
 int n;scanf("%d",&n);vector<int>a(n);for(auto&v:a)scanf("%d",&v);long long dp=0;
 for(int j=0;j<n;j++){vector<int>pr;int x=a[j];while(x>1){int p=spf[x];pr.push_back(p);while(x%p==0)x/=p;}
  int k=pr.size();vector<pair<int,int>>ds; // squarefree divisor, sign
  for(int m=1;m<(1<<k);m++){int d=1;for(int i=0;i<k;i++)if(m>>i&1)d*=pr[i];ds.push_back({d,__builtin_popcount(m)&1});}
  if(j==0)dp=1;else{dp=0;for(auto[d,odd]:ds)dp=(dp+(odd?S[d]:MOD-S[d]))%MOD;}
  for(auto[d,odd]:ds)S[d]=(S[d]+dp)%MOD;}
 printf("%lld\n",dp);}

