 vector<int>nxt(n+1,0),who(n+1,-1);int mn[3];for(int c=0;c<3;c++)mn[c]=n; // winning card with min p_c
 for(int i=n-1;i>=1;i--){for(int c=0;c<3;c++)if(p[c][mn[c]]<p[c][i]){nxt[i]=mn[c];who[i]=c;break;}
