typedef long long ll;
int main(){int n,m;ll k;cin>>n>>m>>k;vector<array<ll,4>>s(m);for(int i=0;i<m;i++){cin>>s[i][1]>>s[i][2]>>s[i][0];s[i][3]=i+1;} // (c,a,b,id)
 sort(s.begin(),s.end());const ll NEG=LLONG_MIN/4;
 // dp[i][j][d]: subject i is day j with count a_i+d
 vector<vector<vector<ll>>>dp(m,vector<vector<ll>>(n+1,vector<ll>(101,NEG)));vector<vector<vector<int>>>pd(m,vector<vector<int>>(n+1,vector<int>(101,-1)));
 for(int i=0;i<m;i++)for(int d=0;d<=s[i][2]-s[i][1];d++)dp[i][1][d]=s[i][1]+d;
 for(int i=0;i<m;i++)for(int j=2;j<=n;j++)for(int d=0;d<=s[i][2]-s[i][1];d++){ll v=s[i][1]+d;
  for(int p=0;p<i;p++){if(s[p][0]>=s[i][0])continue;
   for(ll prev:{v-k,(v%k==0)?v/k:-1}){ll pdx=prev-s[p][1];if(prev<1||pdx<0||pdx>s[p][2]-s[p][1])continue;
    if(dp[p][j-1][pdx]>NEG&&dp[p][j-1][pdx]+v>dp[i][j][d]){dp[i][j][d]=dp[p][j-1][pdx]+v;pd[i][j][d]=p*101+pdx;}}}}
 ll best=NEG;int bi=-1,bd=-1;for(int i=0;i<m;i++)for(int d=0;d<=100;d++)if(dp[i][n][d]>best){best=dp[i][n][d];bi=i;bd=d;}
 if(best==NEG){puts("NO");return 0;}puts("YES");vector<pair<ll,ll>>out;
 for(int j=n,i=bi,d=bd;j>=1;j--){out.push_back({s[i][3],s[i][1]+d});int q=pd[i][j][d];if(q<0)break;i=q/101;d=q%101;}
 reverse(out.begin(),out.end());for(auto[id,v]:out)printf("%lld %lld\n",id,v);}

#include <bits/stdc++.h>
using namespace std;
const int M=1e9+7;
int main(){int n,k;scanf("%d %d",&n,&k);vector<int>a(n);for(auto&x:a)scanf("%d",&x);
 int W=1<<k; // state = sum of the strictly decreasing tail (each value a power of two), W means "already won"
 vector<long long>dp(W+1,0),nd(W+1);dp[0]=1;
 for(int x:a){fill(nd.begin(),nd.end(),0);
  for(int s=0;s<=W;s++){if(!dp[s])continue;
   for(int v:{2,4}){if(x&&x!=v)continue;int t;
    if(s==W)t=W;else if(v==4&&(s&2))t=4;  // 4 lands after a 2: tail restarts
    else t=min(W,s+v);                      // binary carry = merging
    nd[t]=(nd[t]+dp[s])%M;}}
  swap(dp,nd);}
 printf("%lld\n",dp[W]);}

#include <bits/stdc++.h>
using namespace std;typedef long long ll;
int main(){int n,k,x;scanf("%d %d %d",&n,&k,&x);vector<ll>a(n+1);for(int i=1;i<=n;i++)scanf("%lld",&a[i]);
 const ll NEG=LLONG_MIN/4;vector<ll>prev(n+1,NEG),cur(n+1);prev[0]=0;
 for(int j=1;j<=x;j++){deque<int>dq;cur.assign(n+1,NEG);
  for(int i=1;i<=n;i++){int add=i-1; // push index i-1 from prev layer
   while(!dq.empty()&&prev[dq.back()]<=prev[add])dq.pop_back();dq.push_back(add);
   while(dq.front()<i-k)dq.pop_front();
   if(prev[dq.front()]>NEG)cur[i]=prev[dq.front()]+a[i];}
  swap(prev,cur);}
 ll ans=NEG;for(int i=max(1,n-k+1);i<=n;i++)ans=max(ans,prev[i]);printf("%lld\n",ans>NEG?ans:-1);}

