const int M=500000,INF=1e9;int g[M+1],dp[M+1];
int main(){fill(g,g+M+1,INF);g[1]=0; // g[m]: min vertices in a forest of children with prod(f+2)=m
  for(int m=1;m<=M;m++){if(g[m]<INF)dp[m]=1+g[m];else dp[m]=INF;
    if(dp[m]<INF){long long d=m+2;for(long long k=1;k<=m&&d*k<=M;k++)if(g[k]<INF)g[d*k]=min(g[d*k],dp[m]+g[k]);}
    if(g[m]<INF)for(long long d=3;d<=m+1&&d*m<=M;d++)if(dp[d-2]<INF)g[d*m]=min(g[d*m],dp[d-2]+g[m]);}
  int t;scanf("%d",&t);while(t--){int m;scanf("%d",&m);printf("%d\n",dp[m]>=INF?-1:dp[m]);}}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
ll oddp(ll x){while(x%2==0)x/=2;return x;}
ll full(ll x){return x/oddp(x);}            // max adds to build x alone: 2^p pieces of its odd part
ll nextTo(ll x,ll y){ll o=oddp(x);          // max adds to build x beside existing neighbour y
 if(oddp(y)==o&&y<x)return 1+(x-2*y)/o;    // block touching y must jump straight to 2y
 return x/o;}
int main(){int t;scanf("%d",&t);while(t--){int n;ll k;scanf("%d %lld",&n,&k);vector<ll>a(n);for(auto&x:a)scanf("%lld",&x);
 // start at s: elements left of s built next to their right neighbour, right of s next to their left neighbour
 vector<ll>L(n+1,0),R(n+1,0);
 for(int i=0;i<n;i++)L[i+1]=L[i]+(i+1<n?nextTo(a[i],a[i+1]):0);   // L[s] = sum over i<s
 for(int i=n-1;i>=0;i--)R[i]=R[i+1]+(i>0?nextTo(a[i],a[i-1]):0);   // R[s+1] = sum over i>s
 ll best=0;for(int s=0;s<n;s++)best=max(best,L[s]+full(a[s])+R[s+1]);
 puts(k<=best?"YES":"NO");}}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;const ll MOD=1e9+7;const int D=101; // state: dp[x..x-99], S[x]
typedef vector<vector<ll>> M;
M mul(const M&A,const M&B){M C(D,vector<ll>(D,0));for(int i=0;i<D;i++)for(int k=0;k<D;k++)if(A[i][k]){ll a=A[i][k];for(int j=0;j<D;j++)C[i][j]=(C[i][j]+a*B[k][j])%MOD;}return C;}
int main(){int n;ll x;scanf("%d %lld",&n,&x);vector<ll>cnt(101,0);for(int i=0;i<n;i++){int d;scanf("%d",&d);cnt[d]++;}
 // dp[x] = sum_d cnt[d]*dp[x-d]; S[x] = S[x-1] + dp[x]; dp[0]=1, S[0]=1
 M T(D,vector<ll>(D,0));for(int d=1;d<=100;d++)T[0][d-1]=cnt[d];for(int i=1;i<100;i++)T[i][i-1]=1;
 for(int d=1;d<=100;d++)T[100][d-1]=cnt[d];T[100][100]=1;
 vector<ll>v(D,0);v[0]=1;v[100]=1; // at x=0
 M R(D,vector<ll>(D,0));for(int i=0;i<D;i++)R[i][i]=1;ll e=x;M B=T;while(e){if(e&1)R=mul(R,B);B=mul(B,B);e>>=1;}
 ll ans=0;for(int j=0;j<D;j++)ans=(ans+R[100][j]*v[j])%MOD;printf("%lld\n",ans);}

