using namespace std;
int main(){int n,m;scanf("%d %d",&n,&m);vector<map<int,int>>mp(n+1);int ans=0;
 for(int i=0;i<m;i++){int a,b,w;scanf("%d %d %d",&a,&b,&w);
  int cur=1;auto it=mp[a].lower_bound(w);if(it!=mp[a].begin()){--it;cur=it->second+1;}
  ans=max(ans,cur);auto&M=mp[b];auto j=M.lower_bound(w);
  if(j!=M.begin()&&prev(j)->second>=cur)continue; // dominated by smaller weight with >= value
  if(j!=M.end()&&j->first==w&&j->second>=cur)continue;
  M[w]=cur;j=M.upper_bound(w);while(j!=M.end()&&j->second<=cur)j=M.erase(j);}
 printf("%d\n",ans);}

#include <bits/stdc++.h>
using namespace std;
const long long MOD=998244353;
int main(){int t;scanf("%d",&t);while(t--){int n;scanf("%d",&n);int N=2*n;vector<int>c(N);
 vector<int>fi(n+1,-1),se(n+1,-1);for(int i=0;i<N;i++){scanf("%d",&c[i]);if(fi[c[i]]<0)fi[c[i]]=i;else se[c[i]]=i;}
 int segs=0;long long ways=1;int start=0;set<int>open;
 for(int i=0;i<N;i++){if(fi[c[i]]==i)open.insert(c[i]);else open.erase(c[i]);
  if(open.empty()){ // minimal balanced segment [start,i]
   long long good=0;
   for(int x=start;x<=i;x++){if(fi[c[x]]!=x)continue; // each color once
    int L=fi[c[x]],R=se[c[x]],a=L,b=R; // expand closure; scanned range [a,b] grows to [L,R]
    for(int p=L;p<=R;p++){L=min(L,fi[c[p]]);R=max(R,se[c[p]]);
     while(L<a){a--;R=max(R,se[c[a]]);L=min(L,fi[c[a]]);} }
    if(L==start&&R==i)good++;}
   segs++;ways=ways*(2*good%MOD)%MOD;start=i+1;}}
 printf("%d %lld\n",segs,ways);}}

