int main(){int n,k;cin>>n>>k;int V=n-1; // vertices 2..n, star-edge weights
 vector<vector<ll>>C(V+1,vector<ll>(V+1,0));for(int i=0;i<=V;i++){C[i][0]=1;for(int j=1;j<=i;j++)C[i][j]=(C[i-1][j-1]+C[i-1][j])%MOD;}
 // dp[j]: j vertices assigned star weights <= w; every non-star edge (u,v) needs weight >= max(w_u,w_v)
 vector<ll>dp(V+1,0);dp[0]=1;
 for(int w=1;w<=k;w++){vector<ll>nd(V+1,0);ll base=k-w+1;
  int E=V*V;vector<ll>P(E+1);P[0]=1;for(int e=1;e<=E;e++)P[e]=P[e-1]*base%MOD;
  for(int j=0;j<=V;j++)if(dp[j])for(int t=0;j+t<=V;t++){ll e=(ll)t*j+(ll)t*(t-1)/2; // new edges touching the t vertices of weight w
   nd[j+t]=(nd[j+t]+dp[j]*C[V-j][t]%MOD*P[e])%MOD;}
  dp=nd;}
 cout<<dp[V]<<endl;}

#include <bits/stdc++.h>
using namespace std;
int main(){string s,p;cin>>s>>p;int n=s.size(),m=p.size();const int NEG=-1e9;
 vector<vector<int>>dp(n+1,vector<int>(n+1,NEG));dp[0][0]=0; // dp[i][j]: first i chars processed, j deleted
 for(int i=0;i<n;i++){
  // greedy shortest window starting at i that contains p as subsequence (with s[i]==p[0])
  int e=-1,d=0;{int k=0,x=i;while(x<n&&k<m){if(s[x]==p[k])k++;x++;}if(k==m){e=x;d=(x-i)-m;}}
  for(int j=0;j<=i;j++){if(dp[i][j]==NEG)continue;int v=dp[i][j];
   dp[i+1][j]=max(dp[i+1][j],v);          // keep s[i] (not in a match)
   dp[i+1][j+1]=max(dp[i+1][j+1],v);      // delete s[i]
   if(e>=0)dp[e][j+d]=max(dp[e][j+d],v+1);}} // take a match, deleting the extra chars inside the window
 for(int x=0;x<=n;x++)printf("%d ",max(dp[n][x],0));puts("");}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;const ll MOD=1e9+7;
int main(){int n,k;string s;cin>>n>>k>>s;
 vector<ll>F(n+1),IF(n+1),p10(n+1);F[0]=1;for(int i=1;i<=n;i++)F[i]=F[i-1]*i%MOD;
 auto pw=[&](ll b,ll e){ll r=1;b%=MOD;while(e){if(e&1)r=r*b%MOD;b=b*b%MOD;e>>=1;}return r;};
 IF[n]=pw(F[n],MOD-2);for(int i=n;i>0;i--)IF[i-1]=IF[i]*i%MOD;p10[0]=1;for(int i=1;i<=n;i++)p10[i]=p10[i-1]*10%MOD;
 auto C=[&](int a,int b)->ll{return (b<0||a<0||b>a)?0:F[a]*IF[b]%MOD*IF[a-b]%MOD;};
 // S[x] = sum_{l=0..x} 10^l * C(n-2-l, k-1): digit with l digits after it in its number, then a plus
 vector<ll>S(n+1,0);for(int l=0;l<=n-2;l++)S[l]=((l?S[l-1]:0)+p10[l]*C(n-2-l,k-1))%MOD;
 ll ans=0;
 for(int i=0;i<n;i++){ll d=s[i]-'0';if(!d)continue;
  ll w=(n-2-i>=0?S[n-2-i]:0);                      // some plus after this digit
  w=(w+p10[n-1-i]*C(i,k))%MOD;                     // digit belongs to the last number
  ans=(ans+d*w)%MOD;}
 cout<<ans<<endl;}

#include <bits/stdc++.h>
using namespace std;
map<int,int>memo;
int grundy(int mask){ // bit e-1 set <=> some number has exponent e of this prime
 if(mask==0)return 0;auto it=memo.find(mask);if(it!=memo.end())return it->second;
 set<int>s;int hi=32-__builtin_clz(mask);
 for(int k=1;k<=hi;k++){int nm=(mask&((1<<(k-1))-1))|(mask>>k);s.insert(grundy(nm));} // exponents >= k drop by k
 int g=0;while(s.count(g))g++;return memo[mask]=g;}
int main(){int n;cin>>n;map<int,int>pm;
 for(int i=0;i<n;i++){int x;cin>>x;for(int p=2;(long long)p*p<=x;p++)if(x%p==0){int e=0;while(x%p==0){x/=p;e++;}pm[p]|=1<<(e-1);}
  if(x>1)pm[x]|=1;}
 int g=0;for(auto&[p,m]:pm)g^=grundy(m);cout<<(g?"Mojtaba":"Arpa")<<endl;}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;const ll MOD=1e9+7;
ll pw(ll b,ll e){ll r=1;b%=MOD;while(e){if(e&1)r=r*b%MOD;b=b*b%MOD;e>>=1;}return r;}
int main(){int t;scanf("%d",&t);while(t--){int n;ll x;scanf("%d %lld",&n,&x);
 vector<ll>f;ll add=0; // f: multiplicative factors (y or 1/y); add: signed sum of +/- values
 for(int i=0;i<n;i++){char s[20];scanf("%s",s);ll y=atoll(s+1)%MOD;
  if(s[0]=='+')add=(add+y)%MOD;else if(s[0]=='-')add=(add-y+MOD)%MOD;
  else if(s[0]=='x')f.push_back(y);else f.push_back(pw(y,MOD-2));}
 int K=f.size();vector<ll>e(K+1,0);e[0]=1; // elementary symmetric polynomials
 for(ll v:f)for(int s=K;s>=1;s--)e[s]=(e[s]+e[s-1]*v)%MOD;
 vector<ll>fact(K+1,1),inv(K+1,1);for(int i=1;i<=K;i++)fact[i]=fact[i-1]*i%MOD;
 inv[K]=pw(fact[K],MOD-2);for(int i=K;i>0;i--)inv[i-1]=inv[i]*i%MOD;
 // an additive op sees a uniformly random subset of size s (s uniform in 0..K) of factors after it
 ll E=0;for(int s=0;s<=K;s++)E=(E+e[s]*inv[K]%MOD*fact[s]%MOD*fact[K-s])%MOD; // e_s / C(K,s)
 E=E*pw(K+1,MOD-2)%MOD;
 printf("%lld\n",(x%MOD*e[K]%MOD+add*E)%MOD);}}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int n,m,T;vector<vector<pair<int,int>>>g;vector<int>tin,low,sub,comp;vector<vector<int>>cuts;
void dfs(int v,int pe,int c){tin[v]=low[v]=++T;sub[v]=1;comp[v]=c;
 for(auto[u,e]:g[v])if(e!=pe){if(tin[u])low[v]=min(low[v],tin[u]);else{dfs(u,e,c);sub[v]+=sub[u];low[v]=min(low[v],low[u]);
   if(low[u]>tin[v])cuts[c].push_back(sub[u]);}}} // bridge: the side of u has sub[u] vertices
int main(){int t;scanf("%d",&t);while(t--){ll c;scanf("%d %d %lld",&n,&m,&c);g.assign(n+1,{});
 for(int i=0;i<m;i++){int u,v;scanf("%d %d",&u,&v);g[u].push_back({v,i});g[v].push_back({u,i});}
 tin.assign(n+1,0);low=sub=comp=tin;cuts.assign(n+1,{});T=0;vector<int>sz;
 for(int v=1;v<=n;v++)if(!tin[v]){int st=T;dfs(v,-1,sz.size());sz.push_back(T-st);}
 int k=sz.size();vector<char>d0(n+1,0),d1(n+1,0);d0[0]=1; // d1: one component is split by a bridge
 for(int i=0;i<k;i++){vector<char>e0(n+1,0),e1(n+1,0);
  for(int s=0;s<=n;s++){if(d0[s]){e0[s]=1;if(s+sz[i]<=n)e0[s+sz[i]]=1;for(int b:cuts[i]){e1[s+b]=1;e1[s+sz[i]-b]=1;}}
   if(d1[s]){e1[s]=1;if(s+sz[i]<=n)e1[s+sz[i]]=1;}}
  d0=e0;d1=e1;}
 ll best=-1;for(int x=1;x<n;x++)if((k>=2&&d0[x])||d1[x]){ll v=(ll)x*x+(ll)(n-x)*(n-x)+c*(k-1);if(best<0||v<best)best=v;}
 printf("%lld\n",best);}}

