int main(){int xs,ys,n;scanf("%d %d %d",&xs,&ys,&n);vector<int>x(n),y(n);for(int i=0;i<n;i++)scanf("%d %d",&x[i],&y[i]);
 vector<int>d0(n);vector<vector<int>>d(n,vector<int>(n));
 for(int i=0;i<n;i++){d0[i]=(x[i]-xs)*(x[i]-xs)+(y[i]-ys)*(y[i]-ys);for(int j=0;j<n;j++)d[i][j]=(x[i]-x[j])*(x[i]-x[j])+(y[i]-y[j])*(y[i]-y[j]);}
 int F=1<<n;vector<int>dp(F,INT_MAX),par(F,0);dp[0]=0;
 for(int m=0;m<F-1;m++){if(dp[m]==INT_MAX)continue;int i=__builtin_ctz(~m); // lowest unpicked object must be in the next trip
  int nm=m|1<<i,c=dp[m]+2*d0[i];if(c<dp[nm]){dp[nm]=c;par[nm]=m;}
  for(int j=i+1;j<n;j++)if(!(m>>j&1)){int mm=nm|1<<j,cc=dp[m]+d0[i]+d[i][j]+d0[j];if(cc<dp[mm]){dp[mm]=cc;par[mm]=m;}}}
 printf("%d\n0",dp[F-1]);vector<int>path;
 for(int m=F-1;m;m=par[m]){int diff=m^par[m];vector<int>t;for(int i=0;i<n;i++)if(diff>>i&1)t.push_back(i+1);path.insert(path.begin(),0);path.insert(path.begin(),t.begin(),t.end());}
 for(int v:path)printf(" %d",v);puts("");}

