const long long M=1e9+7;
long long pw(long long b,long long e){long long r=1;b%=M;while(e){if(e&1)r=r*b%M;b=b*b%M;e>>=1;}return r;}
int main(){int t;scanf("%d",&t);long long i4=pw(10000,M-2);while(t--){int n;scanf("%d",&n);
 vector<int>a(n);vector<long long>p(n);for(auto&x:a)scanf("%d",&x);for(auto&x:p){scanf("%lld",&x);x=x*i4%M;}
 long long ans=0;
 for(int i=0;i<10;i++)for(int j=0;j<10;j++){long long dp[4]={1,0,0,0};
  for(int e=0;e<n;e++){int v=((a[e]>>i)&1)|(((a[e]>>j)&1)<<1);if(!v)continue;long long nd[4];
   for(int s=0;s<4;s++)nd[s]=(dp[s]*(1-p[e]+M)+dp[s^v]*p[e])%M;memcpy(dp,nd,sizeof dp);}
  ans=(ans+dp[3]*((1LL<<(i+j))%M))%M;}
 printf("%lld\n",ans);}}

