#include <bits/stdc++.h>
using namespace std;
int main(){int t;scanf("%d",&t);while(t--){int n,k;static char buf[3005];scanf("%d %d %s",&n,&k,buf);string s(buf);
  // pre[i][j]: longest run of '1' within s[0..i) using <= j flips; suf[i][j]: within s[i..n)
  vector<vector<int>>pre(n+1,vector<int>(k+1,0)),suf(n+2,vector<int>(k+1,0));
  for(int j=0;j<=k;j++){int l=0,z=0;for(int i=0;i<n;i++){z+=s[i]=='0';while(z>j)z-=s[l++]=='0';pre[i+1][j]=max(pre[i][j],i-l+1);}
    int r=n-1;z=0;for(int i=n-1;i>=0;i--){z+=s[i]=='0';while(z>j)z-=s[r--]=='0';suf[i][j]=max(suf[i+1][j],r-i+1);}}
  vector<int>best(n+1,-1);best[0]=pre[n][k];
  for(int l=0;l<n;l++){int c=0;for(int r=l;r<n;r++){c+=s[r]=='1';if(c>k)break;int rem=k-c;
      best[r-l+1]=max(best[r-l+1],max(pre[l][rem],suf[r+1][rem]));}}
  for(int a=1;a<=n;a++){long long ans=0;for(int L=0;L<=n;L++)if(best[L]>=0)ans=max(ans,(long long)a*L+best[L]);printf("%lld ",ans);}puts("");}}

