#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
// best[i] = max total health kept by a chain that ends exploding at i going outward one side
vector<ll> side(const vector<ll>&h){int n=h.size();vector<ll>L(n);vector<int>st;
 for(int i=0;i<n;i++){while(!st.empty()&&h[st.back()]-st.back()>h[i]-i)st.pop_back();
  ll j=st.empty()?-1:st.back();ll len=i-j;
  if(len>h[i]||j<0&&len>=h[i]){ll k=min<ll>(len,h[i]);L[i]=k*(2*h[i]-k+1)/2;} // chain dies out before j
  else L[i]=(j>=0?L[j]:0)+len*(2*h[i]-len+1)/2;
  st.push_back(i);}return L;}
int main(){int t;scanf("%d",&t);while(t--){int n;scanf("%d",&n);vector<ll>h(n);ll S=0;for(auto&x:h){scanf("%lld",&x);S+=x;}
 vector<ll>L=side(h);vector<ll>r(h.rbegin(),h.rend());vector<ll>R=side(r);reverse(R.begin(),R.end());
 ll ans=LLONG_MAX;for(int i=0;i<n;i++)ans=min(ans,S-(L[i]+R[i]-h[i])+h[i]);printf("%lld\n",ans);}}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
unsigned long long W[11][62][1024]; // W[b][len][mask]: digit strings of length len whose digit-parity mask is mask
ll cnt(int b,ll N){ // magic numbers in [1, N]
 if(N<=0)return 0;vector<int>d;for(ll x=N;x;x/=b)d.push_back(x%b);reverse(d.begin(),d.end());int L=d.size();ll r=0;
 for(int len=1;len<L;len++)for(int f=1;f<b;f++)r+=W[b][len-1][1<<f]; // shorter numbers, leading digit f
 int mask=0;
 for(int i=0;i<L;i++){for(int x=(i==0?1:0);x<d[i];x++)r+=W[b][L-1-i][mask^(1<<x)]; // rest must cancel the mask
  mask^=1<<d[i];}
 if(mask==0)r++;return r;}
int main(){for(int b=2;b<=10;b++){W[b][0][0]=1;for(int l=1;l<62;l++)for(int m=0;m<(1<<b);m++)for(int x=0;x<b;x++)W[b][l][m]+=W[b][l-1][m^(1<<x)];}
 int q;scanf("%d",&q);while(q--){int b;ll l,r;scanf("%d %lld %lld",&b,&l,&r);printf("%lld\n",cnt(b,r)-cnt(b,l-1));}}

#include <bits/stdc++.h>
using namespace std;
typedef pair<int,int> P; // (steps, replacements)
int main(){int n;cin>>n;int N=n*n,V=3*N;vector<int> pr(N+1),pc(N+1);
 for(int i=0;i<n;i++)for(int j=0;j<n;j++){int x;cin>>x;pr[x]=i;pc[x]=j;}
 const P INF={1e9,1e9};vector<vector<P>> d(V,vector<P>(V,INF));
 auto id=[&](int r,int c,int p){return (r*n+c)*3+p;};
 for(int r=0;r<n;r++)for(int c=0;c<n;c++)for(int p=0;p<3;p++){
  int u=id(r,c,p);d[u][u]={0,0};
  for(int q=0;q<3;q++)if(q!=p)d[u][id(r,c,q)]={1,1};
  for(int r2=0;r2<n;r2++)for(int c2=0;c2<n;c2++){
   if(r2==r&&c2==c)continue;int dr=abs(r2-r),dc=abs(c2-c);bool ok=false;
   if(p==0)ok=(dr==1&&dc==2)||(dr==2&&dc==1);      // knight
   if(p==1)ok=(dr==dc);                            // bishop
   if(p==2)ok=(dr==0||dc==0);                      // rook
   if(ok)d[u][id(r2,c2,p)]=min(d[u][id(r2,c2,p)],P{1,0});}}
 for(int k=0;k<V;k++)for(int i=0;i<V;i++)if(d[i][k]!=INF)for(int j=0;j<V;j++)if(d[k][j]!=INF){
  P t={d[i][k].first+d[k][j].first,d[i][k].second+d[k][j].second};if(t<d[i][j])d[i][j]=t;}
 vector<P> dp(3,P{0,0});
 for(int x=1;x<N;x++){vector<P> nd(3,INF);
  for(int a=0;a<3;a++)for(int b=0;b<3;b++){P e=d[id(pr[x],pc[x],a)][id(pr[x+1],pc[x+1],b)];
   P t={dp[a].first+e.first,dp[a].second+e.second};nd[b]=min(nd[b],t);}dp=nd;}
 P best=*min_element(dp.begin(),dp.end());cout<<best.first<<" "<<best.second<<"\n";}

