typedef long long ll;
int main(){
    int t; scanf("%d",&t);
    while(t--){
        int n; ll h; scanf("%d %lld",&n,&h);
        vector<ll> a(n+1); for(int i=1;i<=n;i++) scanf("%lld",&a[i]);
        vector<vector<ll>> P(n+1, vector<ll>(n+1,0));
        for(int i=1;i<=n;i++){
            vector<ll> M(n+1); ll mx=a[i];
            for(int j=i;j>=1;j--){ mx=max(mx,a[j]); M[j]=mx; }
            mx=a[i];
            for(int j=i;j<=n;j++){ mx=max(mx,a[j]); M[j]=mx; }
            for(int j=1;j<=n;j++) P[i][j]=P[i][j-1]+M[j];
        }
        ll tot=(ll)n*h, ans=0;
        for(int i=1;i<=n;i++){
            ans=max(ans,tot-P[i][n]);
            int q=i;
            for(int k=i+1;k<=n;k++){
                if(a[k]>a[q]) q=k;
                ans=max(ans, tot-(P[i][q]+P[k][n]-P[k][q]));
            }
        }
        printf("%lld\n",ans);
    }
}

