const long long M=998244353;
int main(){int t;scanf("%d",&t);while(t--){int n,m,d;scanf("%d %d %d",&n,&m,&d);vector<string>g(n);static char buf[2005];
 for(auto&s:g){scanf("%s",buf);s=buf;}
 vector<long long>tot(m,0),f1(m),P(m+1);
 auto pre=[&](const vector<long long>&v){P[0]=0;for(int i=0;i<m;i++)P[i+1]=(P[i]+v[i])%M;};
 auto rs=[&](int l,int r){l=max(l,0);r=min(r,m-1);return (P[r+1]-P[l]+M)%M;};
 for(int r=n-1;r>=0;r--){
  if(r==n-1){for(int c=0;c<m;c++)f1[c]=g[r][c]=='X';}
  else{pre(tot);for(int c=0;c<m;c++)f1[c]=g[r][c]=='X'?rs(c-(d-1),c+(d-1)):0;}
  pre(f1);for(int c=0;c<m;c++)tot[c]=g[r][c]=='X'?rs(c-d,c+d):0;}
 long long ans=0;for(int c=0;c<m;c++)ans=(ans+tot[c])%M;printf("%lld\n",ans);}}

