int main(){int t;scanf("%d",&t);while(t--){int n;ll m;scanf("%d %lld",&n,&m);vector<int>U(n),V(n);int K=0,maxU=0;
 for(int i=0;i<n;i++){int l;scanf("%d",&l);vector<int>a(l);for(auto&x:a)scanf("%d",&x);vector<char>h(l+3,0);for(int x:a)if(x<=l+2)h[x]=1;
  int u=0;while(h[u])u++;int v=u+1;while(h[v])v++;U[i]=u;V[i]=v;K=max(K,v);maxU=max(maxU,u);}
 vector<vector<int>>g(K+1);vector<int>outd(K+1,0);for(int i=0;i<n;i++){g[U[i]].push_back(V[i]);outd[U[i]]++;}
 vector<int>f(K+1);for(int x=K;x>=0;x--){f[x]=x;for(int y:g[x])f[x]=max(f[x],f[y]);}
 int base=maxU;for(int x=0;x<=K;x++)if(outd[x]>1)base=max(base,f[x]);
 ll ans=0;for(ll x=0;x<=min<ll>(m,K);x++)ans+=max<ll>(base,f[x]);
