#include <bits/stdc++.h>
using namespace std;
typedef unsigned long long ull;
int main(){int t;scanf("%d",&t);while(t--){int n,m;scanf("%d %d",&n,&m);vector<vector<int>>g(n+1);
 for(int i=0;i<m;i++){int u,v;scanf("%d %d",&u,&v);g[u].push_back(v);g[v].push_back(u);}
 int f;scanf("%d",&f);vector<int>h(f);for(auto&x:h)scanf("%d",&x);int k;scanf("%d",&k);vector<int>p(k);vector<char>noCar(f,0);
 vector<int>own(n+1,0);for(int i=0;i<k;i++){scanf("%d",&p[i]);p[i]--;noCar[p[i]]=1;own[h[p[i]]]|=1<<i;}
 vector<int>d(n+1,-1),ord;d[1]=0;ord.push_back(1);for(size_t i=0;i<ord.size();i++)for(int u:g[ord[i]])if(d[u]<0){d[u]=d[ord[i]]+1;ord.push_back(u);}
 // reach[v]: bitset over masks (64) of carless friends collectable on some shortest path 1 -> v
 vector<ull>reach(n+1,0);reach[1]=1ULL<<own[1];
 for(int v:ord){if(v==1)continue;ull acc=0;for(int u:g[v])if(d[u]==d[v]-1)acc|=reach[u];
  ull r=0;for(int ms=0;ms<64;ms++)if(acc>>ms&1)r|=1ULL<<(ms|own[v]);reach[v]=r;}
 ull dp=1; // achievable unions of carried friends
 for(int i=0;i<f;i++){if(noCar[i])continue;ull r=reach[h[i]],nd=dp;
  for(int a=0;a<64;a++)if(dp>>a&1)for(int b=0;b<64;b++)if(r>>b&1)nd|=1ULL<<(a|b);dp=nd;}
 int best=0;for(int ms=0;ms<64;ms++)if(dp>>ms&1)best=max(best,__builtin_popcount(ms));
 printf("%d\n",k-best);}}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
// x_u reachable = a_u + <child sums> mod b_u; g_u = gcd(b_u, s0, D), s0 = sum of the children's a, D = gcd of the children's step sizes
int main(){int t;scanf("%d",&t);while(t--){int n;scanf("%d",&n);vector<ll>a(n+1),b(n+1);for(int i=1;i<=n;i++)scanf("%lld",&a[i]);for(int i=1;i<=n;i++)scanf("%lld",&b[i]);
 vector<vector<int>>g(n+1);for(int i=0;i<n-1;i++){int u,v;scanf("%d %d",&u,&v);g[u].push_back(v);g[v].push_back(u);}
 vector<int>ord,par(n+1,0);ord.reserve(n);vector<int>st={1};par[1]=-1;
 while(!st.empty()){int v=st.back();st.pop_back();ord.push_back(v);for(int u:g[v])if(u!=par[v]){par[u]=v;st.push_back(u);}}
 vector<ll>s0(n+1,0),D(n+1,0),step(n+1,0);ll ans=0;
 for(int k=n-1;k>=0;k--){int v=ord[k];ll gg=__gcd(b[v],__gcd(s0[v],D[v])); // gcd(x,0)=x
  ans+=a[v]%gg+b[v]-gg;step[v]=(gg==b[v])?0:gg; // step 0: a single reachable value
  if(par[v]>0){s0[par[v]]+=a[v];D[par[v]]=__gcd(D[par[v]],step[v]);}}
 printf("%lld\n",ans);}}

