typedef long long ll;int n,K;vector<int>h;
vector<ll> solve(int l,int r){ // the strings sorted[l..r]; h[i] = lcp(s_i, s_{i+1})
 if(l==r)return {0,0};int p=l;for(int i=l;i<r;i++)if(h[i]<h[p])p=i;
 auto A=solve(l,p),B=solve(p+1,r);int sz=min<int>(K,r-l+1);vector<ll>C(sz+1,LLONG_MIN);
 for(int a=0;a<(int)A.size();a++)if(A[a]>LLONG_MIN)for(int b=0;b<(int)B.size()&&a+b<=sz;b++)if(B[b]>LLONG_MIN)
  C[a+b]=max(C[a+b],A[a]+B[b]+(ll)a*b*h[p]); // every cross pair has lcp = h[p] (the range minimum)
 return C;}
int main(){cin>>n>>K;vector<string>s(n);for(auto&x:s)cin>>x;sort(s.begin(),s.end());h.assign(n,0);
 for(int i=0;i+1<n;i++){int j=0;while(j<(int)s[i].size()&&j<(int)s[i+1].size()&&s[i][j]==s[i+1][j])j++;h[i]=j;}
 cout<<solve(0,n-1)[K]<<endl;}

