int main(){scanf("%d",&n);for(int i=0;i<n;i++)for(int j=0;j<n;j++)scanf("%d",&a[i][j]);
 const int NEG=INT_MIN/4;for(auto&r:dp[0])for(auto&v:r)v=NEG;dp[0][0][0]=a[0][0];
 // two walkers move together from (0,0); after s steps walker k is at row x_k, column s-x_k
 for(int s=1;s<=2*n-2;s++){int c=s&1,p=c^1;for(auto&r:dp[c])for(auto&v:r)v=NEG;
  for(int x1=max(0,s-n+1);x1<=min(n-1,s);x1++)for(int x2=x1;x2<=min(n-1,s);x2++){
   int best=NEG;for(int d1=0;d1<2;d1++)for(int d2=0;d2<2;d2++){int p1=x1-d1,p2=x2-d2;if(p1<0||p2<0)continue;int u=min(p1,p2),w=max(p1,p2);best=max(best,dp[p][u][w]);}
   if(best==NEG)continue;int y1=s-x1,y2=s-x2;dp[c][x1][x2]=best+a[x1][y1]+(x1!=x2?a[x2][y2]:0);}}
