using namespace std;typedef long long ll;typedef unsigned long long ull;
ll n,k;
ll cnt(ll y){ // number of x<=n with y in path(x)
 ll c=0,lo=y,len=(y%2?1:2);
 while(lo<=n){ll hi=lo+len-1;c+=min(hi,n)-lo+1;if(lo>n/2+1)break;lo*=2;len*=2;}
 return c;}
int main(){cin>>n>>k;ll best=1;
 for(int par=0;par<2;par++){ // search over y = 2t+par
  ll lo=(par?0:1),hi=(n-par)/2,res=-1; // y=2t+par, y>=1
  while(lo<=hi){ll md=lo+(hi-lo)/2;ll y=2*md+par;if(y>=1&&cnt(y)>=k){res=y;lo=md+1;}else hi=md-1;}
  if(res>0)best=max(best,res);}
 cout<<best<<endl;}

