  for(int j=0;j<n;j++){for(int i:st[j])pq.push({min(n-1,i+D[i]),i});ll cap=Z;
    while(!pq.empty()){auto[r,i]=pq.top();if(r<j)return false;ll t=min(cap,rem[i]);rem[i]-=t;cap-=t;
