  for(int i=0;i<n;i++){int a;scanf("%d",&a);a--;for(int j=0;j<K;j++)cnt[a][j]+=seen[j];seen[a]++;} // cnt[a][j]: j before a
  int F=1<<K;vector<ll>dp(F,LLONG_MAX);dp[0]=0;
  for(int mask=0;mask<F;mask++){if(dp[mask]==LLONG_MAX)continue;
    for(int c=0;c<K;c++)if(!(mask>>c&1)){ll add=0;for(int j=0;j<K;j++)if(mask>>j&1)add+=cnt[j][c]; // c before j pairs
      int nm=mask|1<<c;dp[nm]=min(dp[nm],dp[mask]+add);}}
  printf("%lld\n",dp[F-1]);}

