  auto id=[&](ll v){return int(lower_bound(xs.begin(),xs.end(),v)-xs.begin())+1;};
  vector<ll>dp(n+1,0);upd(id(P[0]),0); // store dp[j]-j at key P[j]
  for(int i=1;i<=n;i++){dp[i]=dp[i-1];ll b=qry(id(P[i]));if(b>LLONG_MIN/4)dp[i]=max(dp[i],b+i);upd(id(P[i]),dp[i]-i);}
