#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main(){int t;scanf("%d",&t);while(t--){int n;ll k;scanf("%d %lld",&n,&k);vector<ll>p(n),d(n);
 for(auto&x:p)scanf("%lld",&x);for(auto&x:d)scanf("%lld",&x);
 auto md=[&](ll x){x%=k;if(x<0)x+=k;return x;};
 vector<ll>A(n),B(n);for(int i=0;i<n;i++){A[i]=md(d[i]+p[i]);B[i]=md(d[i]-p[i]);}
 // state 2i = at light i turned to move left; 2i+1 = turned to move right. nxt=-1 means escape
 vector<int>nxt(2*n,-1);
 {map<ll,int>last;for(int i=0;i<n;i++){auto it=last.find(A[i]);if(it!=last.end())nxt[2*i]=2*it->second+1;last[A[i]]=i;}}
 {map<ll,int>last;for(int i=n-1;i>=0;i--){auto it=last.find(B[i]);if(it!=last.end())nxt[2*i+1]=2*it->second;last[B[i]]=i;}}
 vector<int>res(2*n,-1),col(2*n,0); // res: 1 escape, 0 loop
 for(int s=0;s<2*n;s++){if(col[s])continue;vector<int>path;int u=s;
  while(u!=-1&&col[u]==0){col[u]=1;path.push_back(u);u=nxt[u];}
  int r=(u==-1)?1:(col[u]==1?0:res[u]); // col 1 = on current path -> cycle
  for(int v:path){res[v]=r;col[v]=2;}}
 map<ll,vector<int>>byB;for(int i=0;i<n;i++)byB[B[i]].push_back(i);
 int q;scanf("%d",&q);while(q--){ll a;scanf("%lld",&a);ll c=md(-a);auto it=byB.find(c);bool esc=true;
  if(it!=byB.end()){auto&v=it->second;int lo=lower_bound(v.begin(),v.end(),0,[&](int idx,int){return p[idx]<a;})-v.begin();
   if(lo<(int)v.size())esc=res[2*v[lo]]==1;}
  puts(esc?"YES":"NO");}}}

#include <bits/stdc++.h>
using namespace std;
struct BIT{int n;vector<int>t;void init(int m){n=m;t.assign(m+1,0);}void upd(int i,int v){for(;i<=n;i+=i&-i)t[i]=max(t[i],v);}int q(int i){int r=0;for(;i>0;i-=i&-i)r=max(r,t[i]);return r;}};
// lows form a non-decreasing chain; between two lows (and before the first) one 'big' element >= next low may be inserted
int main(){int T;scanf("%d",&T);while(T--){int n;scanf("%d",&n);vector<int>a(n);for(auto&x:a)scanf("%d",&x);
 BIT b1,b2;b1.init(n);b2.init(n); // b1: dp[j]+1 at key a_j ; b2: dp[j]+2 at key a_j once some later x >= a_j exists
 vector<int>dp(n),st;int ans=0;
 for(int i=0;i<n;i++){
  int v=max({1,b1.q(a[i]),b2.q(a[i])});
  if(i>0)v=max(v,2); // leading big element: any earlier a_x (if a_x < a_i the pair is increasing anyway)
  dp[i]=v;ans=max(ans,v);
  while(!st.empty()&&a[st.back()]<=a[i]){b2.upd(a[st.back()],dp[st.back()]+2);st.pop_back();} // i = first x >= a_j after j
  st.push_back(i);b1.upd(a[i],dp[i]+1);}
 printf("%d\n",ans);}}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;const ll MOD=1e9+7,INF=LLONG_MAX/4;
typedef pair<ll,ll> P; // (min cost, ways)
P comb(P a,P b){if(a.first<b.first)return a;if(b.first<a.first)return b;return {a.first,(a.second+b.second)%MOD};}
int main(){int t;scanf("%d",&t);while(t--){int n,m;scanf("%d %d",&n,&m);vector<ll>a(n),b(m),pre(n+1,0);
 for(auto&x:a)scanf("%lld",&x);for(auto&x:b)scanf("%lld",&x);for(int i=0;i<n;i++)pre[i+1]=pre[i]+a[i];
 int sz=1;while(sz<n+1)sz<<=1;vector<P>seg(2*sz);
 auto upd=[&](int i,P v){i+=sz;seg[i]=v;for(i>>=1;i;i>>=1)seg[i]=comb(seg[2*i],seg[2*i+1]);};
 auto qry=[&](int l,int r){P res={INF,0};for(l+=sz,r+=sz+1;l<r;l>>=1,r>>=1){if(l&1)res=comb(res,seg[l++]);if(r&1)res=comb(res,seg[--r]);}return res;};
 // dp[i][k]: (cost, ways) to delete a[i..] when current index is k; process k = m..1, keep column k+1
 vector<P>nxt(n+1,{INF,0}),cur(n+1);
 for(int k=m;k>=1;k--){for(int i=0;i<2*sz;i++)seg[i]={INF,0};cur[n]={0,1};upd(n,cur[n]);int R=n;
  for(int i=n-1;i>=0;i--){while(pre[R]-pre[i]>b[k-1])R--; // largest j with sum a[i..j) <= b_k
   P best={INF,0};if(R>i){P q=qry(i+1,R);if(q.first<INF)best={q.first+(m-k),q.second};}
   if(k<m)best=comb(best,nxt[i]);                       // type 1: k -> k+1 (free)
   cur[i]=best;upd(i,best);}
  nxt=cur;}
 if(nxt[0].first>=INF)puts("-1");else printf("%lld %lld\n",nxt[0].first,nxt[0].second);}}

