 auto add=[&](int c,int i){long long nd=((2*dp-last[c])%MOD+MOD)%MOD;last[c]=dp;dp=nd;pos[c]=i;};
 int m=t.size();for(int i=0;i<m;i++)add(t[i]-'a',i);
 vector<int> ord(k);iota(ord.begin(),ord.end(),0);
 sort(ord.begin(),ord.end(),[&](int a,int b){return pos[a]<pos[b];}); // earliest last-occurrence first
