    int n,m,k; scanf("%d %d %d",&n,&m,&k);
    vector<ll> P(n+1,0);
    for(int i=1;i<=n;i++){ll x;scanf("%lld",&x);P[i]=P[i-1]+x;}
    const ll NEG=LLONG_MIN/4;
    vector<ll> prev(n+1,0),cur(n+1);
    for(int j=1;j<=k;j++){
        for(int i=0;i<=n;i++){
            cur[i]= i>0? cur[i-1]:NEG;
