  for(int v:g[u])if(v!=par[u]){ll b1=LLONG_MAX,b2=LLONG_MAX;int bc=0; // best and second best over child's rounds
   for(int c=1;c<=C;c++){if(dp[v][c]<b1){b2=b1;b1=dp[v][c];bc=c;}else if(dp[v][c]<b2)b2=dp[v][c];}
