using namespace std;
int n,q;string w;int nx[100005][26];int dp[252][252][252];string r[3];
int main(){cin>>n>>q>>w;for(int c=0;c<26;c++)nx[n][c]=nx[n+1][c]=n;
 for(int i=n-1;i>=0;i--){for(int c=0;c<26;c++)nx[i][c]=nx[i+1][c];nx[i][w[i]-'a']=i;}
 // dp[a][b][c] = min prefix length of w embedding r1[0..a), r2[0..b), r3[0..c) disjointly (n+1 = impossible)
 auto step=[&](int pos,char ch){return pos>=n?n+1:(nx[pos][ch-'a']>=n?n+1:nx[pos][ch-'a']+1);};
 dp[0][0][0]=0;
 while(q--){char op;int i;cin>>op>>i;i--;
  if(op=='+'){char c;cin>>c;r[i]+=c;int A=r[0].size(),B=r[1].size(),C=r[2].size();
   int la=i==0?A:0,lb=i==1?B:0,lc=i==2?C:0; // only states with the new index need recomputing
   for(int a=la;a<=A;a++)for(int b=lb;b<=B;b++)for(int cc=lc;cc<=C;cc++){if(!a&&!b&&!cc)continue;int v=n+1;
    if(a)v=min(v,step(dp[a-1][b][cc],r[0][a-1]));if(b)v=min(v,step(dp[a][b-1][cc],r[1][b-1]));if(cc)v=min(v,step(dp[a][b][cc-1],r[2][cc-1]));
    dp[a][b][cc]=v;}}
  else r[i].pop_back();
  puts(dp[r[0].size()][r[1].size()][r[2].size()]<=n?"YES":"NO");}}

#include <bits/stdc++.h>
using namespace std;
const int M=3000000;
int main(){int n;scanf("%d",&n);vector<long long> cnt(M+1,0);
 for(int i=0;i<n;i++){int x;scanf("%d",&x);cnt[x]++;}
 vector<long long> ex(M+1,0); // ex[v] = ordered pairs with product exactly v (v<=M)
 for(long long a=1;a<=M;a++) if(cnt[a])
  for(long long b=1;a*b<=M;b++) if(cnt[b])
   ex[a*b]+= (a==b)? cnt[a]*(cnt[a]-1) : cnt[a]*cnt[b];
 vector<long long> less_(M+2,0); // less_[p] = pairs with product < p
 for(int p=1;p<=M+1;p++) less_[p]=less_[p-1]+(p-1>=1&&p-1<=M?ex[p-1]:0);
 long long tot=(long long)n*(n-1);
 int m;scanf("%d",&m);string out;
 while(m--){int p;scanf("%d",&p);out+=to_string(tot-less_[p])+"\n";}
 fputs(out.c_str(),stdout);}

#include <bits/stdc++.h>
using namespace std;
typedef long double ld;
int main(){int n,m;cin>>n>>m;vector<int>a(m);for(auto&x:a)cin>>x;
 vector<vector<ld>>C(n+1,vector<ld>(n+1,0));for(int i=0;i<=n;i++){C[i][0]=1;for(int j=1;j<=i;j++)C[i][j]=C[i-1][j-1]+C[i-1][j];}
 auto le=[&](int T){ // probability that every room's max queue <= T
  vector<ld>dp(n+1,0);dp[0]=1;
  for(int i=0;i<m;i++){vector<ld>nd(n+1,0);for(int s=0;s<=n;s++)if(dp[s]>0)
    for(int c=0;s+c<=n&&(c+a[i]-1)/a[i]<=T;c++)nd[s+c]+=dp[s]*C[n-s][c];dp=nd;}
  return dp[n]/powl((ld)m,n);};
 ld E=0;for(int T=1;T<=n;T++)E+=1-le(T-1); // E = sum_{T>=1} P(max >= T)
 printf("%.12Lf\n",E);}

