 vector<int> P((n+1)*(m+1));
 auto ok=[&](int l){for(int i=0;i<=n;i++)for(int j=0;j<=m;j++){if(!i||!j){P[i*(m+1)+j]=0;continue;}
   P[i*(m+1)+j]=(a[(i-1)*m+j-1]>=l)+P[(i-1)*(m+1)+j]+P[i*(m+1)+j-1]-P[(i-1)*(m+1)+j-1];}
  for(int i=l;i<=n;i++)for(int j=l;j<=m;j++){int s=P[i*(m+1)+j]-P[(i-l)*(m+1)+j]-P[i*(m+1)+j-l]+P[(i-l)*(m+1)+j-l];if(s==l*l)return true;}
  return false;};
 int lo=1,hi=n,ans=1;while(lo<=hi){int md=(lo+hi)/2;if(ok(md)){ans=md;lo=md+1;}else hi=md-1;}
