 vector<vector<int>>g(n+1);for(int i=0;i<n-1;i++){int u,v;scanf("%d %d",&u,&v);g[u].push_back(v);g[v].push_back(u);}
 int st=0;for(int v=1;v<=n;v++){if(g[v].size()>2){puts("-1");return 0;}if(g[v].size()==1)st=v;}
 vector<int>ord;int prev=0,cur=st;while(cur){ord.push_back(cur);int nx=0;for(int u:g[cur])if(u!=prev)nx=u;prev=cur;cur=nx;}
 int P[3]={0,1,2};long long best=LLONG_MAX;int bp[3];
 do{long long s=0;for(int i=0;i<n;i++)s+=c[P[i%3]][ord[i]];if(s<best){best=s;copy(P,P+3,bp);}}while(next_permutation(P,P+3));
 vector<int>col(n+1);for(int i=0;i<n;i++)col[ord[i]]=bp[i%3]+1;
