int main(){int n;scanf("%d",&n);vector<long long>a(n);for(auto&x:a)scanf("%lld",&x);vector<int>L(n),R(n),st;
 for(int i=0;i<n;i++){while(!st.empty()&&a[st.back()]>=a[i])st.pop_back();L[i]=st.empty()?-1:st.back();st.push_back(i);}
 st.clear();for(int i=n-1;i>=0;i--){while(!st.empty()&&a[st.back()]>=a[i])st.pop_back();R[i]=st.empty()?n:st.back();st.push_back(i);}
 vector<long long>b(n+2,0);for(int i=0;i<n;i++){int len=R[i]-L[i]-1;b[len]=max(b[len],a[i]);}
