#include <bits/stdc++.h>
using namespace std;
int n,m;vector<int>bit;
void add(int i,int v){for(;i<=n;i+=i&-i)bit[i]+=v;}
int kth(int k){int p=0;for(int s=1<<20;s;s>>=1)if(p+s<=n&&bit[p+s]<k){p+=s;k-=bit[p];}return p+1;}
int main(){scanf("%d %d",&n,&m);vector<int>a(m);for(auto&x:a)scanf("%d",&x);bit.assign(n+1,0);vector<int>val(n+1);int len=0,tot=0;
 for(int e=0;e<n;e++){int x;scanf("%d",&x);
  if(x>=0){tot++;val[tot]=x;add(tot,1);len++;}
  else{int k=upper_bound(a.begin(),a.end(),len)-a.begin(); // a_1..a_k are <= len
   for(int i=0;i<k;i++){int p=kth(a[i]-i);add(p,-1);} // earlier removals shift later positions left by i
   len-=k;}}
 if(!len){puts("Poor stack!");return 0;}
 string out; // read the survivors in order
 for(int i=1;i<=len;i++)out+=char('0'+val[kth(i)]);puts(out.c_str());}

#include <bits/stdc++.h>
using namespace std;
const int LG=18;
int main(){int t;scanf("%d",&t);while(t--){int n;scanf("%d",&n);vector<vector<int>>g(n+1);
 for(int i=1;i<n;i++){int a,b;scanf("%d %d",&a,&b);g[a].push_back(b);g[b].push_back(a);}
 vector<int>par(n+1,0),dep(n+1,0),ord={1},h(n+1,0);
 for(size_t i=0;i<ord.size();i++){int v=ord[i];for(int u:g[v])if(u!=par[v]){par[u]=v;dep[u]=dep[v]+1;ord.push_back(u);}}
 vector<int>b1(n+1,0),b2(n+1,0),bc(n+1,0); // best and second best (1+h(child)) and which child gives best
 for(int i=n-1;i>=0;i--){int v=ord[i];h[v]=b1[v];int p=par[v];if(!p)continue;int c=1+h[v];
  if(c>b1[p]){b2[p]=b1[p];b1[p]=c;bc[p]=v;}else if(c>b2[p])b2[p]=c;}
 // val[x] = (deepest descent from parent p avoiding x's branch) - dep[p]
 vector<array<int,LG>>up(n+1),mx(n+1);
 for(int v:ord){int p=par[v];up[v][0]=p;mx[v][0]=p?((bc[p]==v?b2[p]:b1[p])-dep[p]):INT_MIN;
  for(int j=1;j<LG;j++){int m=up[v][j-1];up[v][j]=m?up[m][j-1]:0;mx[v][j]=m?max(mx[v][j-1],mx[m][j-1]):mx[v][j-1];}}
 int q;scanf("%d",&q);while(q--){int v,k;scanf("%d %d",&v,&k);k=min(k,dep[v]);int best=h[v],u=v,M=INT_MIN;
  for(int j=0;j<LG;j++)if(k>>j&1){M=max(M,mx[u][j]);u=up[u][j];}
  if(M!=INT_MIN)best=max(best,dep[v]+M);printf("%d ",best);}
 puts("");}}

#include <bits/stdc++.h>
using namespace std;
typedef unsigned long long ull;
int main(){int n,m;cin>>n>>m;map<string,int>id;vector<ull>adj(m,0);ull seg=0;
 auto flush=[&](){for(int i=0;i<m;i++)if(seg>>i&1)adj[i]|=seg&~(1ULL<<i);seg=0;}; // friends in one segment conflict
 for(int e=0;e<n;e++){int tp;cin>>tp;if(tp==1){flush();continue;}string s;cin>>s;
  if(!id.count(s)){int k=id.size();id[s]=k;}seg|=1ULL<<id[s];}
 flush();
 // maximum independent set, meet in the middle: A = first h vertices, B = rest
 int h=m/2,r=m-h;vector<int>bestB(1<<r,0);
 for(int mask=1;mask<(1<<r);mask++){int v=__builtin_ctz(mask);
  int without=bestB[mask&(mask-1)];int nb=(adj[h+v]>>h)&((1ULL<<r)-1);
  bestB[mask]=max(without,1+bestB[mask&~nb&~(1<<v)]);}
 int ans=0;
 for(int A=0;A<(1<<h);A++){bool ok=true;ull allowB=(1ULL<<r)-1;
  for(int v=0;v<h&&ok;v++)if(A>>v&1){if(adj[v]&(ull)A)ok=false;allowB&=~(adj[v]>>h);}
  if(ok)ans=max(ans,__builtin_popcount(A)+bestB[allowB]);}
 cout<<ans<<endl;}

#include <bits/stdc++.h>
using namespace std;
int main(){int n;cin>>n;vector<string>w(n);int total=-1;for(auto&s:w){cin>>s;total+=s.size()+1;}
 vector<vector<int>>lcp(n+1,vector<int>(n+1,0)); // lcp[i][j]: number of equal consecutive words from i and j
 for(int i=n-1;i>=0;i--)for(int j=n-1;j>=0;j--)lcp[i][j]=(w[i]==w[j])?lcp[i+1][j+1]+1:0;
 int best=0;
 for(int i=0;i<n;i++){int letters=0;
  for(int L=1;i+L<=n;L++){letters+=w[i+L-1].size();int cnt=1;
   for(int j=i+L;j+L<=n;)if(lcp[i][j]>=L){cnt++;j+=L;}else j++;   // greedy non-overlapping copies
   if(cnt>=2)best=max(best,cnt*(letters-1));}}                   // each copy: letters+L-1 -> L chars
 cout<<total-best<<endl;}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main(){int K,N;scanf("%d %d",&K,&N);vector<ll>t(N);for(auto&x:t)scanf("%lld",&x);sort(t.begin(),t.end());
 int G=N-1;const ll INF=1e18;vector<ll>d(G+2,INF);vector<int>L(G+2),R(G+2);vector<char>dead(G+2,0);
 for(int i=1;i<=G;i++)d[i]=t[i]-t[i-1];for(int i=0;i<=G+1;i++){L[i]=i-1;R[i]=i+1;} // 0 and G+1: INF sentinels
 priority_queue<pair<ll,int>,vector<pair<ll,int>>,greater<>>pq;for(int i=1;i<=G;i++)pq.push({d[i],i});
 ll ans=0;
 for(int k=0;k<K;k++){ // choose K non-adjacent gaps of minimum sum: regret greedy
  while(dead[pq.top().second]||pq.top().first!=d[pq.top().second])pq.pop();
  auto[v,i]=pq.top();pq.pop();ans+=v;int a=L[i],b=R[i];
  d[i]=(d[a]>=INF||d[b]>=INF)?INF:d[a]+d[b]-d[i]; // undo option: take both neighbours instead
  if(a>=1){dead[a]=1;L[i]=L[a];if(L[a]>=0)R[L[a]]=i;}else d[i]=INF;
  if(b<=G){dead[b]=1;R[i]=R[b];if(R[b]<=G+1)L[R[b]]=i;}else d[i]=INF;
  if(d[i]<INF)pq.push({d[i],i});}
 printf("%lld\n",ans);}

