 // ok[i][c]: digits i.. can be produced with incoming carry c; ch = the chosen (#4, #7)
 vector<array<char,5>>ok(L+1);vector<array<pair<int,int>,5>>ch(L);for(int c=0;c<5;c++)ok[L][c]=(c==0);
 for(int i=L-1;i>=0;i--)for(int c=0;c<5;c++){ok[i][c]=0;
  for(int f=0;f<=6&&!ok[i][c];f++)for(int s=0;f+s<=6;s++){int tot=4*f+7*s+c;if(tot%10==d[i]&&ok[i+1][tot/10]){ok[i][c]=1;ch[i][c]={f,s};break;}}}
 if(!ok[0][0]){puts("-1");continue;}
 ll num[6]={0},p=1;int c=0;
 for(int i=0;i<L;i++,p*=10){auto[f,s]=ch[i][c];for(int j=0;j<6;j++)num[j]+=p*(j<f?4:(j<f+s?7:0));c=(4*f+7*s+c)/10;}
 for(int j=0;j<6;j++)printf("%lld ",num[j]);puts("");}}

