long long C[20][20],P9[20];
long long fr(int L,int k){long long s=0;for(int j=0;j<=k&&j<=L;j++)s+=C[L][j]*P9[j];return s;}
long long cnt(long long X){if(X<0)return 0;string s=to_string(X);int n=s.size(),used=0;long long r=0;
 for(int i=0;i<n;i++){int d=s[i]-'0',L=n-i-1;if(!d)continue;r+=fr(L,3-used);if(3-used-1>=0)r+=(d-1)*fr(L,3-used-1);used++;if(used>3)return r;}
 return r+1;}
