 int T;scanf("%d",&T);while(T--){long long L,R;scanf("%lld %lld",&L,&R);printf("%lld\n",cnt(R)-cnt(L-1));}}

#include <bits/stdc++.h>
using namespace std;
int n,m;long long k;vector<long long>a;vector<vector<int>>g;
bool ok(long long X){vector<int>in(n,0),len(n,1);int cnt=0,tot=0;
 for(int u=0;u<n;u++)if(a[u]<=X){tot++;for(int v:g[u])if(a[v]<=X)in[v]++;}
 queue<int>q;for(int u=0;u<n;u++)if(a[u]<=X&&!in[u])q.push(u);long long best=0;
 while(!q.empty()){int u=q.front();q.pop();cnt++;best=max(best,(long long)len[u]);
  for(int v:g[u])if(a[v]<=X){len[v]=max(len[v],len[u]+1);if(--in[v]==0)q.push(v);}}
 if(cnt<tot)return true;return best>=k;}
