const long long M=1e9+7;
int main(){int n;scanf("%d",&n);vector<int>p(n,-1);for(int i=1;i<n;i++)scanf("%d",&p[i]);
 vector<long long>d0(n),d1(n);for(int i=0;i<n;i++){int x;scanf("%d",&x);d1[i]=x;d0[i]=1-x;}
 for(int v=n-1;v>=1;v--){int u=p[v];long long c0=d0[v],c1=d1[v]; // p[v]<v, so children processed first
  long long n1=(d1[u]*(c0+c1)+d0[u]*c1)%M,n0=d0[u]*(c0+c1)%M; // cut edge only if child part has 1 black
