#include <bits/stdc++.h>
using namespace std;
int main(){int t;scanf("%d",&t);while(t--){int n,m;long long k;scanf("%d %d %lld",&n,&m,&k);
 vector<long long>a(n);for(auto&x:a)scanf("%lld",&x);vector<int>b(m);for(auto&x:b)scanf("%d",&x);
 vector<int>am(1<<m);am[0]=(1<<30)-1;for(int s=1;s<(1<<m);s++){int j=__builtin_ctz(s);am[s]=am[s&(s-1)]&b[j];}
 vector<long long>g;g.reserve((size_t)n*m);long long sum=0;
 for(int i=0;i<n;i++){vector<long long>best(m+1,LLONG_MAX);
  for(int s=0;s<(1<<m);s++){int c=__builtin_popcount(s);best[c]=min(best[c],a[i]&am[s]);}
  sum+=a[i];for(int c=1;c<=m;c++)g.push_back(best[c-1]-best[c]);}
 // gains per element are non-increasing (convex), so greedy top-k is valid
 sort(g.rbegin(),g.rend());for(long long i=0;i<k&&i<(long long)g.size();i++)sum-=g[i];
 printf("%lld\n",sum);}}

#include <bits/stdc++.h>
