int main(){int n;scanf("%d",&n);vector<int>a(n+1);for(int i=1;i<=n;i++)scanf("%d",&a[i]);vector<vector<int>>g(n+1);
 for(int i=0;i<n-1;i++){int u,v;scanf("%d %d",&u,&v);g[u].push_back(v);g[v].push_back(u);}
 vector<int>ord={1},par(n+1,0);par[1]=-1;for(int i=0;i<(int)ord.size();i++)for(int w:g[ord[i]])if(w!=par[ord[i]]){par[w]=ord[i];ord.push_back(w);}
 ll total=0;vector<array<ll,2>>dp(n+1);
 for(int b=0;b<20;b++){ll cnt=0;for(int v=1;v<=n;v++){int bv=a[v]>>b&1;dp[v]={0,0};dp[v][bv]=1;cnt+=bv;}
  for(int i=n-1;i>=0;i--){int v=ord[i];int p=par[v];if(p<=0)continue; // merge v into p
   int bp=a[p]>>b&1;cnt+=dp[p][0]*dp[v][1]+dp[p][1]*dp[v][0];dp[p][0^bp]+=dp[v][0];dp[p][1^bp]+=dp[v][1];}
  total+=cnt<<b;}
 printf("%lld\n",total);}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main(){int t;scanf("%d",&t);const int K=12; // candidates L_i*t, t=1..K (heuristic bound)
 while(t--){int n;scanf("%d",&n);vector<ll>a(n),b(n);for(auto&x:a)scanf("%lld",&x);for(auto&x:b)scanf("%lld",&x);
 vector<ll>g(n-1);for(int i=0;i+1<n;i++)g[i]=__gcd(a[i],a[i+1]);
 // condition <=> gcd(a'_i,a'_{i+1}) == g_i for all adjacent pairs
 vector<vector<pair<ll,int>>>cand(n);
 for(int i=0;i<n;i++){ll L=1;if(i>0)L=L/__gcd(L,g[i-1])*g[i-1];if(i+1<n)L=L/__gcd(L,g[i])*g[i];
  cand[i].push_back({a[i],0});for(int k=1;k<=K&&L*k<=b[i];k++)if(L*k!=a[i])cand[i].push_back({L*k,1});}
 vector<int>dp(cand[0].size());for(size_t c=0;c<cand[0].size();c++)dp[c]=cand[0][c].second;
 for(int i=1;i<n;i++){vector<int>nd(cand[i].size(),INT_MIN);
  for(size_t c=0;c<cand[i].size();c++)for(size_t p=0;p<cand[i-1].size();p++)
   if(dp[p]>INT_MIN&&__gcd(cand[i-1][p].first,cand[i][c].first)==g[i-1])nd[c]=max(nd[c],dp[p]+cand[i][c].second);
  dp=nd;}
 printf("%d\n",*max_element(dp.begin(),dp.end()));}}

#include <bits/stdc++.h>
using namespace std;
int main(){int n,m;cin>>n>>m;if(n<m)swap(n,m); // m = width <= 6
  int F=1<<m,full=F-1;const int INF=1e9;
  auto cov=[&](int b){return (b|(b<<1)|(b>>1))&full;};
  // dp[a][b]: a = chosen mask of row i-1, b = chosen mask of row i; rows < i all covered
  vector<vector<int>>dp(F,vector<int>(F,INF)),nd;
  for(int b=0;b<F;b++)dp[0][b]=__builtin_popcount(b);
  for(int i=1;i<n;i++){nd.assign(F,vector<int>(F,INF));
    for(int a=0;a<F;a++)for(int b=0;b<F;b++)if(dp[a][b]<INF)for(int c=0;c<F;c++)
      if((a|cov(b)|c)==full)nd[b][c]=min(nd[b][c],dp[a][b]+__builtin_popcount(c));
    dp=nd;}
  int best=INF;for(int a=0;a<F;a++)for(int b=0;b<F;b++)if((a|cov(b))==full)best=min(best,dp[a][b]);
  cout<<n*m-best<<endl;}

