int main(){scanf("%d",&n);g.resize(n+1);for(int i=0;i<n-1;i++){int a,b;scanf("%d %d",&a,&b);g[a].push_back({b,0});g[b].push_back({a,1});}
  int ans=n;vector<int>par(n+1),cost(n+1),best(n+1),ord;
  for(int r=1;r<=n;r++){ord={r};par[r]=0;best[r]=0;int tot=0,gain=0;
    for(size_t i=0;i<ord.size();i++){int u=ord[i];for(auto[v,w]:g[u])if(v!=par[u]){par[v]=u;ord.push_back(v);
        tot+=w; // w=1: edge points toward root, must reverse
        best[v]=max(0,best[u])+(w?1:-1);gain=max(gain,best[v]);}}
    ans=min(ans,tot-gain);}
  printf("%d\n",ans);}

