const int N=300005,LG=19;int up[LG][N];ll a[N],c[N];
int main(){int q;scanf("%d %lld %lld",&q,&a[0],&c[0]);for(int k=0;k<LG;k++)up[k][0]=0;
  for(int i=1;i<=q;i++){int ty;scanf("%d",&ty);
    if(ty==1){int p;scanf("%d %lld %lld",&p,&a[i],&c[i]);up[0][i]=p;for(int k=1;k<LG;k++)up[k][i]=up[k-1][up[k-1][i]];}
    else{int v;ll w;scanf("%d %lld",&v,&w);ll got=0,cost=0;
      while(w>0&&a[v]>0){int u=v;for(int k=LG-1;k>=0;k--)if(a[up[k][u]]>0)u=up[k][u]; // topmost non-empty ancestor
        ll take=min(w,a[u]);a[u]-=take;w-=take;got+=take;cost+=take*c[u];}
      printf("%lld %lld\n",got,cost);fflush(stdout);}}}

