using namespace std;
const int MX=100000,B=17;
vector<array<int,2>>ch;vector<int>mn;int root[MX+1];bool in_[MX+1];vector<int>divs[MX+1];
int nn(){ch.push_back({0,0});mn.push_back(INT_MAX);return ch.size()-1;}
void ins(int r,int v){int u=r;mn[u]=min(mn[u],v);for(int b=B-1;b>=0;b--){int c=v>>b&1;if(!ch[u][c]){int t=nn();ch[u][c]=t;}u=ch[u][c];mn[u]=min(mn[u],v);}}
int main(){for(int d=1;d<=MX;d++)for(int m=d;m<=MX;m+=d)divs[m].push_back(d);
 ch.reserve(1<<22);mn.reserve(1<<22);nn();
 int q;scanf("%d",&q);while(q--){int t;scanf("%d",&t);
  if(t==1){int u;scanf("%d",&u);if(in_[u])continue;in_[u]=1;
   for(int d:divs[u]){if(!root[d])root[d]=nn();ins(root[d],u);}}  // trie per divisor, subtree minimum
  else{int x,k,s;scanf("%d %d %d",&x,&k,&s);int lim=s-x;
   if(x%k||!root[k]||mn[root[k]]>lim){puts("-1");continue;}
   int u=root[k],v=0;for(int b=B-1;b>=0;b--){int want=(x>>b&1)^1;int c=ch[u][want];
    if(c&&mn[c]<=lim){u=c;v|=want<<b;}else{u=ch[u][want^1];v|=(want^1)<<b;}}
   printf("%d\n",v);}}}

#include <bits/stdc++.h>
using namespace std;
const int MOD=1e9+7,V=20;
int main(){int n;string b;cin>>n>>b;
 // dp[i][mask]: ways with last cut at gap i, segment values seen = mask (values 1..20 only: 1..m must all appear)
 vector<vector<int>>dp(n+1,vector<int>(1<<V,0));long long ans=0;
 for(int i=0;i<=n;i++)dp[i][0]=1; // first cut anywhere
 for(int i=0;i<n;i++)for(int mask=0;mask<(1<<V);mask++){int cur=dp[i][mask];if(!cur)continue;
  int val=0;for(int j=i;j<n;j++){val=val*2+(b[j]-'0');if(val>V)break;if(val==0)continue;
   int nm=mask|(1<<(val-1));int&d=dp[j+1][nm];d+=cur;if(d>=MOD)d-=MOD;}}
 for(int i=1;i<=n;i++)for(int m=1;m<=V;m++)ans+=dp[i][(1<<m)-1];
 cout<<ans%MOD<<endl;}

