 for(int i=0;i<=1000;i++){Cb[i][0]=1;for(int j=1;j<=i;j++)Cb[i][j]=(Cb[i-1][j-1]+Cb[i-1][j])%M;}
 vector<int>st(1001,0);for(int c=2;c<=1000;c++)st[c]=st[__builtin_popcount(c)]+1;
 long long ans=0;
