void addRect(int r1,int r2,int c1,int c2){int m=n-k+1;r1=max(r1,1);c1=max(c1,1);r2=min(r2,m);c2=min(c2,m);
 if(r1>r2||c1>c2)return;D[r1][c1]++;D[r1][c2+1]--;D[r2+1][c1]--;D[r2+1][c2+1]++;}
