 for(int i=0;i<n;i++){int L=n,R=-1;for(int j=0;j<n;j++)if(g[i][j]=='B'){L=min(L,j);R=max(R,j);}
  if(R<0){base++;continue;} if(R-L+1<=k) addRect(i+1-k+1,i+1,R+1-k+1,L+1);}
 for(int j=0;j<n;j++){int T=n,B=-1;for(int i=0;i<n;i++)if(g[i][j]=='B'){T=min(T,i);B=max(B,i);}
  if(B<0){base++;continue;} if(B-T+1<=k) addRect(B+1-k+1,T+1,j+1-k+1,j+1);}
 int best=0;for(int i=1;i<=n-k+1;i++)for(int j=1;j<=n-k+1;j++){D[i][j]+=D[i-1][j]+D[i][j-1]-D[i-1][j-1];best=max(best,D[i][j]);}
 cout<<base+best<<endl;}

