#include <bits/stdc++.h>
using namespace std;
vector<array<int,26>> build(const string&p){int m=p.size();vector<int>f(m,0);
  for(int i=1,k=0;i<m;i++){while(k&&p[i]!=p[k])k=f[k-1];if(p[i]==p[k])k++;f[i]=k;}
  vector<array<int,26>>go(m+1);for(int s=0;s<=m;s++)for(int c=0;c<26;c++){
    if(s<m&&p[s]-'a'==c)go[s][c]=s+1;else go[s][c]=s?go[f[s-1]][c]:0;}return go;}
int main(){string c,s,t;cin>>c>>s>>t;auto A=build(s),B=build(t);int S=s.size(),T=t.size();
  const int NEG=-1e9;vector<vector<int>>dp(S+1,vector<int>(T+1,NEG)),nd;dp[0][0]=0;
  for(char ch:c){nd.assign(S+1,vector<int>(T+1,NEG));
    for(int x=0;x<=S;x++)for(int y=0;y<=T;y++)if(dp[x][y]>NEG)
      for(int l=0;l<26;l++){if(ch!='*'&&ch-'a'!=l)continue;int nx=A[x][l],ny=B[y][l];
        int v=dp[x][y]+(nx==S)-(ny==T);nd[nx][ny]=max(nd[nx][ny],v);}
    dp=nd;}
  int ans=NEG;for(auto&r:dp)for(int v:r)ans=max(ans,v);cout<<ans<<endl;}

