  if(ru==rv){cout<<(((px[u]^px[v])==w)?"YES\n":"NO\n");}
  else{par[ru]=rv;px[ru]=px[u]^px[v]^w;cout<<"YES\n";}}
 while(q--){string x,y;cin>>x>>y;int u=id[x],v=id[y];
