  vector<int>nx(n+1);nx[n]=n;long long len=0;int j=0; // line starting at i covers words [i,nx[i])
  for(int i=0;i<n;i++){if(j<i){j=i;len=0;}
    while(j<n&&len+(j>i)+(long long)w[j].size()<=c){len+=(j>i)+w[j].size();j++;}
    nx[i]=j;if(j>i)len-=w[i].size()+(j>i+1?1:0);}
  vector<int>res(n+1),base=nx;iota(res.begin(),res.end(),0);
  for(int e=r;e;e>>=1){if(e&1)for(int i=0;i<=n;i++)res[i]=base[res[i]];
    vector<int>nb(n+1);for(int i=0;i<=n;i++)nb[i]=base[base[i]];base=nb;}
  int bi=0;for(int i=0;i<n;i++)if(res[i]-i>res[bi]-bi)bi=i;
  for(int i=bi,k=0;k<r&&nx[i]>i;k++){string line;for(int q=i;q<nx[i];q++){if(q>i)line+=' ';line+=w[q];}puts(line.c_str());i=nx[i];}}

#include <bits/stdc++.h>
