int main(){int n,m;string s;cin>>n>>m>>s;vector<vector<int>>c(m,vector<int>(m,0));
  for(int i=0;i+1<n;i++){int a=s[i]-'a',b=s[i+1]-'a';if(a!=b){c[a][b]++;c[b][a]++;}}
  int F=1<<m;vector<int>cross(F,0),dp(F,INT_MAX);
  for(int mask=1;mask<F;mask++){int b=__builtin_ctz(mask),rest=mask^(1<<b);int v=cross[rest];
    for(int y=0;y<m;y++){if(y==b)continue;if(mask>>y&1)v-=c[b][y];else v+=c[b][y];}cross[mask]=v;}
  dp[0]=0;
  for(int mask=0;mask<F;mask++)if(dp[mask]<INT_MAX)for(int x=0;x<m;x++)if(!(mask>>x&1)){int nm=mask|1<<x;
      dp[nm]=min(dp[nm],dp[mask]+cross[mask]);}
  cout<<dp[F-1]<<endl;}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main(){int n,k;ll m;cin>>n>>k>>m;
 // build x from the last digit; dp[r] = #suffixes with value mod k = r and no valid y (nonzero-led, divisible by k) yet
 vector<ll>dp(k,0),nd(k);dp[0]=1;ll p10=1%k,ans=0;
 vector<ll>p10m(n+1,1%m);for(int i=1;i<=n;i++)p10m[i]=p10m[i-1]*10%m;
 for(int i=0;i<n;i++){fill(nd.begin(),nd.end(),0);bool top=(i==n-1);int rest=n-1-i;
  ll ways=top?1%m:9*p10m[rest-1]%m;
  for(int r=0;r<k;r++)if(dp[r])for(int d=(top?1:0);d<=9;d++){int nr=(r+d*p10)%k;
   if(d!=0&&nr==0)ans=(ans+dp[r]*ways)%m;  // suffix starting with d is a valid y
   else nd[nr]=(nd[nr]+dp[r])%m;}
  swap(dp,nd);p10=p10*10%k;}
 cout<<ans%m<<endl;}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main(){int t;scanf("%d",&t);static char buf[1000005];while(t--){int n,m;scanf("%d %d",&n,&m);vector<string>g(n);for(auto&s:g){scanf("%s",buf);s=buf;}
 vector<int>comp(n*m,-1);vector<ll>R(n+2,0),C(m+2,0);vector<ll>RC((n+2)*(m+2),0);auto rc=[&](int r,int c)->ll&{return RC[(r+1)*(m+2)+(c+1)];};
 vector<int>rowDot(n,0),colDot(m,0);for(int i=0;i<n;i++)for(int j=0;j<m;j++)if(g[i][j]=='.'){rowDot[i]++;colDot[j]++;}
 for(int i=0;i<n;i++)for(int j=0;j<m;j++)if(g[i][j]=='#'&&comp[i*m+j]<0){ // BFS component, bounding box
  int r1=i,r2=i,c1=j,c2=j;ll sz=0;vector<int>q={i*m+j};comp[i*m+j]=1;
  for(size_t h=0;h<q.size();h++){int x=q[h]/m,y=q[h]%m;sz++;r1=min(r1,x);r2=max(r2,x);c1=min(c1,y);c2=max(c2,y);
   int dx[4]={1,-1,0,0},dy[4]={0,0,1,-1};for(int d=0;d<4;d++){int a=x+dx[d],b=y+dy[d];if(a>=0&&b>=0&&a<n&&b<m&&g[a][b]=='#'&&comp[a*m+b]<0){comp[a*m+b]=1;q.push_back(a*m+b);}}}
  int ra=max(0,r1-1),rb=min(n-1,r2+1),ca=max(0,c1-1),cb=min(m-1,c2+1);
  R[ra]+=sz;R[rb+1]-=sz;C[ca]+=sz;C[cb+1]-=sz;             // touched by row r / column c
  rc(ra,ca)+=sz;rc(ra,cb+1)-=sz;rc(rb+1,ca)-=sz;rc(rb+1,cb+1)+=sz;} // touched by both (counted twice)
 for(int i=1;i<n;i++)R[i]+=R[i-1];for(int j=1;j<m;j++)C[j]+=C[j-1];
 for(int i=0;i<n;i++)for(int j=0;j<m;j++){ll v=rc(i,j);if(i)v+=rc(i-1,j);if(j)v+=rc(i,j-1);if(i&&j)v-=rc(i-1,j-1);rc(i,j)=v;}
 ll best=0;for(int i=0;i<n;i++)for(int j=0;j<m;j++){ll v=R[i]+C[j]-rc(i,j)+rowDot[i]+colDot[j]-(g[i][j]=='.');best=max(best,v);}
 printf("%lld\n",best);}}

