const string T="H He Li Be B C N O F Ne Na Mg Al Si P S Cl Ar K Ca Sc Ti V Cr Mn Fe Co Ni Cu Zn Ga Ge As Se Br Kr Rb Sr Y Zr Nb Mo Tc Ru Rh Pd Ag Cd In Sn Sb Te I Xe Cs Ba La Ce Pr Nd Pm Sm Eu Gd Tb Dy Ho Er Tm Yb Lu Hf Ta W Re Os Ir Pt Au Hg Tl Pb Bi Po At Rn Fr Ra Ac Th Pa U Np Pu Am Cm Bk Cf Es Fm";
int main(){map<string,int>Z;{stringstream ss(T);string s;int i=1;while(ss>>s)Z[s]=i++;}
 int n,k;cin>>n>>k;vector<string>A(n),B(k);vector<int>a(n),b(k);
 for(int i=0;i<n;i++){cin>>A[i];a[i]=Z[A[i]];}for(int j=0;j<k;j++){cin>>B[j];b[j]=Z[B[j]];}
 vector<int>pre(k+1,0);for(int j=0;j<k;j++)pre[j+1]=pre[j]+b[j];
 int F=1<<n;vector<int>sum(F,0),par(F,-1);vector<char>dp(F,0);dp[0]=1;
 for(int m=1;m<F;m++){int i=__builtin_ctz(m);sum[m]=sum[m^(1<<i)]+a[i];}
