  for(int i=0;i<n;i++)if(!(m>>i&1)&&sum[m]+a[i]<=pre[j+1]&&!dp[m|1<<i]){dp[m|1<<i]=1;par[m|1<<i]=i;}}
 if(!dp[F-1]){puts("NO");return 0;}
