int main(){int n;cin>>n;vector<long long>a(n);for(auto&x:a)cin>>x;
 vector<vector<int>>pt(n,vector<int>(n,-1)); // pt[t][j] = k with a_j + a_k = a_t (k <= j < t)
 for(int t=1;t<n;t++)for(int j=0;j<t;j++)for(int k=0;k<=j;k++)if(a[j]+a[k]==a[t])pt[t][j]=k;
 vector<char>dp(1<<n,0);dp[1]=1;int best=-1;
 for(int mask=1;mask<(1<<n);mask++)if(dp[mask]){int i=31-__builtin_clz(mask);
  if(i==n-1){int p=__builtin_popcount(mask);if(best<0||p<best)best=p;continue;}
  bool ok=false;for(int j=0;j<=i&&!ok;j++)if(mask>>j&1){int k=pt[i+1][j];if(k>=0&&(mask>>k&1))ok=true;}
  if(!ok)continue;int nb=1<<(i+1);dp[mask|nb]=1; // a new variable, or overwrite any value
  for(int j=0;j<=i;j++)if(mask>>j&1)dp[(mask^(1<<j))|nb]=1;}
 cout<<best<<endl;}

