int main(){int n;scanf("%d",&n);vector<vector<pair<int,int>>>g(n+1);vector<int>indeg(n+1,0);
 for(int i=1;i<=n;i++){int s;scanf("%d",&s);while(s--){int l,w;scanf("%d %d",&l,&w);g[i].push_back({l,w});indeg[l]++;}}
 vector<int>ord;queue<int>q;for(int i=1;i<=n;i++)if(!indeg[i])q.push(i);
 while(!q.empty()){int u=q.front();q.pop();ord.push_back(u);for(auto[v,w]:g[u])if(--indeg[v]==0)q.push(v);}
 vector<ll>c0(n+1,0),c1(n+1,0),iv(n+1,0);
 for(int k=n-1;k>=0;k--){int u=ord[k];ll z=0,o=0,I=0;
  for(auto[v,w]:g[u]){ // append [w] then seq(v)
   if(w==0){I=(I+o)%M;z=(z+1)%M;}else o=(o+1)%M;
   I=(I+iv[v]+o*c0[v])%M;z=(z+c0[v])%M;o=(o+c1[v])%M;}
  c0[u]=z;c1[u]=o;iv[u]=I;}
 printf("%lld\n",iv[1]);}

