 vector<ll>dp(n+1,0);deque<int>dq; // window minimum of the last c elements
 for(int i=1;i<=n;i++){while(!dq.empty()&&a[dq.back()]>=a[i])dq.pop_back();dq.push_back(i);if(dq.front()<=i-c)dq.pop_front();
  dp[i]=dp[i-1]+a[i];                                   // segment of length 1 (or part of a short segment)
  if(i>=c)dp[i]=min(dp[i],dp[i-c]+pre[i]-pre[i-c]-a[dq.front()]);} // segment of exactly c: drop its min
 printf("%lld\n",dp[n]);}

#include <bits/stdc++.h>
using namespace std;typedef long long ll;
int n,k;ll S;vector<ll>a,f(20,1);
void gen(int l,int r,ll sum,int used,map<ll,vector<ll>>&out,bool store,ll&total,map<ll,vector<ll>>*ref){
 if(sum>S)return;
 if(l==r){if(store){auto&v=out[sum];if(v.empty())v.assign(k+2,0);v[used]++;}
  else{auto it=ref->find(S-sum);if(it!=ref->end()&&used<=k)total+=it->second[k-used];}return;}
 gen(l+1,r,sum,used,out,store,total,ref);gen(l+1,r,sum+a[l],used,out,store,total,ref);
 if(used<k&&a[l]<=18&&f[a[l]]<=S)gen(l+1,r,sum+f[a[l]],used+1,out,store,total,ref);}
int main(){cin>>n>>k>>S;a.resize(n);for(auto&x:a)cin>>x;for(int i=1;i<20;i++)f[i]=f[i-1]*i;
 int h=n/2;map<ll,vector<ll>>L;ll tot=0;gen(0,h,0,0,L,true,tot,nullptr);
 for(auto&[s,v]:L)for(int i=1;i<=k;i++)v[i]+=v[i-1]; // prefix over sticker count
 gen(h,n,0,0,L,false,tot,&L);cout<<tot<<endl;}

