#include <bits/stdc++.h>
using namespace std;typedef long long ll;const ll M=1e9+7;const int N=200005;ll F[N],I[N];
ll pw(ll b,ll e){ll r=1;for(;e;e>>=1,b=b*b%M)if(e&1)r=r*b%M;return r;}
ll C(int n,int k){return k<0||k>n||n<0?0:F[n]*I[k]%M*I[n-k]%M;}
int main(){F[0]=1;for(int i=1;i<N;i++)F[i]=F[i-1]*i%M;I[N-1]=pw(F[N-1],M-2);for(int i=N-1;i>0;i--)I[i-1]=I[i]*i%M;
  int t;scanf("%d",&t);while(t--){int n,m1,m2;scanf("%d %d %d",&n,&m1,&m2);vector<int>p(m1),s(m2);for(auto&x:p)scanf("%d",&x);for(auto&x:s)scanf("%d",&x);
    if(p[m1-1]!=s[0]||p[0]!=1||s[m2-1]!=n){puts("0");continue;}
    ll ans=C(n-1,s[0]-1);
    for(int i=m1-2;i>=0;i--)ans=ans*C(p[i+1]-2,p[i]-1)%M*F[p[i+1]-p[i]-1]%M;
    for(int i=1;i<m2;i++)ans=ans*C(n-s[i-1]-1,n-s[i])%M*F[s[i]-s[i-1]-1]%M;
    printf("%lld\n",ans);}}

