#include <bits/stdc++.h>
using namespace std;
typedef long long ll;const ll MOD=998244353;
struct BIT{int n;vector<ll>t;void init(int m){n=m;t.assign(m+1,0);}void add(int i,ll v){for(i++;i<=n;i+=i&-i)t[i]=(t[i]+v)%MOD;}
 ll q(int i){ll s=0;for(i++;i>0;i-=i&-i)s+=t[i];return s%MOD;}ll rng(int l,int r){return l>r?0:(q(r)-q(l-1)+MOD)%MOD;}};
int main(){int T;scanf("%d",&T);static char buf[200005];while(T--){scanf("%s",buf);string s(buf);int n=s.size();
 vector<ll>p2(n+1,1);for(int i=1;i<=n;i++)p2[i]=p2[i-1]*2%MOD;
 // runs of a subsequence = 1 + #adjacent differing pairs; pair (i<j) adjacent in 2^i * 2^(n-1-j) subsequences
 BIT A[2],B[2];for(int c=0;c<2;c++){A[c].init(n);B[c].init(n);}
 for(int i=0;i<n;i++){int c=s[i]-'0';A[c].add(i,p2[i]);B[c].add(i,p2[n-1-i]);}
 auto pairsWith=[&](int p){int o=1-(s[p]-'0');return (p2[n-1-p]*A[o].rng(0,p-1)+p2[p]*B[o].rng(p+1,n-1))%MOD;};
 ll S=0;for(int j=0;j<n;j++)if(s[j]=='1')S=(S+p2[n-1-j]*A[0].rng(0,j-1))%MOD;else S=(S+p2[n-1-j]*A[1].rng(0,j-1))%MOD;
 int q;scanf("%d",&q);string out;
 while(q--){int v;scanf("%d",&v);v--;S=(S-pairsWith(v)+MOD)%MOD;int c=s[v]-'0';
  A[c].add(v,MOD-p2[v]);B[c].add(v,MOD-p2[n-1-v]);s[v]^=1;c^=1;A[c].add(v,p2[v]);B[c].add(v,p2[n-1-v]);
  S=(S+pairsWith(v))%MOD;out+=to_string((S+p2[n]-1+MOD)%MOD)+" ";}
 puts(out.c_str());}}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;const ll MOD=1e9+7;
int main(){int t;scanf("%d",&t);while(t--){int n;scanf("%d",&n);vector<int>b(n+1);bool anyK=false;for(int i=1;i<=n;i++){scanf("%d",&b[i]);if(b[i]>=0)anyK=true;}
 if(!anyK){ll r=1;for(int i=0;i<n;i++)r=r*2%MOD;printf("%lld\n",(r-1+MOD)%MOD);continue;}
 // known b_p=v: no treasure in (p-v,p+v), and a treasure at p-v or p+v
 vector<int>df(n+2,0);for(int p=1;p<=n;p++)if(b[p]>0){int L=max(1,p-b[p]+1),R=min(n,p+b[p]-1);df[L]++;df[R+1]--;}
 vector<char>forb(n+1,0),must(n+1,0),needPrev(n+1,0);int c=0;for(int i=1;i<=n;i++){c+=df[i];forb[i]=c>0;}
 bool bad=false;
 for(int p=1;p<=n&&!bad;p++){if(b[p]<0)continue;if(b[p]==0){if(forb[p])bad=true;must[p]=1;continue;}
  int L=p-b[p],R=p+b[p];bool okL=L>=1&&!forb[L],okR=R<=n&&!forb[R];
  if(!okL&&!okR)bad=true;else if(!okL)must[R]=1;else if(!okR)must[L]=1;
  else needPrev[R]=1;} // L and R are consecutive allowed positions: at least one is chosen
 if(bad){puts("0");continue;}
 ll d0=1,d1=0; // the last allowed position chosen? (start: a virtual 'not chosen')
 for(int i=1;i<=n;i++){if(forb[i])continue;ll n1=(d0+d1)%MOD,n0=needPrev[i]?d1:(d0+d1)%MOD;if(must[i])n0=0;d0=n0;d1=n1;}
 printf("%lld\n",(d0+d1)%MOD);}}

