int main(){int t;scanf("%d",&t);while(t--){int n,k;scanf("%d %d",&n,&k);vector<int>a(n);for(auto&x:a)scanf("%d",&x);vector<ll>cold(k+1),hot(k+1);
 for(int i=1;i<=k;i++)scanf("%lld",&cold[i]);for(int i=1;i<=k;i++)scanf("%lld",&hot[i]);
 const ll INF=LLONG_MAX/4;vector<ll>dp(k+1,INF);ll off=0,mn; // real value = dp[x]+off ; x = other CPU's last program (0=none)
 dp[0]=cold[a[0]];mn=dp[0];
 for(int i=1;i<n;i++){int c=a[i],p=a[i-1];
  ll cand=min(mn+off+cold[c], dp[c]<INF?dp[c]+off+hot[c]:INF); // run on other CPU
  ll c1=(c==p)?hot[c]:cold[c];off+=c1; // run on same CPU as previous
  ll cur=dp[p]<INF?dp[p]+off:INF;if(cand<cur){dp[p]=cand-off;}
  mn=min(mn,dp[p]);}
 printf("%lld\n",mn+off);}}

