int n;vector<vector<ll>>P,dp;vector<vector<int>>rt;
ll S(int r1,int r2,int c1,int c2){if(r1>r2||c1>c2)return 0;return P[r2][c2]-P[r1-1][c2]-P[r2][c1-1]+P[r1-1][c1-1];}
ll cross(int l,int r){return l>r?0:S(l,r,1,n)-S(l,r,l,r);}
vector<int>par;
void build(int l,int r,int p){if(l>r)return;int k=rt[l][r];par[k]=p;build(l,k-1,k);build(k+1,r,k);}
int main(){scanf("%d",&n);P.assign(n+1,vector<ll>(n+1,0));
  for(int i=1;i<=n;i++)for(int j=1;j<=n;j++){ll c;scanf("%lld",&c);P[i][j]=c+P[i-1][j]+P[i][j-1]-P[i-1][j-1];}
  dp.assign(n+2,vector<ll>(n+2,0));rt.assign(n+2,vector<int>(n+2,0));
  for(int len=1;len<=n;len++)for(int l=1;l+len-1<=n;l++){int r=l+len-1;ll best=LLONG_MAX;
    for(int k=l;k<=r;k++){ll v=(k>l?dp[l][k-1]:0)+(k<r?dp[k+1][r]:0)+cross(l,k-1)+cross(k+1,r);
      if(v<best){best=v;rt[l][r]=k;}}dp[l][r]=best;}
  par.assign(n+1,0);build(1,n,0);for(int i=1;i<=n;i++)printf("%d ",par[i]);puts("");}

