int main(){int N,K;string P,mk;cin>>N>>K>>P>>mk;int m=P.size();vector<int>f(m,0);
  for(int i=1,k=0;i<m;i++){while(k&&P[i]!=P[k])k=f[k-1];if(P[i]==P[k])k++;f[i]=k;}
  auto go=[&](int s,int c){if(s==m)s=f[m-1];while(s&&P[s]-'a'!=c)s=f[s-1];return P[s]-'a'==c?s+1:0;};
  // reach[i][s]: after i chars, automaton state s; par for reconstruction
  vector<vector<int>>par(N+1,vector<int>(m+1,-1)),ch(N+1,vector<int>(m+1,-1));par[0][0]=0;
  for(int i=0;i<N;i++)for(int s=0;s<=m;s++)if(par[i][s]>=0)for(int c=0;c<K;c++){int t=go(s,c);
      int st=i+1-m;if(st>=0&&((mk[st]=='1')!=(t==m)))continue;
      if(par[i+1][t]<0){par[i+1][t]=s;ch[i+1][t]=c;}}
  int s=-1;for(int t=0;t<=m;t++)if(par[N][t]>=0){s=t;break;}
  if(s<0){puts("No solution");return 0;}
  string r(N,'?');for(int i=N;i>0;i--){r[i-1]='a'+ch[i][s];s=par[i][s];}puts(r.c_str());}

