 vector<int>fail(m+1,0);for(int i=1,k=0;i<m;i++){while(k&&b[i]!=b[k])k=fail[k];if(b[i]==b[k])k++;fail[i+1]=k;}
 vector<array<int,2>>go(m+1); // KMP automaton; after a full match continue from fail[m]
 for(int s=0;s<=m;s++)for(int c=0;c<2;c++){if(s<m&&b[s]-'0'==c){go[s][c]=s+1;continue;}int k=(s==m)?fail[m]:s;
  while(k&&b[k]-'0'!=c)k=fail[k];go[s][c]=(b[k]-'0'==c&&k<m)?k+1:0;}
 int K=n-m+1;const int INF=1e9;vector<vector<int>>dp(m+1,vector<int>(K+1,INF)),nd=dp;dp[0][0]=0;
 for(int i=0;i<n;i++){for(auto&r:nd)fill(r.begin(),r.end(),INF);
  for(int s=0;s<=m;s++)for(int k=0;k<=K;k++)if(dp[s][k]<INF)for(int c=0;c<2;c++){int t=go[s][c],nk=k+(t==m);if(nk>K)continue;
   int v=dp[s][k]+(a[i]-'0'!=c);if(v<nd[t][nk])nd[t][nk]=v;}
  swap(dp,nd);}
 for(int k=0;k<=K;k++){int best=INF;for(int s=0;s<=m;s++)best=min(best,dp[s][k]);printf("%d ",best==INF?-1:best);}puts("");}

