  for(int c=0;c<n;c++){int b=0;for(int r=0;r<3;r++)if(g[r][c]!='.')b|=1<<r;vector<ll>nd(8,0);
    for(int s=0;s<8;s++)if(dp[s]&&!(s&b)){int fill=s|b; // fill rows not in fill
      function<void(int,int,int)>rec=[&](int r,int cur,int nx){if(r==3){nd[nx]=(nd[nx]+dp[s])%MOD;return;}
        if(cur>>r&1){rec(r+1,cur,nx);return;}
        if(c+1<n)rec(r+1,cur|1<<r,nx|1<<r); // horizontal
        if(r<2&&!(cur>>(r+1)&1))rec(r+2,cur|3<<r,nx);}; // vertical
      rec(0,fill,0);}
    dp=nd;}
  return dp[0];}
