  for(int r=0;r<3;r++)for(int c=0;c<n;c++)if(g[r][c]=='O'){orow=r;ocol=c;g[r][c]='X';}
  int dr[4]={0,0,1,-1},dc[4]={1,-1,0,0};ll ans=0;
  for(int S=1;S<16;S++){auto h=g;bool ok=true;
    for(int d=0;d<4;d++)if(S>>d&1){for(int t=1;t<=2;t++){int r=orow+dr[d]*t,c=ocol+dc[d]*t;
        if(r<0||r>2||c<0||c>=n||h[r][c]!='.'){ok=false;break;}h[r][c]='X';}if(!ok)break;}
    if(!ok)continue;ll t=tilings(h);ans=(ans+(__builtin_popcount(S)%2?t:MOD-t))%MOD;}
  cout<<ans<<endl;}

#include <bits/stdc++.h>
using namespace std;
int n,k;vector<int>t,lz;
void add(int x,int l,int r,int ql,int qr,int v){if(qr<l||r<ql)return;if(ql<=l&&r<=qr){t[x]+=v;lz[x]+=v;return;}
  int m=(l+r)/2;add(2*x,l,m,ql,qr,v);add(2*x+1,m+1,r,ql,qr,v);t[x]=max(t[2*x],t[2*x+1])+lz[x];}
int qry(int x,int l,int r,int ql,int qr){if(qr<l||r<ql)return INT_MIN/2;if(ql<=l&&r<=qr)return t[x];
  int m=(l+r)/2;return max(qry(2*x,l,m,ql,qr),qry(2*x+1,m+1,r,ql,qr))+lz[x];}
int main(){scanf("%d %d",&n,&k);vector<int>a(n+1);for(int i=1;i<=n;i++)scanf("%d",&a[i]);
  vector<int>prev(n+1,0),last(n+1,0);for(int i=1;i<=n;i++){prev[i]=last[a[i]];last[a[i]]=i;}
  vector<int>dp(n+1,INT_MIN/2);dp[0]=0; // dp over j = number of boxes
  for(int j=1;j<=k;j++){t.assign(4*(n+1),0);lz.assign(4*(n+1),0);
    for(int i=0;i<=n;i++)add(1,0,n,i,i,dp[i]); // position p holds dp[p] + distinct(p+1..i)
    vector<int>nd(n+1,INT_MIN/2);
    for(int i=1;i<=n;i++){add(1,0,n,prev[i],i-1,1);nd[i]=qry(1,0,n,0,i-1);}
    dp=nd;}
  printf("%d\n",dp[n]);}

