typedef vector<vector<ll>> Mat;
Mat mul(const Mat&A,const Mat&B){Mat C(X,vector<ll>(X,0));for(int i=0;i<X;i++)for(int k=0;k<X;k++)if(A[i][k])for(int j=0;j<X;j++)C[i][j]=(C[i][j]+A[i][k]*B[k][j])%M;return C;}
int main(){int n;ll b;int k;scanf("%d %lld %d %d",&n,&b,&k,&X);int cnt[10]={0};for(int i=0;i<n;i++){int d;scanf("%d",&d);cnt[d]++;}
 Mat T(X,vector<ll>(X,0));for(int r=0;r<X;r++)for(int d=1;d<=9;d++)T[r][(r*10+d)%X]+=cnt[d]; // remainder r -> (10r+d)%X
 Mat R(X,vector<ll>(X,0));for(int i=0;i<X;i++)R[i][i]=1;
 while(b){if(b&1)R=mul(R,T);T=mul(T,T);b>>=1;}
 printf("%lld\n",R[0][k]);}

