typedef long long ll;const ll MOD=1e9+7;
int main(){int n,m;scanf("%d %d",&n,&m);vector<string>g(n);static char buf[2005];for(auto&s:g){scanf("%s",buf);s=buf;}
 if(n==1&&m==1){puts(g[0][0]=='.'?"1":"0");return 0;}
 // rr[i][j] = rocks in row i at columns >= j ; rd[i][j] = rocks in column j at rows >= i
 vector<vector<int>>rr(n+1,vector<int>(m+2,0)),rd(n+2,vector<int>(m+1,0));
 for(int i=n-1;i>=0;i--)for(int j=m-1;j>=0;j--){rr[i][j]=rr[i][j+1]+(g[i][j]=='R');rd[i][j]=rd[i+1][j]+(g[i][j]=='R');}
 // A = arrived moving down (next goes right), B = arrived moving right (next goes down); difference arrays
 vector<vector<ll>>A(n+1,vector<ll>(m+1,0)),B=A,dB(n+1,vector<ll>(m+2,0)),dA(n+2,vector<ll>(m+1,0));
 for(int i=0;i<n;i++){ll run=0;
  for(int j=0;j<m;j++){run=(run+dB[i][j])%MOD;if(i)dA[i][j]=(dA[i][j]+dA[i-1][j])%MOD;
   A[i][j]=dA[i][j];B[i][j]=run;if(i==0&&j==0)A[i][j]=B[i][j]=1;
   int lim=m-1-rr[i][j+1]; // furthest column reachable moving right from (i,j)
   if(lim>j&&A[i][j]){dB[i][j+1]=(dB[i][j+1]+A[i][j])%MOD;dB[i][lim+1]=(dB[i][lim+1]-A[i][j]+MOD)%MOD;}
   int limd=n-1-rd[i+1][j];
   if(limd>i&&B[i][j]){dA[i+1][j]=(dA[i+1][j]+B[i][j])%MOD;if(limd+1<=n)dA[limd+1][j]=(dA[limd+1][j]-B[i][j]+MOD)%MOD;}}}
 printf("%lld\n",(A[n-1][m-1]+B[n-1][m-1])%MOD);}

