 auto cmp=[&](int sub,char x,char y){if(sub)return sub;return x<y?1:(x>y?-1:0);};
 for(int len=2;len<=n;len+=2)for(int l=0;l+len-1<n;l++){int r=l+len-1;
  int a1=min(cmp(R(l+2,r),s[l],s[l+1]),cmp(R(l+1,r-1),s[l],s[r]));
  int a2=min(cmp(R(l+1,r-1),s[r],s[l]),cmp(R(l,r-2),s[r],s[r-1]));
  d[l][r]=max(a1,a2);}
 int v=d[0][n-1];cout<<(v>0?"Alice":v<0?"Bob":"Draw")<<"\n";}}

