int main(){int n,t;scanf("%d %d",&n,&t);vector<vector<int>>g(n+1);
 for(int i=0;i<n-1;i++){int u,v;scanf("%d %d",&u,&v);g[u].push_back(v);g[v].push_back(u);}
 vector<int>ord={1},par(n+1,0);par[1]=-1;
 for(int i=0;i<(int)ord.size();i++)for(int w:g[ord[i]])if(w!=par[ord[i]]){par[w]=ord[i];ord.push_back(w);}
 vector<int>down(n+1,0),cl(n+1,0),up(n+1,1),full(n+1,0); // up[v]=win status of parent side when entered from v (1 = win, root: none)
 for(int i=n-1;i>=0;i--){int v=ord[i];down[v]=cl[v]>0;if(par[v]>0&&!down[v])cl[par[v]]++;}
 for(int v:ord){int lose=cl[v]+(par[v]>0&&!up[v]?1:0);full[v]=lose>0;
  for(int c:g[v]){if(c==par[v])continue;int l2=lose-(!down[c]?1:0);up[c]=l2>0;}}
