#include <bits/stdc++.h>
using namespace std;typedef long long ll;
int main(){int n,k;scanf("%d %d",&n,&k);vector<vector<int>>g(n+1);for(int i=0;i<n-1;i++){int a,b;scanf("%d %d",&a,&b);g[a].push_back(b);g[b].push_back(a);}
 vector<int>ord={1},par(n+1,0);par[1]=-1;for(int i=0;i<(int)ord.size();i++)for(int w:g[ord[i]])if(w!=par[ord[i]]){par[w]=ord[i];ord.push_back(w);}
 vector<ll>sz(n+1,1);vector<array<ll,5>>c(n+1);for(int v=1;v<=n;v++){c[v].fill(0);c[v][0]=1;}
 ll dsum=0,extra=0;
 for(int i=n-1;i>=0;i--){int v=ord[i],p=par[v];if(p<=0)continue;
  dsum+=sz[v]*(n-sz[v]);
  // nodes in v's subtree have depth (rel p) = rel v + 1
  array<ll,5>sh;sh.fill(0);for(int r=0;r<k;r++)sh[(r+1)%k]+=c[v][r];
  for(int r1=0;r1<k;r1++)for(int r2=0;r2<k;r2++){int r=(r1+r2)%k;extra+=c[p][r1]*sh[r2]*((k-r)%k);}
  for(int r=0;r<k;r++)c[p][r]+=sh[r];sz[p]+=sz[v];}
 printf("%lld\n",(dsum+extra)/k);}

#include <bits/stdc++.h>
using namespace std;typedef long long ll;const ll M=1e9+7;typedef vector<vector<ll>> Mat;
Mat mul(const Mat&A,const Mat&B){int n=A.size();Mat C(n,vector<ll>(n,0));
  for(int i=0;i<n;i++)for(int k=0;k<n;k++)if(A[i][k])for(int j=0;j<n;j++)C[i][j]=(C[i][j]+A[i][k]*B[k][j])%M;return C;}
int main(){int n;ll k;cin>>n>>k;vector<ll>v(16,0);v[0]=1;
  for(int i=0;i<n;i++){ll a,b;int c;cin>>a>>b>>c;b=min(b,k);
    for(int y=c+1;y<16;y++)v[y]=0;
    Mat T(c+1,vector<ll>(c+1,0));for(int y=0;y<=c;y++)for(int d=-1;d<=1;d++)if(y+d>=0&&y+d<=c)T[y][y+d]=1;
    ll e=b-a;Mat R(c+1,vector<ll>(c+1,0));for(int y=0;y<=c;y++)R[y][y]=1;
    for(;e;e>>=1,T=mul(T,T))if(e&1)R=mul(R,T);
    vector<ll>nv(16,0);for(int y=0;y<=c;y++)for(int z=0;z<=c;z++)nv[z]=(nv[z]+v[y]*R[y][z])%M;v=nv;
    if(b==k)break;}
  cout<<v[0]<<endl;}

#include <bits/stdc++.h>
using namespace std;
struct R{bool win;int me,op;};
map<string,int>cnt;map<string,R>memo;
int val(const string&t){int s=0,m=0;for(char ch:t){s+=ch-'a'+1;m=max(m,ch-'a'+1);}return s*m+cnt[t];}
R solve(const string&s){auto it=memo.find(s);if(it!=memo.end())return it->second;
  R best{false,0,0};bool any=false;
  for(char ch='a';ch<='z';ch++)for(int side=0;side<2;side++){string t=side?s+ch:string(1,ch)+s;
    if(s.empty()&&side)continue;if(!cnt.count(t))continue;R sub=solve(t);
    R cand{!sub.win,val(t)+sub.op,sub.me};
    if(!any||cand.win>best.win||(cand.win==best.win&&(cand.me>best.me||(cand.me==best.me&&cand.op<best.op))))best=cand;any=true;}
  return memo[s]=best;}
int main(){int n;cin>>n;for(int i=0;i<n;i++){string w;cin>>w;set<string>sub;
    for(size_t a=0;a<w.size();a++)for(size_t l=1;a+l<=w.size();l++)sub.insert(w.substr(a,l));for(auto&x:sub)cnt[x]++;}
  R r=solve("");cout<<(r.win?"First":"Second")<<"\n"<<r.me<<" "<<r.op<<endl;}

#include <bits/stdc++.h>
using namespace std;typedef long long ll;const ll MOD=1e9+7;
int m,d;
ll cnt(const string&s){int n=s.size(); // count d-magic multiples of m in [10^(n-1), s]
  vector<ll>dp(m,0),nd;int trem=0;bool alive=true;
  for(int i=0;i<n;i++){nd.assign(m,0);int lo=i==0?1:0;
    for(int r=0;r<m;r++)if(dp[r])for(int c=lo;c<=9;c++){if(((i%2==1)==(c==d))){nd[(r*10+c)%m]=(nd[(r*10+c)%m]+dp[r])%MOD;}}
    if(alive){int sc=s[i]-'0';for(int c=lo;c<sc;c++)if((i%2==1)==(c==d))nd[(trem*10+c)%m]=(nd[(trem*10+c)%m]+1)%MOD;
      if((i%2==1)==(sc==d))trem=(trem*10+sc)%m;else alive=false;}
    dp=nd;}
  ll r=dp[0];if(alive&&trem==0)r=(r+1)%MOD;return r;}
bool ok(const string&s){int r=0;for(size_t i=0;i<s.size();i++){int c=s[i]-'0';if((i%2==1)!=(c==d))return false;r=(r*10+c)%m;}return r==0;}
int main(){string a,b;cin>>m>>d>>a>>b;cout<<((cnt(b)-cnt(a)+ok(a)+MOD)%MOD)<<endl;}

#include <bits/stdc++.h>
using namespace std;
int main(){static char buf[1000005];scanf("%s",buf);string s(buf);int n=s.size();
  vector<int>pi(n+11,0);vector<array<int,26>>aut(n); // aut[k][c]: next prefix length from state k (k<n)
  for(int i=1;i<n;i++){int k=pi[i-1];while(k&&s[i]!=s[k])k=pi[k-1];if(s[i]==s[k])k++;pi[i]=k;}
  for(int k=0;k<n;k++)for(int c=0;c<26;c++){if(s[k]-'a'==c)aut[k][c]=k+1;else aut[k][c]=k?aut[pi[k-1]][c]:0;}
  int q;scanf("%d",&q);string full=s;
  while(q--){scanf("%s",buf);string t(buf);full.resize(n);full+=t;
    for(int i=n;i<n+(int)t.size();i++){int k=pi[i-1];int c=full[i]-'a';
      while(k>=n){if(full[k]==full[i])break;k=pi[k-1];}
      if(k>=n)k=k+1;else k=(k<n)?aut[k][c]:0;pi[i]=k;printf("%d ",k);}
    puts("");}}

