int main(){int n,m,k;string a,b,s;cin>>n>>m>>k>>a>>b>>s;int dir=(b=="head")?-1:1,pos=k;
 vector<char>S(n+2,0);S[m]=1;
 auto mv=[&](){pos+=dir;if(pos==1||pos==n)dir=-dir;};
 for(int i=0;i<(int)s.size();i++){
  if(s[i]=='0'){vector<char>T(n+2,0);
   for(int p=1;p<=n;p++)if(S[p])for(int d=-1;d<=1;d++)if(p+d>=1&&p+d<=n)T[p+d]=1;
   T[pos]=0;mv();T[pos]=0;S=T;}
  else{if(i==(int)s.size()-1){puts("Stowaway");return 0;}
   mv();for(int p=1;p<=n;p++)S[p]=(p!=pos);}
  bool any=false;for(int p=1;p<=n;p++)any|=S[p];
  if(!any){printf("Controller %d\n",i+1);return 0;}}
 puts("Stowaway");}

