 int base[10],S=1;for(int d=0;d<10;d++){base[d]=S;S*=c[d]+1;} // mixed-radix state = how many of each digit used
 vector<vector<long long>>dp(S,vector<long long>(m,0));dp[0][0]=1;
 for(int s=0;s<S;s++)for(int r=0;r<m;r++){long long w=dp[s][r];if(!w)continue;
  for(int d=0;d<10;d++){int used=s/base[d]%(c[d]+1);if(used==c[d])continue;if(s==0&&d==0)continue; // no leading zero
   dp[s+base[d]][(r*10+d)%m]+=w;}}
