int main(){int len[5]={3,4,5,4,3},st[5]={2,1,0,1,2};map<pair<int,int>,int>id;int c=0; // cell (row, doubled column)
 for(int r=0;r<5;r++)for(int i=0;i<len[r];i++)id[{r,st[r]+2*i}]=c++;
 int board=0;for(int i=0;i<19;i++){char ch;cin>>ch;if(ch=='O')board|=1<<i;}
 vector<int>moves;int dr[3]={0,1,1},dx[3]={2,1,-1};
 for(auto&[p,v]:id)for(int d=0;d<3;d++){int mask=0;int r=p.first,x=p.second;
  while(id.count({r,x})){mask|=1<<id[{r,x}];moves.push_back(mask);r+=dr[d];x+=dx[d];}} // every segment along a line
 sort(moves.begin(),moves.end());moves.erase(unique(moves.begin(),moves.end()),moves.end());
 vector<char>win(1<<19,0);
 for(int s=1;s<(1<<19);s++)for(int m:moves)if((s&m)==m&&!win[s^m]){win[s]=1;break;}
