#include <bits/stdc++.h>
using namespace std;typedef long long ll;const ll M=1e9+7;typedef array<array<ll,3>,3> Mat;
Mat mul(const Mat&A,const Mat&B){Mat C{};for(int i=0;i<3;i++)for(int k=0;k<3;k++)for(int j=0;j<3;j++)C[i][j]=(C[i][j]+A[i][k]*B[k][j])%M;return C;}
array<ll,3> apply(array<ll,3>v,int mask,ll e){Mat T{};for(int r=0;r<3;r++)if(!(mask>>r&1))for(int p=max(0,r-1);p<=min(2,r+1);p++)T[r][p]=1;
  Mat R{};for(int i=0;i<3;i++)R[i][i]=1;for(;e;e>>=1,T=mul(T,T))if(e&1)R=mul(R,T);
  array<ll,3>o{};for(int i=0;i<3;i++)for(int j=0;j<3;j++)o[i]=(o[i]+R[i][j]*v[j])%M;return o;}
int main(){int n;ll m;cin>>n>>m;map<ll,array<int,3>>ev;
  for(int i=0;i<n;i++){int a;ll l,r;cin>>a>>l>>r;ev[l][a-1]++;ev[r+1][a-1]--;}
  array<ll,3>v={0,1,0};array<int,3>cnt={0,0,0};ll cur=1;
  for(auto&[p,d]:ev){if(p>m)break;int mask=0;for(int r=0;r<3;r++)if(cnt[r]>0)mask|=1<<r;
    v=apply(v,mask,p-1-cur);cur=p-1;for(int r=0;r<3;r++)cnt[r]+=d[r];}
  int mask=0;for(int r=0;r<3;r++)if(cnt[r]>0)mask|=1<<r;v=apply(v,mask,m-cur);
  cout<<v[1]<<endl;}

vector<int> zf(const string&s){int n=s.size();vector<int>z(n);z[0]=n;
 for(int i=1,l=0,r=0;i<n;i++){if(i<r)z[i]=min(r-i,z[i-l]);
  while(i+z[i]<n&&s[z[i]]==s[i+z[i]])z[i]++; if(i+z[i]>r)l=i,r=i+z[i];}return z;}
int solve(const string&s,int k){int n=s.size();auto z=zf(s);
 auto ok=[&](int L){if(L==0)return true;int c=0;for(int i=0;i<n;){if(z[i]>=L){c++;i+=L;}else i++;}return c>=k;};
 int lo=0,hi=n/k;while(lo<hi){int m=(lo+hi+1)/2;if(ok(m))lo=m;else hi=m-1;}return lo;}

#include <bits/stdc++.h>
using namespace std;
const int LG=17;int n;vector<int>dep,sz;vector<array<int,LG>>up;
int anc(int v,int k){for(int b=0;b<LG;b++)if(k>>b&1)v=up[v][b];return v;}
int lca(int a,int b){if(dep[a]<dep[b])swap(a,b);a=anc(a,dep[a]-dep[b]);if(a==b)return a;for(int b2=LG-1;b2>=0;b2--)if(up[a][b2]!=up[b][b2]){a=up[a][b2];b=up[b][b2];}return up[a][0];}
int main(){scanf("%d",&n);vector<vector<int>>g(n+1);for(int i=0;i<n-1;i++){int a,b;scanf("%d %d",&a,&b);g[a].push_back(b);g[b].push_back(a);}
 dep.assign(n+1,0);sz.assign(n+1,1);up.assign(n+1,{});vector<int>ord{1};up[1].fill(1);
 vector<char>vis(n+1,0);vis[1]=1;
 for(size_t i=0;i<ord.size();i++){int u=ord[i];for(int w:g[u])if(!vis[w]){vis[w]=1;dep[w]=dep[u]+1;up[w][0]=u;ord.push_back(w);}}
 for(int b=1;b<LG;b++)for(int v=1;v<=n;v++)up[v][b]=up[up[v][b-1]][b-1];
 for(int i=n-1;i>0;i--)sz[up[ord[i]][0]]+=sz[ord[i]];
 int m;scanf("%d",&m);while(m--){int x,y;scanf("%d %d",&x,&y);
  if(x==y){printf("%d\n",n);continue;}int l=lca(x,y),d=dep[x]+dep[y]-2*dep[l];
  if(d%2){puts("0");continue;}if(dep[x]<dep[y])swap(x,y);
  if(dep[x]==dep[y]){int cx=anc(x,dep[x]-dep[l]-1),cy=anc(y,dep[y]-dep[l]-1);printf("%d\n",n-sz[cx]-sz[cy]);} // midpoint is the lca
  else{int mid=anc(x,d/2),c=anc(x,d/2-1);printf("%d\n",sz[mid]-sz[c]);}}}

#include <bits/stdc++.h>
using namespace std;typedef long long ll;const ll M=1e9+7;
int d,n;vector<int>a;vector<vector<int>>g;
ll dfs(int v,int p,int r){ll res=1;for(int w:g[v]){if(w==p)continue;
  if(a[w]<a[r]||a[w]>a[r]+d||(a[w]==a[r]&&w<r))continue;res=res*(1+dfs(w,v,r))%M;}return res;}
int main(){scanf("%d %d",&d,&n);a.resize(n+1);g.resize(n+1);for(int i=1;i<=n;i++)scanf("%d",&a[i]);
 for(int i=0;i<n-1;i++){int u,v;scanf("%d %d",&u,&v);g[u].push_back(v);g[v].push_back(u);}
 ll ans=0;for(int r=1;r<=n;r++)ans=(ans+dfs(r,0,r))%M;printf("%lld\n",ans);}

