int main(){int t;scanf("%d",&t);while(t--){int n;scanf("%d",&n);vector<int>p(n+1);vector<vector<int>>ch(n+1);
 for(int i=2;i<=n;i++){scanf("%d",&p[i]);ch[p[i]].push_back(i);}
 vector<int>f(n+1,0);
 for(int v=n;v>=1;v--){auto&c=ch[v];if(c.empty()){f[v]=0;continue;}
  if(c.size()==1){f[v]=f[c[0]]+1;continue;}
  priority_queue<int,vector<int>,greater<int>>pq;for(int u:c)pq.push(f[u]);
  while(pq.size()>1){pq.pop();int b=pq.top();pq.pop();pq.push(b+1);} // round 2^a up to 2^b, merge
  f[v]=pq.top();}
 printf("%d\n",f[1]);}}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;const int LG=20;
int main(){int Q;scanf("%d",&Q);int N=Q+2;
 // up[j][v]: 2^j-th node in v's "next heavier-or-equal ancestor" chain; sm[j][v]: weight sum of those 2^j nodes
 vector<array<int,LG>>up(N);vector<array<ll,LG>>sm(N);vector<ll>w(N,0);
 const ll INF=LLONG_MAX/4;
 // node 0 = sentinel with infinite weight
 w[0]=INF;for(int j=0;j<LG;j++){up[0][j]=0;sm[0][j]=INF;}
 w[1]=0;for(int j=0;j<LG;j++){up[1][j]=0;sm[1][j]=INF;}
 int cnt=1;ll last=0;
 while(Q--){int tp;ll p,q;scanf("%d %lld %lld",&tp,&p,&q);int R=p^last;
  if(tp==1){ll W=q^last;int v=++cnt;w[v]=W;int u=R;
   if(w[u]<W){for(int j=LG-1;j>=0;j--)if(w[up[u][j]]<W)u=up[u][j];u=up[u][0];} // first chain node with weight >= W
   up[v][0]=u;sm[v][0]=(u==0?INF:w[u]);
   for(int j=1;j<LG;j++){up[v][j]=up[up[v][j-1]][j-1];ll a=sm[v][j-1],b=sm[up[v][j-1]][j-1];sm[v][j]=(a>=INF||b>=INF)?INF:min(INF,a+b);}}
  else{ll X=q^last;ll ans=0;int u=R;
   if(w[u]<=X){X-=w[u];ans=1;for(int j=LG-1;j>=0;j--)if(sm[u][j]<=X){X-=sm[u][j];ans+=1<<j;u=up[u][j];}}
   printf("%lld\n",ans);last=ans;}}}

