int main(){int t;scanf("%d",&t);while(t--){int n;scanf("%d",&n);vector<vector<int>>g(n+1);
 for(int i=0;i<n-1;i++){int u,v;scanf("%d %d",&u,&v);g[u].push_back(v);g[v].push_back(u);}
 vector<int> leaf(n+1),adj(n+1,0),good(n+1,0);long long L=0;
 for(int v=1;v<=n;v++){leaf[v]=g[v].size()==1;L+=leaf[v];}
 for(int v=1;v<=n;v++) if(!leaf[v]) for(int w:g[v]) if(leaf[w]) adj[v]=1;
 long long G=0;for(int v=1;v<=n;v++){good[v]=!leaf[v]&&!adj[v];G+=good[v];}
 long long ans=L*(n-L);
 // root at 1, sub[v]=good count in subtree
 vector<int> ord={1},par(n+1,0);par[1]=-1;
 for(int i=0;i<(int)ord.size();i++)for(int w:g[ord[i]])if(w!=par[ord[i]]){par[w]=ord[i];ord.push_back(w);}
 vector<long long> sub(n+1,0);for(int i=n-1;i>=0;i--){int v=ord[i];sub[v]+=good[v];if(par[v]>0)sub[par[v]]+=sub[v];}
 for(int q=1;q<=n;q++){ if(leaf[q])continue;
  for(int v:g[q]){ if(!adj[v])continue; // v non-leaf adjacent to leaf
   long long side = (v==par[q]) ? G-sub[q] : sub[v];
   ans+=side; } }
 printf("%lld\n",ans);}}

