using namespace std;
int dp[31][31][51];
int f(int n,int m,int k){if(k==0||k==n*m)return 0;int&r=dp[n][m][k];if(r>=0)return r;r=INT_MAX;
 for(int i=1;i<n;i++)for(int x=0;x<=k;x++)if(x<=i*m&&k-x<=(n-i)*m)r=min(r,m*m+f(i,m,x)+f(n-i,m,k-x)); // horizontal cut
 for(int j=1;j<m;j++)for(int x=0;x<=k;x++)if(x<=n*j&&k-x<=n*(m-j))r=min(r,n*n+f(n,j,x)+f(n,m-j,k-x)); // vertical cut
 return r;}
