int main(){int n,k,m;cin>>n>>k>>m;vector<vector<pair<int,int>>>g(n+2);
  for(int i=0;i<m;i++){int u,v,c;cin>>u>>v>>c;g[u].push_back({v,c});}
  if(k==1){cout<<0<<endl;return 0;}
  // dp[L][R][s]: open interval (L,R) still free; current vertex = L (s=0) or R (s=1)
  vector<vector<array<int,2>>>dp(n+2,vector<array<int,2>>(n+2,{INF,INF})),nd;
  for(int v=1;v<=n;v++){dp[v][n+1][0]=0;dp[0][v][1]=0;}
  for(int t=1;t<k;t++){nd.assign(n+2,vector<array<int,2>>(n+2,{INF,INF}));
    for(int L=0;L<=n+1;L++)for(int R=L+1;R<=n+1;R++)for(int s=0;s<2;s++){int cur=dp[L][R][s];if(cur>=INF)continue;
      int u=s?R:L;if(u<1||u>n)continue;
      for(auto[w,c]:g[u])if(L<w&&w<R){nd[L][w][1]=min(nd[L][w][1],cur+c);nd[w][R][0]=min(nd[w][R][0],cur+c);}}
    dp=nd;}
  int ans=INF;for(auto&r:dp)for(auto&x:r)ans=min({ans,x[0],x[1]});cout<<(ans>=INF?-1:ans)<<endl;}

