typedef long long ll;
int main(){int t;scanf("%d",&t);while(t--){int n;scanf("%d",&n);vector<ll>a(n+1);for(int i=1;i<=n;i++)scanf("%lld",&a[i]);
 vector<int>p(n+1,0);for(int i=2;i<=n;i++)scanf("%d",&p[i]);
 vector<priority_queue<ll,vector<ll>,greater<ll>>>pq(n+1);vector<ll>spare; // min-heaps of chain maxima
 for(int i=n;i>=1;i--){ // p_i < i, so children are processed first
  if(pq[i].empty())pq[i].push(a[i]);
  else{ll x=pq[i].top();pq[i].pop();pq[i].push(max(x,a[i]));spare.push_back(min(x,a[i]));} // join the weakest chain
  if(i>1){int q=p[i];if(pq[q].size()<pq[i].size())swap(pq[q],pq[i]); // small-to-large
   while(!pq[i].empty()){pq[q].push(pq[i].top());pq[i].pop();}}}
 int L=pq[1].size();ll sum=0;while(!pq[1].empty()){sum+=pq[1].top();pq[1].pop();}
 vector<ll>ans(n+1,-1);ans[L]=sum;sort(spare.rbegin(),spare.rend());
 for(int k=L+1;k<=n;k++){sum+=spare[k-L-1];ans[k]=sum;} // each extra group = one spare value as a singleton
 string o;for(int k=1;k<=n;k++)o+=to_string(ans[k])+" ";puts(o.c_str());}}

#include <bits/stdc++.h>
using namespace std;
int own[4][9];signed char memo[2][390625];
int enc(array<int,4>&st){int c=0;for(int s=0;s<4;s++)c=c*25+st[s];return c;}
// interval code: 0 empty, else 1 + l*6 + (h-3)
void dec(int c,int&l,int&h){c--;l=c/6;h=c%6+3;}
bool on(int code,int r){if(!code)return false;int l,h;dec(code,l,h);return r>=l&&r<=h;}
bool win(array<int,4>&st,int p){int key=enc(st);if(memo[p][key])return memo[p][key]==1;bool any=false,res=false;
 for(int s=0;s<4&&!res;s++)for(int r=0;r<9&&!res;r++){if(own[s][r]!=p||on(st[s],r))continue;int c=st[s],nc;
  if(!c){if(r!=3)continue;nc=1+3*6+0;}else{int l,h;dec(c,l,h);if(r==l-1)nc=1+r*6+(h-3);else if(r==h+1)nc=1+l*6+(r-3);else continue;}
  any=true;st[s]=nc;int cnt=0;for(int a=0;a<4;a++)for(int b=0;b<9;b++)if(own[a][b]==p&&on(st[a],b))cnt++;
  if(cnt==18||!win(st,1-p))res=true;st[s]=c;}
 if(!any)res=!win(st,1-p);memo[p][key]=res?1:2;return res;}
int main(){string R="6789TJQKA",S="CDSH";for(int p=0;p<2;p++)for(int i=0;i<18;i++){string c;cin>>c;own[S.find(c[1])][R.find(c[0])]=p;}
 array<int,4>st={0,0,0,0};cout<<(win(st,0)?"Alice":"Bob")<<"\n";}

