 for(int i=1;i<=n;i++)scanf("%lld",&sum[i]);vector<vector<int>>g(n+1);
 for(int i=0;i<n-1;i++){int u,v;scanf("%d %d",&u,&v);g[u].push_back(v);g[v].push_back(u);}
 vector<int>ord={1};for(int i=0;i<(int)ord.size();i++)for(int w:g[ord[i]])if(w!=par[ord[i]]){par[w]=ord[i];ord.push_back(w);}
