int main(){int t;scanf("%d",&t);while(t--){int n,m;scanf("%d %d",&n,&m);vector<ll>a(n+1);for(int i=1;i<=n;i++)scanf("%lld",&a[i]);
 vector<vector<int>>g(n+1);vector<int>indeg(n+1,0);for(int i=0;i<m;i++){int x,y;scanf("%d %d",&x,&y);g[x].push_back(y);indeg[y]++;}
 auto allz=[&](){for(int i=1;i<=n;i++)if(a[i])return false;return true;};
 int T=0;bool done=false;
 for(;T<n;T++){if(allz()){done=true;break;} // simulate first n seconds exactly
  vector<ll>na=a;for(int v=1;v<=n;v++)if(a[v]>0){na[v]--;for(int u:g[v])na[u]++;}a=na;}
 if(!done&&allz())done=true;
 if(done){printf("%d\n",T);continue;}
 // afterwards every node with flow stays positive: answer = n + total mass reaching the sink
 vector<int>ord;queue<int>q;for(int i=1;i<=n;i++)if(!indeg[i])q.push(i);
 vector<ll>f(n+1);for(int i=1;i<=n;i++)f[i]=a[i]%MOD;int sink=0;
 while(!q.empty()){int v=q.front();q.pop();if(g[v].empty())sink=v;for(int u:g[v]){f[u]=(f[u]+f[v])%MOD;if(--indeg[u]==0)q.push(u);}}
 printf("%lld\n",(f[sink]+n)%MOD);}}

