using namespace std;
int n,best=0;vector<int>r;vector<vector<int>>g;vector<int>tl; // tl = patience tails (strict LIS)
void dfs(int v,int p){
 int pos=lower_bound(tl.begin(),tl.end(),r[v])-tl.begin();bool app=(pos==(int)tl.size());int old=app?0:tl[pos];
 if(app)tl.push_back(r[v]);else tl[pos]=r[v];
 best=max(best,(int)tl.size());
 for(int u:g[v])if(u!=p)dfs(u,v);
 if(app)tl.pop_back();else tl[pos]=old;} // roll back
int main(){scanf("%d",&n);r.resize(n+1);for(int i=1;i<=n;i++)scanf("%d",&r[i]);g.resize(n+1);
 for(int i=1;i<n;i++){int a,b;scanf("%d %d",&a,&b);g[a].push_back(b);g[b].push_back(a);}
 for(int s=1;s<=n;s++){tl.clear();dfs(s,0);} // every path = root-to-node path from one of its ends
 printf("%d\n",best);}

