int n;vector<int>a;vector<vector<int>>pos;vector<int>idx; // idx[i] = rank of position i within its value's list
int check(int c){ // max #values taking c+1 copies (others take c), all 8 values used; -1 if impossible
 vector<vector<int>>dp(n+1,vector<int>(256,-1));dp[0][0]=0;int res=-1;
 for(int i=0;i<=n;i++)for(int mask=0;mask<256;mask++){int cur=dp[i][mask];if(cur<0)continue;
  if(mask==255){res=max(res,cur);continue;}
  if(i<n)dp[i+1][mask]=max(dp[i+1][mask],cur);   // skip a[i]
  if(i==n)continue;int v=a[i];if(mask>>v&1)continue;int k=idx[i];
  for(int take=c;take<=c+1;take++){if(take==0)continue;if(k+take-1<(int)pos[v].size()){int np=pos[v][k+take-1]+1;
    dp[np][mask|1<<v]=max(dp[np][mask|1<<v],cur+(take==c+1));}}}
 return res;}
int main(){cin>>n;a.resize(n);pos.assign(8,{});idx.resize(n);for(int i=0;i<n;i++){cin>>a[i];a[i]--;idx[i]=pos[a[i]].size();pos[a[i]].push_back(i);}
 int distinct=0;for(int v=0;v<8;v++)distinct+=!pos[v].empty();
 int lo=1,hi=n/8,ans=distinct; // c = 0: one card of each present value
 while(lo<=hi){int mid=(lo+hi)/2;int r=check(mid);if(r>=0){ans=max(ans,8*mid+r);lo=mid+1;}else hi=mid-1;}
 cout<<ans<<endl;}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;ll N;map<pair<ll,int>,int>memo;
bool big(ll a,int b){ll r=1;for(int i=0;i<b;i++){r*=a;if(r>=N)return true;}return false;} // a^b >= N ?
int f(ll a,int b){ // 1 = player to move wins, 0 = loses, 2 = draw
 if(a==1&&big(2,b))return 2;                     // adding a box loses, adding items is safe forever
 if(b==1&&big(a,2))return ((N-1-a)%2==1)?1:0;    // only box moves remain
 auto key=make_pair(a,b);auto it=memo.find(key);if(it!=memo.end())return it->second;
 bool draw=false,win=false;
 if(!big(a+1,b)){int r=f(a+1,b);if(r==0)win=true;if(r==2)draw=true;}
 if(!big(a,b+1)){int r=f(a,b+1);if(r==0)win=true;if(r==2)draw=true;}
 return memo[key]=win?1:(draw?2:0);}
int main(){ll a;int b;cin>>a>>b>>N;int r=f(a,b);puts(r==1?"Masha":r==0?"Stas":"Missing");} // prints the loser's name

