int main(){int n;scanf("%d",&n);vector<vector<int>>g(n+1);for(int i=1;i<n;i++){int u,v;scanf("%d %d",&u,&v);g[u].push_back(v);g[v].push_back(u);}
 vector<int>par(n+1,0),dep(n+1,0),ord={1};for(size_t i=0;i<ord.size();i++)for(int u:g[ord[i]])if(u!=par[ord[i]]){par[u]=ord[i];dep[u]=dep[ord[i]]+1;ord.push_back(u);}
 // A[v]: max-arranger, rank-from-top needed; B[v]: min-arranger. Even depth = first player (maximizer) moves.
 vector<int>A(n+1),B(n+1);int leaves=0;
 for(int k=n-1;k>=0;k--){int v=ord[k];bool leaf=true;int mnA=INT_MAX,sA=0,mnB=INT_MAX,sB=0;
  for(int u:g[v])if(u!=par[v]){leaf=false;mnA=min(mnA,A[u]);sA+=A[u];mnB=min(mnB,B[u]);sB+=B[u];}
  if(leaf){A[v]=B[v]=1;leaves++;continue;}
  if(dep[v]%2==0){A[v]=mnA;B[v]=sB;}else{A[v]=sA;B[v]=mnB;}}
 printf("%d %d\n",leaves-A[1]+1,B[1]);}

#include <bits/stdc++.h>
using namespace std;
// mask bit c*4+r: cell (row r, column i+c) of the 4x4 window starting at column i still has an uncleared '*'
int main(){int n;cin>>n;int a[5];for(int k=1;k<=4;k++)cin>>a[k];vector<string>g(4);for(auto&s:g)cin>>s;
 vector<pair<int,int>>sq;for(int k=1;k<=4;k++)for(int r=0;r+k<=4;r++){int m=0;for(int c=0;c<k;c++)for(int d=0;d<k;d++)m|=1<<(c*4+r+d);sq.push_back({m,a[k]});}
 map<int,int>best;for(int s=0;s<(1<<sq.size());s++){int m=0,c=0;for(size_t j=0;j<sq.size();j++)if(s>>j&1){m|=sq[j].first;c+=sq[j].second;}
  if(!best.count(m)||best[m]>c)best[m]=c;}
 vector<pair<int,int>>opt(best.begin(),best.end()); // the cheapest way to clear each pattern with squares starting in this column
 auto col=[&](int j){int m=0;if(j<n)for(int r=0;r<4;r++)if(g[r][j]=='*')m|=1<<r;return m;};
 const int INF=1e9;vector<int>dp(1<<16,INF),nd(1<<16,INF);int init=0;for(int c=0;c<4;c++)init|=col(c)<<(c*4);dp[init]=0;
 vector<int>live={init};
 for(int i=0;i<n;i++){vector<int>nl;
  for(int m:live){int v=dp[m];dp[m]=INF;for(auto&[cv,c]:opt){int r=m&~cv;if(r&15)continue;
    int nm=(r>>4)|(col(i+4)<<12);if(nd[nm]==INF)nl.push_back(nm);nd[nm]=min(nd[nm],v+c);}}
  swap(dp,nd);live=nl;}
 int ans=INF;for(int m:live)ans=min(ans,dp[m]);cout<<ans<<endl;}

