using namespace std;
int memo[102][102][2][2];
bool go(int o,int e,int s,int turn){
 if(o==0&&e==0)return s==0;int&r=memo[o][e][s][turn];if(r!=-1)return r;
 if(turn==0)r=(o>0&&go(o-1,e,s^1,1))||(e>0&&go(o,e-1,s,1));
 else r=(o==0||go(o-1,e,s,0))&&(e==0||go(o,e-1,s,0));
 return r;}
int main(){memset(memo,-1,sizeof memo);int t;scanf("%d",&t);while(t--){int n,o=0,e=0;scanf("%d",&n);
 for(int i=0;i<n;i++){long long x;scanf("%lld",&x);if(x%2)o++;else e++;}
 puts(go(o,e,0,0)?"Alice":"Bob");}}

#include <bits/stdc++.h>
using namespace std;
int n,m;vector<vector<char>>lk;
bool fr(int x,int y){return x>=0&&y>=0&&x<n&&y<m&&!lk[x][y];}
// count free cells walking from (x,y) (inclusive) alternating moves a,b,a,b...
long long walk(int x,int y,int ax,int ay,int bx,int by){long long c=0;int t=0;
 while(fr(x,y)){c++;if(t%2==0){x+=ax;y+=ay;}else{x+=bx;y+=by;}t++;}return c;}
long long through(int x,int y){ // staircases containing free cell (x,y)
 long long f1=walk(x,y,0,1,1,0),b1=walk(x,y,-1,0,0,-1); // line: ... down, (cell), right, down ...
 long long f2=walk(x,y,1,0,0,1),b2=walk(x,y,0,-1,-1,0); // line: ... right, (cell), down, right ...
 return f1*b1+f2*b2-1;}
int main(){int q;scanf("%d %d %d",&n,&m,&q);lk.assign(n,vector<char>(m,0));
 vector<vector<long long>>R(n+1,vector<long long>(m+1,0)),D=R;long long ans=0;
 for(int i=n-1;i>=0;i--)for(int j=m-1;j>=0;j--){R[i][j]=1+D[i][j+1];D[i][j]=1+R[i+1][j];ans+=R[i][j]+D[i][j]-1;}
 while(q--){int x,y;scanf("%d %d",&x,&y);x--;y--;
  if(!lk[x][y]){ans-=through(x,y);lk[x][y]=1;}else{lk[x][y]=0;ans+=through(x,y);}
  printf("%lld\n",ans);}}

