  void u(int a,int b){a=f(a);b=f(b);if(a==b)return;if(s[a]<s[b])swap(a,b);p[b]=a;s[a]+=s[b];}};
int main(){int n;scanf("%d",&n);D d0(n),d1(n);for(int i=0;i<n-1;i++){int x,y,c;scanf("%d %d %d",&x,&y,&c);(c?d1:d0).u(x,y);}
