  for(double d:D){double p=(d<=R)?1.0:(R==0?0.0:exp(1-d*d/(R*R)));
    for(int j=n;j>=0;j--)dp[j]=dp[j]*(1-p)+(j?dp[j-1]*p:0);}
  double fail=0;for(int j=0;j<K;j++)fail+=dp[j];return fail<=eps;}
