#include <bits/stdc++.h>
using namespace std;
char g[7][8];int par_;
bool bad(int i,int j){return g[i][j]=='B'&&g[i-1][j-1]=='B'&&g[i-1][j+1]=='B'&&g[i+1][j-1]=='B'&&g[i+1][j+1]=='B';}
// can we fix all violations of this parity class with <= d flips (black->white)?
bool dfs(int d){int ci=-1,cj=-1;
 for(int i=1;i<6&&ci<0;i++)for(int j=1;j<6;j++)if((i+j)%2==par_&&bad(i,j)){ci=i;cj=j;break;}
 if(ci<0)return true;if(d==0)return false;
 int di[5]={0,-1,-1,1,1},dj[5]={0,-1,1,-1,1}; // one of the 5 cells of the X must become white
 for(int q=0;q<5;q++){int x=ci+di[q],y=cj+dj[q];g[x][y]='W';bool ok=dfs(d-1);g[x][y]='B';if(ok)return true;}
 return false;}
int main(){int t;scanf("%d",&t);while(t--){for(int i=0;i<7;i++)scanf("%s",g[i]);int ans=0;
 for(par_=0;par_<2;par_++){int d=0;while(!dfs(d))d++;ans+=d;} // the two diagonal colour classes are independent
 printf("%d\n",ans);}}

