 const int NEG=-1e9;vector<int>dp(n+1,NEG),nd(n+1);dp[0]=0;
 for(int j=1;j<=k;j++){vector<int>best(p,NEG);fill(nd.begin(),nd.end(),NEG); // best[r] = max dp[t] with pre[t]==r
  for(int i=1;i<=n;i++){if(dp[i-1]>NEG)best[pre[i-1]]=max(best[pre[i-1]],dp[i-1]);
   for(int r=0;r<p;r++)if(best[r]>NEG)nd[i]=max(nd[i],best[r]+((pre[i]-r)%p+p)%p);}
  swap(dp,nd);}
 printf("%d\n",dp[n]);}

