  else{ // n==2: win[i][j] DP
    static bool w[300][300];
    for(int i=0;i<300;i++)for(int j=0;j<300;j++){bool r=false;
      for(int x=1;x<=i&&!r;x++)if(!w[i-x][j])r=true;
      for(int x=1;x<=j&&!r;x++)if(!w[i][j-x])r=true;
      for(int x=1;x<=min(i,j)&&!r;x++)if(!w[i-x][j-x])r=true;
      w[i][j]=r;}
    first=w[a[0]][a[1]];}
  cout<<(first?"BitLGM":"BitAryo")<<endl;}

#include <bits/stdc++.h>
using namespace std;typedef long long ll;
int main(){int n,k;cin>>n>>k;vector<ll>a(n);for(auto&x:a)cin>>x;sort(a.begin(),a.end());
  vector<ll>P(n+1,0);for(int i=0;i<n;i++)P[i+1]=P[i]+a[i];
  const ll NEG=LLONG_MIN/4;vector<vector<ll>>d(n+1,vector<ll>(k+1,NEG)); // d[i][j]: suffix from i, j pairs left
  for(int i=n;i>=0;i--)for(int j=0;j<=k;j++){if(j==0){d[i][j]=0;continue;}if(i==n)continue;
    ll b=d[i+1][j];for(int L=1;L<=j&&i+2*L<=n;L++){ll r=d[i+2*L][j-L];if(r==NEG)continue;
      b=max(b,(P[i+2*L]-P[i+L])-(P[i+L]-P[i])+r);}d[i][j]=b;}
  cout<<d[0][k]<<endl;}

#include <bits/stdc++.h>
using namespace std;
int main(){string s,t;cin>>s>>t;int n=s.size(),m=t.size();
  vector<vector<int>>d(n+1,vector<int>(m+1));
  for(int i=0;i<=n;i++)for(int j=0;j<=m;j++){
    if(!i||!j){d[i][j]=i+j;continue;}
    d[i][j]=min({d[i-1][j-1]+(s[i-1]!=t[j-1]),d[i-1][j]+1,d[i][j-1]+1});}
  vector<string>ops;int i=n,j=m;
  while(i||j){
    if(i&&j&&d[i][j]==d[i-1][j-1]+(s[i-1]!=t[j-1])){
      if(s[i-1]!=t[j-1])ops.push_back("REPLACE "+to_string(i)+" "+t[j-1]);i--;j--;}
    else if(i&&d[i][j]==d[i-1][j]+1){ops.push_back("DELETE "+to_string(i));i--;}
    else{ops.push_back("INSERT "+to_string(i+1)+" "+t[j-1]);j--;}}
  printf("%d\n",(int)ops.size());for(auto&o:ops)puts(o.c_str());}

#include <bits/stdc++.h>
using namespace std;
int main(){int T;cin>>T;while(T--){string s,t;cin>>s>>t;int n=s.size(),m=t.size();bool ok=false;
  for(int k=0;k<=m&&!ok;k++){string a=t.substr(0,k),b=t.substr(k);int A=a.size(),B=b.size();
    vector<int>dp(A+1,-1);dp[0]=0; // dp[j]: max chars of b matched with j chars of a matched
    for(int i=0;i<n;i++)for(int j=A;j>=0;j--){if(dp[j]<0)continue;int v=dp[j];
      if(j<A&&s[i]==a[j])dp[j+1]=max(dp[j+1],v);if(v<B&&s[i]==b[v])dp[j]=max(dp[j],v+1);}
    if(dp[A]>=B)ok=true;}
  puts(ok?"YES":"NO");}}
